)
values
  (1, 'Haferbrei mit Früchten und Nüssen', 'Frühstück', 'Dieser nahrhafte Frühstücksbrei gibt Ihnen dank seines ausgewogenen Gehalts an Eiweiß, Fett und Kohlenhydraten die nötige Energie für den Morgen. Guten Appetit!', '[{"name":"Haferflocken","menge_anzeige":"25 g","gramm":25},{"name":"Milch oder Wasser","menge_anzeige":"100 ml","gramm":100},{"name":"Apfel","menge_anzeige":"50 g","gramm":50},{"name":"Banane","menge_anzeige":"30 g","gramm":30},{"name":"Nüsse (Walnüsse oder Mandeln)","menge_anzeige":"5 g","gramm":5},{"name":"Honig","menge_anzeige":"7 g","gramm":7},{"name":"Zimt","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Milch oder Wasser zum Kochen bringen. 2. Haferflocken hinzufügen und bei schwacher Hitze 5–7 Minuten unter gelegentlichem Rühren kochen. 3. Apfel und Banane in Würfel schneiden. 4. Den Brei mit Früchten und Nüssen mischen. 5. Honig hinzufügen und mit Zimt bestreuen.', 1, 'Die Zutatenmenge ergibt mit 246 kcal genau eine für ein Frühstück übliche Portion, nahe am alten Wert von 250 kcal.', 246, 245, 8, 39, 7, 'Haferflocken 25 g = 93 kcal; Milch 100 ml (1,5% Fett, Annahme: ''Milch oder Wasser'' mit Milch gerechnet) = 47 kcal; Apfel 50 g = 26 kcal; Banane 30 g = 27 kcal; Nüsse (Walnuss) 5 g = 33 kcal; Honig 7 g = 21 kcal; Zimt nach Geschmack = 0 kcal; Summe = 246 kcal'),
  (2, 'Smoothie mit Avocado und Spinat', 'Frühstück', 'Dieser Smoothie mit Avocado und Spinat ist ein ausgezeichneter Start in den Tag, reich an Vitaminen und Mineralstoffen. Guten Appetit!', '[{"name":"Avocado","menge_anzeige":"90 g","gramm":90},{"name":"Spinat","menge_anzeige":"100 g","gramm":100},{"name":"Banane","menge_anzeige":"50 g","gramm":50},{"name":"Kokoswasser","menge_anzeige":"200 ml","gramm":200},{"name":"Zitronensaft","menge_anzeige":"1 EL (15 ml)","gramm":15}]'::jsonb, '1. Avocado und Banane schälen. 2. Alle Zutaten in den Mixer geben. 3. Bis zur glatten Konsistenz mixen.', 1, 'Die Menge ergibt mit 253 kcal eine einzelne Smoothie-Portion, konsistent mit dem alten Wert von 250 kcal.', 253, 255, 7, 32, 14, 'Avocado 90 g = 144 kcal; Spinat 100 g = 23 kcal; Banane 50 g = 45 kcal; Kokoswasser 200 ml = 38 kcal; Zitronensaft 15 ml = 3 kcal; Summe = 253 kcal'),
  (3, 'Griechischer Joghurt mit Honig und Beeren', 'Frühstück', 'Dieser griechische Joghurt mit Honig und Beeren ist ideal zum Frühstück oder als Snack. Guten Appetit!', '[{"name":"Griechischer Joghurt","menge_anzeige":"200 g","gramm":200},{"name":"Honig","menge_anzeige":"1 EL (20 g)","gramm":20},{"name":"Beeren (Blaubeeren, Himbeeren, Erdbeeren)","menge_anzeige":"80 g","gramm":80}]'::jsonb, '1. Joghurt in eine Schüssel geben. 2. Mit Honig übergießen. 3. Beeren hinzufügen.', 1, '200 g Joghurt mit Toppings entsprechen einer üblichen Frühstücksschale für eine Person.', 363, 365, 13, 30, 20, 'Griechischer Joghurt (10% Fett, Annahme) 200 g = 266 kcal; Honig 20 g = 61 kcal; Beeren 80 g = 36 kcal; Summe = 363 kcal'),
  (4, 'Fladenbrot mit Käse, Wurst, Eiern und Tomaten', 'Frühstück', 'Dieses Fladenbrot mit Käse, Wurst, Eiern und Tomaten ist eine schnelle und leckere Möglichkeit, ein sättigendes Gericht zuzubereiten. Guten Appetit!', '[{"name":"Fladenbrot","menge_anzeige":"1 Blatt (ca. 90 g, Annahme)","gramm":90},{"name":"Ei","menge_anzeige":"4 Stk (220 g)","gramm":220},{"name":"Wurst oder Schinken","menge_anzeige":"50 g","gramm":50},{"name":"Käse (hart)","menge_anzeige":"50 g","gramm":50},{"name":"Tomate","menge_anzeige":"1 Stk (100 g)","gramm":100},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Olivenöl","menge_anzeige":"1 TL (4 g)","gramm":4},{"name":"Frische Kräuter zum Garnieren","menge_anzeige":"optional","gramm":null}]'::jsonb, '1. Wurst oder Schinken und Tomate in kleine Würfel schneiden. 2. Käse reiben. 3. Ein Ei mit Salz und Pfeffer verquirlen. 4. Olivenöl in einer Pfanne bei mittlerer Hitze erhitzen. 5. Das Ei in die Pfanne geben und unter Rühren halb garen. 6. Wurst und Tomate hinzufügen, umrühren und weitere 1–2 Minuten kochen. 7. Fladenbrot auf eine flache Fläche legen. 8. Die Ei-Mischung gleichmäßig auf dem Fladenbrot verteilen. 9. Mit geriebenem Käse bestreuen. 10. Die restlichen drei Eier daraufgeben. 11. In einer Pfanne goldbraun braten. 12. Heiß servieren, optional mit frischen Kräutern garnieren.', 2, 'Bei 4 Eiern und einem ganzen Fladenbrot ergeben sich 900 kcal für das Gesamtgericht – aufgeteilt auf 2 Portionen (450 kcal) liegt der Wert im typischen Hauptgericht-Bereich und näher am alten Wert von 578 kcal als bei 1 Portion.', 900, 450, 31, 28, 24, 'Fladenbrot 90 g (Gewichts-Annahme) = 243 kcal; Ei 220 g (4 Stk) = 341 kcal; Wurst/Schinken 50 g = 73 kcal; Käse (hart) 50 g = 190 kcal; Tomate 100 g = 18 kcal; Olivenöl 4 g = 35 kcal; Salz/Pfeffer/Kräuter nach Geschmack = 0 kcal; Summe = 900 kcal; Summe/2 Portionen = 450 kcal'),
  (5, 'Omelett mit Gemüse und Kräutern', 'Frühstück', 'Dieses Omelett mit Gemüse und Kräutern ist ein leckeres und nahrhaftes Gericht, das sich leicht zum Frühstück oder Abendessen zubereiten lässt. Guten Appetit!', '[{"name":"Eier","menge_anzeige":"3 Stk (150 g)","gramm":150},{"name":"Milch","menge_anzeige":"50 ml","gramm":50},{"name":"Paprika","menge_anzeige":"1 Stk (100 g)","gramm":100},{"name":"Tomate","menge_anzeige":"1 Stk (120 g)","gramm":120},{"name":"Spinat","menge_anzeige":"50 g","gramm":50},{"name":"Frühlingszwiebeln","menge_anzeige":"1 Bund (30 g)","gramm":30},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Olivenöl","menge_anzeige":"1 TL (4 g)","gramm":4}]'::jsonb, '1. Eier mit Milch verquirlen. 2. Gemüse und Kräuter schneiden. 3. Gemüse in Olivenöl 2–3 Minuten anbraten. 4. Eimischung hinzufügen und das Omelett unter gelegentlichem Rühren garen.', 1, 'Die Zutatenmenge (3 Eier) ergibt mit 360 kcal eine einzelne Omelett-Portion, nahe am alten Wert von 356 kcal.', 360, 360, 25, 15, 22, 'Eier 150 g = 233 kcal; Milch 50 ml (1,5%) = 24 kcal; Paprika 100 g = 26 kcal; Tomate 120 g = 22 kcal; Spinat 50 g = 12 kcal; Frühlingszwiebeln 30 g = 10 kcal; Olivenöl 4 g = 35 kcal; Salz/Pfeffer nach Geschmack = 0 kcal; Summe = 360 kcal'),
  (6, 'Frittata mit Gemüse und Hühnerbrust', 'Frühstück', 'Diese Frittata mit Gemüse und Hühnerbrust ist ein nahrhaftes und leckeres Gericht, ideal für ein gesundes Frühstück oder ein leichtes Abendessen. Guten Appetit!', '[{"name":"Eier","menge_anzeige":"2 Stk (100 g)","gramm":100},{"name":"Hühnerbrust (gekocht)","menge_anzeige":"100 g","gramm":100},{"name":"Spinat","menge_anzeige":"50 g","gramm":50},{"name":"Paprika","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Cherrytomaten","menge_anzeige":"5 Stk (75 g)","gramm":75},{"name":"Zwiebel","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Olivenöl","menge_anzeige":"1 TL (4 g)","gramm":4},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Ofen auf 180 °C vorheizen. 2. Hühnerbrust und Gemüse in Würfel schneiden. 3. Eier mit Salz und Pfeffer verquirlen. 4. Zwiebeln in Olivenöl goldbraun anbraten. 5. Paprika und Spinat hinzufügen und anbraten. 6. Hühnerbrust und Cherrytomaten hinzufügen. 7. Eimischung in die Pfanne geben und anbraten, bis die Eier leicht stocken. 8. Pfanne in den Ofen geben und backen, bis die Eier vollständig gestockt sind (ca. 10 Minuten). 9. Heiß servieren.', 1, 'Die Menge ergibt mit 413 kcal eine Portion, was gut zum alten Wert von 407 kcal passt.', 413, 415, 47, 12, 19, 'Eier 100 g = 155 kcal; Hühnerbrust (gekocht) 100 g = 165 kcal; Spinat 50 g = 12 kcal; Paprika 50 g = 13 kcal; Cherrytomaten 75 g = 14 kcal; Zwiebel 50 g = 20 kcal; Olivenöl 4 g = 35 kcal; Salz/Pfeffer nach Geschmack = 0 kcal; Summe = 413 kcal'),
  (7, 'Shakshuka mit Eiern', 'Frühstück', 'Diese Shakshuka mit Eiern ist ein schmackhaftes und nahrhaftes Gericht, ideal für Frühstück oder ein leichtes Mittagessen. Guten Appetit!', '[{"name":"Eier","menge_anzeige":"2 Stk (100 g)","gramm":100},{"name":"Tomaten","menge_anzeige":"2 Stk (200 g)","gramm":200},{"name":"Paprika","menge_anzeige":"1 Stk (100 g)","gramm":100},{"name":"Zwiebel","menge_anzeige":"1 Stk (100 g)","gramm":100},{"name":"Knoblauch","menge_anzeige":"2 Zehen (10 g)","gramm":10},{"name":"Olivenöl","menge_anzeige":"1 EL (10 g)","gramm":10},{"name":"Tomatenmark","menge_anzeige":"1 EL (20 g)","gramm":20},{"name":"Gewürze (Paprika, Kreuzkümmel, Salz, Pfeffer)","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frischer Koriander oder Petersilie","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Zwiebel, Knoblauch und Paprika schneiden. 2. Zwiebeln und Knoblauch in Olivenöl anbraten, bis sie weich sind. 3. Paprika hinzufügen und 5 Minuten weiterkochen. 4. Tomaten in Würfel schneiden und zusammen mit Tomatenmark und Gewürzen hinzufügen. 5. Bei mittlerer Hitze kochen, bis die Sauce eindickt (ca. 10 Minuten). 6. Zwei Mulden in der Sauce machen und die Eier vorsichtig hineinschlagen. 7. Pfanne abdecken und die Eier garen, bis sie die gewünschte Konsistenz erreicht haben (ca. 5–7 Minuten). 8. Mit frischen Kräutern bestreuen und servieren.', 1, 'Die Zutatenmenge ergibt mit 377 kcal eine Portion Shakshuka, nahe am alten Wert von 395 kcal.', 377, 375, 18, 27, 22, 'Eier 100 g = 155 kcal; Tomaten 200 g = 36 kcal; Paprika 100 g = 26 kcal; Zwiebel 100 g = 40 kcal; Knoblauch 10 g = 15 kcal; Olivenöl 10 g = 88 kcal; Tomatenmark 20 g = 16 kcal; Gewürze/Kräuter nach Geschmack = 0 kcal; Summe = 377 kcal'),
  (8, 'Avocado-Toast mit Lachs und pochiertem Ei', 'Frühstück', 'Diese Avocado-Toast mit Lachs und pochiertem Ei ist ein nahrhaftes und schmackhaftes Gericht, ideal für Frühstück oder ein leichtes Mittagessen. Guten Appetit!', '[{"name":"Vollkornbrot","menge_anzeige":"2 Scheiben (60 g)","gramm":60},{"name":"Avocado","menge_anzeige":"1/2 Stk (70 g)","gramm":70},{"name":"Räucherlachs","menge_anzeige":"50 g","gramm":50},{"name":"Ei","menge_anzeige":"1 Stk (50 g)","gramm":50},{"name":"Zitronensaft","menge_anzeige":"1 TL (5 ml)","gramm":5},{"name":"Frischer Dill","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Olivenöl","menge_anzeige":"1 TL (4 g), für die Toasts","gramm":4},{"name":"Wasser","menge_anzeige":"500 ml (zum Pochieren, nicht Teil der Nährwertberechnung)","gramm":null}]'::jsonb, '1. Brot auf einer trockenen Pfanne oder im Toaster rösten und leicht mit Olivenöl bestreichen. 2. Avocado schälen und zerdrücken, Zitronensaft, Salz und Pfeffer hinzufügen. 3. Avocado auf die Toasts streichen. 4. Wasser in einem kleinen Topf zum Kochen bringen, dann die Hitze reduzieren. 5. Ei in eine Tasse schlagen und vorsichtig ins Wasser gleiten lassen. 6. Ei 3–4 Minuten kochen, dann vorsichtig mit einem Schaumlöffel herausnehmen und abtropfen lassen. 7. Räucherlachs auf die Toasts mit Avocado legen. 8. Pochiertes Ei daraufgeben. 9. Mit frischem Dill bestreuen und nach Belieben mit Salz und Pfeffer würzen.', 1, 'Ein Toast mit Belag und Ei ergibt mit 433 kcal eine Portion, nahe am alten Wert von 463 kcal.', 433, 435, 22, 32, 24, 'Vollkornbrot 60 g = 148 kcal; Avocado 70 g = 112 kcal; Räucherlachs 50 g = 59 kcal; Ei 50 g = 78 kcal; Zitronensaft 5 ml = 1 kcal; Olivenöl 4 g = 35 kcal; Dill/Salz/Pfeffer nach Geschmack = 0 kcal; Kochwasser nicht mitgerechnet; Summe = 433 kcal'),
  (9, 'Pfannenpizza', 'Frühstück', 'Diese Pfannenpizza ist eine einfache und schnelle Möglichkeit, ein leckeres Gericht ohne großen Aufwand zuzubereiten. Guten Appetit!', '[{"name":"Ei","menge_anzeige":"1 Stk (55 g)","gramm":55},{"name":"Mehl","menge_anzeige":"3 EL (45 g)","gramm":45},{"name":"Milch","menge_anzeige":"3 EL (45 ml)","gramm":45},{"name":"Salz","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Tomatensauce","menge_anzeige":"2 EL (30 g)","gramm":30},{"name":"Wurst oder Schinken","menge_anzeige":"50 g","gramm":50},{"name":"Käse (hart)","menge_anzeige":"50 g","gramm":50},{"name":"Tomaten","menge_anzeige":"1 Stk (100 g)","gramm":100},{"name":"Oliven oder schwarze Oliven","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Olivenöl","menge_anzeige":"1 TL (4 g)","gramm":4},{"name":"Frische Kräuter zum Garnieren","menge_anzeige":"optional","gramm":null}]'::jsonb, '1. Ei in einer Schüssel verquirlen, Mehl, Milch und Salz hinzufügen und gut vermischen. 2. Pfanne mit Olivenöl bei mittlerer Hitze erhitzen. 3. Teig in die Pfanne gießen und gleichmäßig verteilen. 4. Teig 2–3 Minuten backen, bis die Unterseite fest ist. 5. Teig mit Tomatensauce bestreichen. 6. Wurst oder Schinken, Tomaten und Oliven schneiden. 7. Belag auf dem Teig verteilen. 8. Optional mit geriebenem Käse bestreuen. 9. Pfanne abdecken und bei schwacher Hitze weitere 5–7 Minuten backen, bis der Käse geschmolzen und goldbraun ist. 10. Heiß servieren, optional mit frischen Kräutern garnieren.', 1, 'Die Pfannenpizza ergibt mit 588 kcal eine sättigende Hauptmahlzeit für eine Person, was in den Bereich des alten Werts von 658 kcal fällt.', 588, 590, 38, 40, 29, 'Ei 55 g = 85 kcal; Mehl 45 g = 157 kcal; Milch 45 ml = 21 kcal; Tomatensauce 30 g = 9 kcal; Wurst/Schinken 50 g = 73 kcal; Käse (hart) 50 g = 190 kcal; Tomaten 100 g = 18 kcal; Olivenöl 4 g = 35 kcal; Salz/Oliven/Kräuter nach Geschmack = 0 kcal; Summe = 588 kcal'),
  (10, 'Quarkauflauf mit Beeren', 'Frühstück', 'Dieser Quarkauflauf mit Beeren ist ein leckeres und gesundes Gericht, das sich gut zum Frühstück oder als leichtes Dessert eignet. Guten Appetit!', '[{"name":"Magerquark","menge_anzeige":"500 g","gramm":500},{"name":"Eier","menge_anzeige":"2 Stk (100 g)","gramm":100},{"name":"Honig","menge_anzeige":"2 EL (42 g)","gramm":42},{"name":"Vanille","menge_anzeige":"1 TL (4 g)","gramm":4},{"name":"Beeren (Blaubeeren, Himbeeren)","menge_anzeige":"200 g","gramm":200}]'::jsonb, '1. Eier mit Honig und Vanille verquirlen. 2. Quark mit der Eimischung vermischen. 3. Beeren hinzufügen und vorsichtig unterheben. 4. Mischung in eine Auflaufform geben. 5. Bei 180 °C ca. 30 Minuten backen, bis die Oberfläche goldbraun ist.', 1, '500 g Magerquark als Auflauf ergeben mit 708 kcal eine große Portion, nahe am alten Wert von 654 kcal.', 708, 710, 80, 68, 13, 'Magerquark 500 g = 335 kcal; Eier 100 g = 155 kcal; Honig 42 g = 128 kcal; Vanille 4 g = 0 kcal (Annahme: reines Aroma ohne relevante Kalorien); Beeren 200 g = 90 kcal; Summe = 708 kcal'),
  (11, 'Protein-Smoothie mit Beeren und Banane', 'Frühstück', 'Dieser Protein-Smoothie mit Beeren und Banane ist eine perfekte Option für einen gesunden und nahrhaften Snack nach dem Training oder zum Frühstück. Guten Appetit!', '[{"name":"Proteinpulver (Molken- oder Pflanzenprotein)","menge_anzeige":"1 Messlöffel (30 g)","gramm":30},{"name":"Banane","menge_anzeige":"1 Stk (120 g)","gramm":120},{"name":"Gefrorene Beeren (Blaubeeren, Himbeeren, Erdbeeren)","menge_anzeige":"150 g","gramm":150},{"name":"Mandelmilch","menge_anzeige":"200 ml","gramm":200},{"name":"Leinsamen","menge_anzeige":"1 EL (10 g)","gramm":10},{"name":"Eis","menge_anzeige":"optional","gramm":null}]'::jsonb, '1. Alle Zutaten im Mixer zu einer glatten Masse mixen. 2. Bei Bedarf Eis hinzufügen, um den Smoothie zu kühlen. 3. Sofort servieren.', 1, 'Die Zutatenmenge ergibt mit 372 kcal einen einzelnen Smoothie, nahe am alten Wert von 381 kcal.', 372, 370, 28, 45, 9, 'Proteinpulver 30 g = 114 kcal; Banane 120 g = 107 kcal; Gefrorene Beeren 150 g = 68 kcal; Mandelmilch (ungesüßt, Annahme) 200 ml = 30 kcal; Leinsamen 10 g = 53 kcal; Eis optional = 0 kcal; Summe = 372 kcal'),
  (12, 'Syrniki mit Magerquark (mit Süßstoff)', 'Frühstück', 'Diese Syrniki mit Magerquark und Süßstoff sind eine ideale Option für ein gesundes und leckeres Frühstück oder einen Snack. Guten Appetit!', '[{"name":"Magerquark","menge_anzeige":"125 g","gramm":125},{"name":"Ei","menge_anzeige":"1/4 Stk (ca. 12,5 g)","gramm":12.5},{"name":"Mehl","menge_anzeige":"1 EL (15 g)","gramm":15},{"name":"Süßstoff","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Salz","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Öl zum Braten","menge_anzeige":"1/4 EL (ca. 4 ml)","gramm":4}]'::jsonb, '1. Quark mit Ei, Mehl, Süßstoff und Salz zu einer glatten Masse vermischen. 2. Kleine Kugeln formen und zu Syrniki flachdrücken. 3. Syrniki in einer vorgeheizten Pfanne mit Öl von beiden Seiten goldbraun braten. 4. Heiß servieren.', 1, 'Die kleine Menge (125 g Quark) ergibt mit 191 kcal eine Portion Syrniki für eine Person, nahe am alten Wert von 211 kcal.', 191, 190, 19, 15, 6, 'Magerquark 125 g = 84 kcal; Ei 12,5 g = 19 kcal; Mehl 15 g = 52 kcal; Öl zum Braten 4 g = 35 kcal; Süßstoff/Salz nach Geschmack = 0 kcal; Summe = 191 kcal'),
  (13, 'Protein-Pfannkuchen mit Quark und Beeren', 'Frühstück', 'Diese Protein-Pfannkuchen mit Quark und Beeren sind ein ideales Frühstück für alle, die auf ihre Ernährung achten und den Tag mit einem leckeren und gesunden Gericht beginnen möchten. Guten Appetit!', '[{"name":"Proteinpulver (Molken- oder Pflanzenprotein)","menge_anzeige":"1 Messlöffel (30 g)","gramm":30},{"name":"Eier","menge_anzeige":"2 Stk (100 g)","gramm":100},{"name":"Haferflocken","menge_anzeige":"30 g","gramm":30},{"name":"Milch (fettarm)","menge_anzeige":"100 ml","gramm":100},{"name":"Magerquark","menge_anzeige":"100 g","gramm":100},{"name":"Beeren (Blaubeeren, Himbeeren, Erdbeeren)","menge_anzeige":"100 g","gramm":100},{"name":"Olivenöl","menge_anzeige":"1 TL (4 g)","gramm":4},{"name":"Honig","menge_anzeige":"1 TL (7 g)","gramm":7}]'::jsonb, '1. Proteinpulver, Eier, Haferflocken und Milch im Mixer zu einer glatten Masse mixen. 2. Pfanne mit Olivenöl erhitzen. 3. Teig in kleinen Portionen in die Pfanne geben und Pfannkuchen von beiden Seiten goldbraun braten. 4. Fertige Pfannkuchen auf einen Teller legen, Quark und Beeren hinzufügen. 5. Vor dem Servieren mit Honig beträufeln.', 1, 'Die Zutatenmenge ergibt mit 596 kcal eine Portion Pfannkuchen, nahe am alten Wert von 605 kcal.', 596, 595, 57, 43, 21, 'Proteinpulver 30 g = 114 kcal; Eier 100 g = 155 kcal; Haferflocken 30 g = 111 kcal; Milch (fettarm) 100 ml = 47 kcal; Magerquark 100 g = 67 kcal; Beeren 100 g = 45 kcal; Olivenöl 4 g = 35 kcal; Honig 7 g = 21 kcal; Summe = 596 kcal'),
  (14, 'Smoothie Bowl mit Beeren und Nüssen', 'Frühstück', 'Diese Smoothie-Bowl mit Beeren und Nüssen ist eine perfekte Wahl für ein nahrhaftes und leckeres Frühstück oder einen Snack.', '[{"name":"Gefrorene Beeren (Blaubeeren, Himbeeren, Erdbeeren)","menge_anzeige":"150 g","gramm":150},{"name":"Banane","menge_anzeige":"1 Stk (120 g)","gramm":120},{"name":"Griechischer Joghurt","menge_anzeige":"100 g","gramm":100},{"name":"Mandelmilch","menge_anzeige":"100 ml","gramm":100},{"name":"Granola","menge_anzeige":"30 g","gramm":30},{"name":"Mandeln","menge_anzeige":"20 g","gramm":20},{"name":"Kokosraspeln","menge_anzeige":"1 EL (5 g)","gramm":5},{"name":"Frische Beeren","menge_anzeige":"zum Garnieren, nach Geschmack","gramm":null},{"name":"Minzblätter","menge_anzeige":"zum Garnieren, nach Geschmack","gramm":null}]'::jsonb, '1. Gefrorene Beeren, Banane, griechischen Joghurt und Mandelmilch im Mixer zu einer glatten Masse mixen. 2. Mischung in eine Schüssel geben. 3. Mit Granola, Mandeln, Kokosraspeln und frischen Beeren bestreuen und mit Minzblättern garnieren. 4. Sofort servieren.', 1, 'Die Menge ergibt eine große Frühstücksschüssel für eine Person; 589 kcal liegen im oberen Bereich des Frühstücks-Richtwerts.', 589, 590, 14, 69, 31, 'Gefrorene Beeren 150 g = 63 kcal; Banane 120 g = 107 kcal; Griechischer Joghurt 100 g = 115 kcal; Mandelmilch 100 ml = 15 kcal; Granola 30 g = 141 kcal; Mandeln 20 g = 115 kcal; Kokosraspeln 5 g = 33 kcal; Summe = 589 kcal'),
  (15, 'Vollkorn-Pfannkuchen mit Banane', 'Frühstück', 'Diese Vollkorn-Pfannkuchen mit Banane sind ein leckeres und nahrhaftes Frühstück, das der ganzen Familie schmecken wird. Guten Appetit!', '[{"name":"Vollkornmehl","menge_anzeige":"50 g","gramm":50},{"name":"Banane","menge_anzeige":"1 Stk (120 g)","gramm":120},{"name":"Ei","menge_anzeige":"1 Stk (50 g)","gramm":50},{"name":"Milch (fettarm)","menge_anzeige":"100 ml","gramm":100},{"name":"Backpulver","menge_anzeige":"1 TL (5 g)","gramm":5},{"name":"Salz","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Olivenöl","menge_anzeige":"1 TL (4 g), zum Braten","gramm":4}]'::jsonb, '1. Banane mit einer Gabel zu Püree zerdrücken. 2. Ei und Milch hinzufügen und gut verrühren. 3. In einer anderen Schüssel Vollkornmehl, Backpulver und Salz mischen. 4. Trockene und flüssige Zutaten vermengen und gut durchmischen. 5. Pfanne mit Olivenöl erhitzen. 6. Kleine Portionen Teig in die Pfanne geben und Pfannkuchen von beiden Seiten goldbraun braten. 7. Heiß servieren, optional mit frischem Obst oder Beeren.', 1, 'Die Teigmenge ergibt einen Stapel Pfannkuchen als Einzelportion; der neue kcal-Wert liegt nahezu deckungsgleich mit dem alten Wert bei n=1.', 438, 440, 18, 65, 13, 'Vollkornmehl 50 g = 170 kcal; Banane 120 g = 107 kcal; Ei 50 g = 78 kcal; Milch fettarm 100 ml = 46 kcal; Backpulver 5 g = 2 kcal; Olivenöl 4 g (1 TL) = 35 kcal; Summe = 438 kcal'),
  (16, 'Gesunde Granola mit Joghurt', 'Frühstück', 'Diese gesunde Granola mit Joghurt ist ein hervorragendes Frühstück oder ein Snack, reich an Eiweiß, gesunden Fetten und Kohlenhydraten. Guten Appetit!', '[{"name":"Haferflocken","menge_anzeige":"50 g","gramm":50},{"name":"Honig","menge_anzeige":"1 EL (20 g)","gramm":20},{"name":"Mandeln","menge_anzeige":"20 g","gramm":20},{"name":"Leinsamen","menge_anzeige":"1 EL (10 g)","gramm":10},{"name":"Kokosraspeln","menge_anzeige":"1 EL (5 g)","gramm":5},{"name":"Getrocknete Cranberries","menge_anzeige":"20 g","gramm":20},{"name":"Griechischer Joghurt","menge_anzeige":"150 g","gramm":150}]'::jsonb, '1. Ofen auf 160 °C vorheizen. 2. Haferflocken, Honig, gehackte Mandeln, Leinsamen und Kokosraspeln in einer Schüssel mischen. 3. Mischung auf ein Backblech geben und gleichmäßig verteilen. 4. Im Ofen 15-20 Minuten goldbraun backen, gelegentlich umrühren. 5. Aus dem Ofen nehmen und abkühlen lassen, dann getrocknete Cranberries hinzufügen. 6. Granola mit griechischem Joghurt servieren.', 1, 'Granola plus 150 g Joghurt ergeben eine großzügige Einzelportion Frühstück, passend zum alten kcal-Bereich bei n=1.', 686, 685, 19, 76, 36, 'Haferflocken 50 g = 186 kcal; Honig 20 g = 61 kcal; Mandeln 20 g = 115 kcal; Leinsamen 10 g = 53 kcal; Kokosraspeln 5 g = 33 kcal; Cranberries 20 g = 65 kcal; Griechischer Joghurt 150 g = 173 kcal; Summe = 686 kcal'),
  (17, 'Haferflocken-Pfannkuchen mit Beeren und Joghurt', 'Frühstück', 'Dieser Haferflocken-Pfannkuchen mit Beeren und Joghurt ist ein schnelles und leckeres Frühstück, das in wenigen Minuten zubereitet ist. Guten Appetit!', '[{"name":"Haferflocken","menge_anzeige":"50 g","gramm":50},{"name":"Ei","menge_anzeige":"1 Stk (50 g)","gramm":50},{"name":"Milch (fettarm)","menge_anzeige":"100 ml","gramm":100},{"name":"Griechischer Joghurt","menge_anzeige":"100 g","gramm":100},{"name":"Beeren (Blaubeeren, Himbeeren, Erdbeeren)","menge_anzeige":"100 g","gramm":100},{"name":"Honig","menge_anzeige":"1 TL (7 g)","gramm":7},{"name":"Salz","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Olivenöl","menge_anzeige":"1 TL (4 g), zum Braten","gramm":4}]'::jsonb, '1. Haferflocken im Mixer zu Mehl mahlen. 2. Hafermehl, Ei, Milch und Salz in einer Schüssel mischen, bis eine glatte Masse entsteht. 3. Pfanne mit Olivenöl erhitzen. 4. Teig in die Pfanne geben und gleichmäßig verteilen, um einen Pfannkuchen zu formen. 5. Pfannkuchen von beiden Seiten goldbraun braten. 6. Pfannkuchen auf einen Teller legen, griechischen Joghurt und Beeren darauf verteilen. 7. Vor dem Servieren mit Honig beträufeln.', 1, 'Die Zutatenmenge reicht für einen Pfannkuchen mit Topping als Einzelportion.', 523, 525, 21, 54, 25, 'Haferflocken 50 g = 186 kcal; Ei 50 g = 78 kcal; Milch fettarm 100 ml = 46 kcal; Griechischer Joghurt 100 g = 115 kcal; Beeren 100 g = 42 kcal; Honig 7 g = 21 kcal; Olivenöl 4 g (1 TL) = 35 kcal; Summe = 523 kcal'),
  (18, 'Chia-Pudding mit Kokosmilch und Mango', 'Frühstück', 'Dieses Frühstück ist nicht nur lecker, sondern auch reich an Nährstoffen wie Ballaststoffen, gesunden Fetten und Antioxidantien aus Mango und Kokosmilch. Guten Appetit!', '[{"name":"Chiasamen","menge_anzeige":"2 EL (30 g)","gramm":30},{"name":"Kokosmilch","menge_anzeige":"200 ml","gramm":200},{"name":"Honig","menge_anzeige":"1 EL (20 g)","gramm":20},{"name":"Mango","menge_anzeige":"1/2 Stk (150 g)","gramm":150}]'::jsonb, '1. Chiasamen, Kokosmilch und Honig in einer Schüssel mischen. 2. Gut umrühren und 5-10 Minuten stehen lassen, dann erneut umrühren. 3. Für 2-3 Stunden oder über Nacht in den Kühlschrank stellen. 4. Mango schälen und in Würfel schneiden. 5. Chia-Pudding mit Mango-Würfeln servieren.', 2, 'Die volle Kokosmilchdose und Honigmenge liefern reichlich Energie; aufgeteilt auf 2 Portionen ergibt sich ein plausibler Frühstücks-/Dessertwert, der insgesamt näher am alten kcal-Wert liegt als bei n=1.', 691, 345, 5, 28, 26, 'Chiasamen 30 g = 146 kcal; Kokosmilch 200 ml = 394 kcal; Honig 20 g = 61 kcal; Mango 150 g = 90 kcal; Summe = 691 kcal'),
  (19, 'Apfelpfannkuchen mit Zimt', 'Frühstück', 'Diese Apfelpfannkuchen mit Zimt sind aromatisch und süß, perfekt für ein gesundes Frühstück oder einen Snack. Guten Appetit!', '[{"name":"Apfel","menge_anzeige":"1 Stk (150 g)","gramm":150},{"name":"Ei","menge_anzeige":"1 Stk (50 g)","gramm":50},{"name":"Vollkornmehl","menge_anzeige":"3 EL (45 g)","gramm":45},{"name":"Kefir (fettarm)","menge_anzeige":"100 ml","gramm":100},{"name":"Honig","menge_anzeige":"1 EL (20 g)","gramm":20},{"name":"Zimt","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Salz","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Olivenöl","menge_anzeige":"1 TL (4 g), zum Braten","gramm":4}]'::jsonb, '1. Apfel grob reiben. 2. Ei, Kefir, Honig, Mehl, geriebenen Apfel, Zimt und Salz in einer Schüssel mischen, bis eine glatte Masse entsteht. 3. Pfanne mit Olivenöl erhitzen. 4. Teig löffelweise in die Pfanne geben und Pfannkuchen formen. 5. Pfannkuchen von beiden Seiten goldbraun braten. 6. Heiß servieren.', 1, 'Die Teigmenge ergibt einen Stapel Pfannkuchen als Einzelportion; der neue Wert liegt nahe am alten kcal-Wert bei n=1.', 447, 445, 16, 71, 12, 'Apfel 150 g = 78 kcal; Ei 50 g = 78 kcal; Vollkornmehl 45 g = 153 kcal; Kefir fettarm 100 ml = 42 kcal; Honig 20 g = 61 kcal; Olivenöl 4 g (1 TL) = 35 kcal; Summe = 447 kcal'),
  (20, 'Gebackene Eier mit Avocado und Spinat', 'Frühstück', 'Dieses Frühstück ist nicht nur lecker, sondern auch nahrhaft und perfekt für einen energiereichen Start in den Tag. Guten Appetit!', '[{"name":"Avocado","menge_anzeige":"1 Stk (ca. 200 g)","gramm":200},{"name":"Eier","menge_anzeige":"2 Stk (110 g)","gramm":110},{"name":"Frischer Spinat","menge_anzeige":"1/2 Tasse (ca. 15 g)","gramm":15},{"name":"Geriebener Käse (z. B. Cheddar oder Parmesan)","menge_anzeige":"2 EL (20 g)","gramm":20},{"name":"Olivenöl","menge_anzeige":"1 EL (10 g)","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Paprikapulver","menge_anzeige":"zum Garnieren (optional)","gramm":null},{"name":"Frische Kräuter (Petersilie oder Koriander)","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. 1/2 EL Olivenöl in einer Pfanne bei mittlerer Hitze erhitzen. 2. Spinat hinzufügen und 2-3 Minuten kochen, bis er weich ist. 3. Vom Herd nehmen und beiseite stellen. 4. Avocadohälften auf ein Backblech legen, damit sie stabil sind (Folienringe oder Muffinformen können zur Unterstützung verwendet werden). 5. In jede Avocadohälfte etwas Spinat legen, dann vorsichtig je ein Ei hineinschlagen, dabei darauf achten, dass das Eigelb ganz bleibt (bei großen Eiern kann etwas Eiweiß entfernt werden). 6. Nach Geschmack salzen und pfeffern, dann mit geriebenem Käse bestreuen. 7. Das Backblech in den vorgeheizten Ofen stellen und ca. 15-20 Minuten backen, bis das Eiweiß fest ist und das Eigelb noch leicht flüssig ist. 8. Aus dem Ofen nehmen und etwas abkühlen lassen. 9. Gebackene Avocados auf einen Teller legen, mit frischen Kräutern und Paprikapulver garnieren und vor dem Servieren mit dem restlichen Olivenöl beträufeln.', 2, 'Eine Avocado ergibt zwei Hälften, in die je ein Ei gefüllt wird – das Rezept ist strukturell für 2 Portionen angelegt.', 658, 330, 12, 10, 29, 'Avocado 200 g = 320 kcal; Eier 110 g = 171 kcal; Spinat 15 g = 3 kcal; Geriebener Käse 20 g = 76 kcal; Olivenöl 10 g = 88 kcal; Summe = 658 kcal'),
  (21, 'Tomatensuppe mit Basilikum', 'Suppen', 'Diese Tomatensuppe mit Basilikum zeichnet sich durch ihren reichen Geschmack und ihr Aroma aus und eignet sich perfekt für ein leichtes Mittag- oder Abendessen.', '[{"name":"Tomaten (frisch oder aus der Dose)","menge_anzeige":"400 g","gramm":400},{"name":"Zwiebel","menge_anzeige":"1 Stk (100 g)","gramm":100},{"name":"Knoblauch","menge_anzeige":"2 Zehen (10 g)","gramm":10},{"name":"Olivenöl","menge_anzeige":"1 EL (10 g)","gramm":10},{"name":"Gemüsebrühe","menge_anzeige":"200 ml","gramm":200},{"name":"Frisches Basilikum","menge_anzeige":"10 g","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Zucker","menge_anzeige":"1 TL (5 g) (optional)","gramm":5},{"name":"Sahne (fettarm)","menge_anzeige":"2 EL (30 ml) (optional)","gramm":30}]'::jsonb, '1. Zwiebel und Knoblauch fein würfeln. 2. Olivenöl in einem großen Topf erhitzen, Zwiebeln glasig anbraten, Knoblauch hinzufügen und eine Minute weiterbraten. 3. Gehackte Tomaten (auch mit Saft bei Dosentomaten) und Gemüsebrühe hinzufügen. 4. Suppe zum Kochen bringen, dann Hitze reduzieren und 15-20 Minuten köcheln lassen. 5. Gehacktes Basilikum hinzufügen, mit Salz, Pfeffer und Zucker abschmecken. 6. Suppe mit einem Mixer pürieren, bis sie glatt ist. 7. Suppe zurück in den Topf geben, optional Sahne hinzufügen und aufkochen. 8. Heiß servieren und mit frischen Basilikumblättern garnieren.', 1, 'Die Menge (ca. 640 ml Suppe) ergibt bei n=1 einen Wert nahe am alten kcal-Wert; bei n=2 läge der Wert unterhalb des Suppen-Richtwerts.', 296, 295, 7, 36, 16, 'Tomaten 400 g = 72 kcal; Zwiebel 100 g = 40 kcal; Knoblauch 10 g = 15 kcal; Olivenöl 10 g = 88 kcal; Gemüsebrühe 200 ml = 10 kcal; Basilikum 10 g = 2 kcal; Zucker 5 g = 20 kcal; Sahne fettarm 30 ml = 48 kcal; Summe = 296 kcal'),
  (22, 'Kürbissuppe mit Ingwer', 'Suppen', 'Diese Suppe besticht durch den intensiven Geschmack des Ingwers und die Weichheit des Kürbisses und eignet sich perfekt für ein Abendessen oder Mittagessen in der kalten Jahreszeit.', '[{"name":"Kürbis (geschält)","menge_anzeige":"400 g","gramm":400},{"name":"Zwiebel","menge_anzeige":"1 Stk (100 g)","gramm":100},{"name":"Knoblauch","menge_anzeige":"2 Zehen (10 g)","gramm":10},{"name":"Frischer Ingwer","menge_anzeige":"1 EL (15 g)","gramm":15},{"name":"Olivenöl","menge_anzeige":"1 EL (10 g)","gramm":10},{"name":"Gemüsebrühe","menge_anzeige":"300 ml","gramm":300},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Gemahlener Koriander","menge_anzeige":"1/2 TL (ca. 1 g)","gramm":1},{"name":"Zimt","menge_anzeige":"1/4 TL (ca. 0,5 g)","gramm":0.5},{"name":"Kokosmilch","menge_anzeige":"50 ml","gramm":50},{"name":"Frische Petersilie oder Koriander","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Kürbis in Würfel schneiden. 2. Zwiebel, Knoblauch und Ingwer fein hacken. 3. Olivenöl in einem großen Topf erhitzen, Zwiebeln glasig anbraten, dann Knoblauch und Ingwer hinzufügen und eine Minute weiterbraten. 4. Gehackten Kürbis und Gemüsebrühe hinzufügen. 5. Suppe zum Kochen bringen, dann Hitze reduzieren und 20-25 Minuten köcheln lassen, bis der Kürbis weich ist. 6. Gemahlenen Koriander und Zimt hinzufügen, mit Salz und Pfeffer abschmecken. 7. Suppe mit einem Mixer pürieren, bis sie glatt ist. 8. Optional Kokosmilch hinzufügen und aufkochen. 9. Heiß servieren und mit frischer Petersilie oder Koriander garnieren.', 1, 'Bei n=1 liegt der neue Wert nah am alten kcal-Wert und passt zur Menge von ca. 700 ml Suppe für eine Portion.', 377, 375, 8, 46, 21, 'Kürbis 400 g = 104 kcal; Zwiebel 100 g = 40 kcal; Knoblauch 10 g = 15 kcal; Ingwer 15 g = 12 kcal; Olivenöl 10 g = 88 kcal; Gemüsebrühe 300 ml = 15 kcal; Koriander 1 g = 3 kcal; Zimt 0,5 g = 1 kcal; Kokosmilch 50 ml = 99 kcal; Summe = 377 kcal'),
  (23, 'Leichte Hühnersuppe mit Gemüse', 'Suppen', 'Diese Suppe ist reich an Proteinen und Vitaminen und eignet sich perfekt als vollwertiges Mittag- oder Abendessen, besonders in der kalten Jahreszeit.', '[{"name":"Hähnchenbrustfilet","menge_anzeige":"100 g","gramm":100},{"name":"Karotte","menge_anzeige":"1 Stk (100 g)","gramm":100},{"name":"Stangensellerie","menge_anzeige":"1 Stiel (50 g)","gramm":50},{"name":"Zucchini","menge_anzeige":"1/2 Stk (100 g)","gramm":100},{"name":"Kartoffel","menge_anzeige":"1 Stk (150 g)","gramm":150},{"name":"Zwiebel","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Knoblauch","menge_anzeige":"1 Zehe (5 g)","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 TL (4 g)","gramm":4},{"name":"Gemüsebrühe","menge_anzeige":"400 ml","gramm":400},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Petersilie","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Hähnchenbrust in Würfel schneiden. 2. Alle Gemüse in Würfel schneiden. 3. Olivenöl in einem großen Topf erhitzen, Zwiebeln und Knoblauch glasig anbraten. 4. Hähnchenbrust hinzufügen und bis zur Halbgarung anbraten. 5. Karotte, Sellerie, Zucchini und Kartoffel hinzufügen und 5 Minuten weitergaren. 6. Gemüsebrühe hinzufügen und zum Kochen bringen. 7. Hitze reduzieren und 15-20 Minuten köcheln lassen, bis das Gemüse weich ist. 8. Mit Salz und Pfeffer abschmecken. 9. Heiß servieren und mit frischer Petersilie garnieren.', 1, 'Bei n=1 liegt der Wert im Suppen-Richtwert und am nächsten am alten kcal-Wert.', 374, 375, 31, 50, 7, 'Hähnchenbrustfilet 100 g = 110 kcal; Karotte 100 g = 41 kcal; Stangensellerie 50 g = 8 kcal; Zucchini 100 g = 17 kcal; Kartoffel 150 g = 116 kcal; Zwiebel 50 g = 20 kcal; Knoblauch 5 g = 7 kcal; Olivenöl 4 g = 35 kcal; Gemüsebrühe 400 ml = 20 kcal; Summe = 374 kcal'),
  (24, 'Linsensuppe mit Spinat', 'Suppen', 'Diese Suppe ist reich an Proteinen und Ballaststoffen aus Linsen und Spinat und überzeugt mit ihrem würzigen Aroma. Sie eignet sich hervorragend für eine gesunde Ernährung oder eine vegetarische Kost.', '[{"name":"Linsen (trocken)","menge_anzeige":"50 g","gramm":50},{"name":"Spinat (frisch oder gefroren)","menge_anzeige":"100 g","gramm":100},{"name":"Zwiebel","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Karotte","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Knoblauch","menge_anzeige":"1 Zehe (5 g)","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL (10 g)","gramm":10},{"name":"Gemüsebrühe","menge_anzeige":"400 ml","gramm":400},{"name":"Tomatenmark","menge_anzeige":"1 EL (20 g)","gramm":20},{"name":"Gemahlener Koriander","menge_anzeige":"1/2 TL (ca. 1 g)","gramm":1},{"name":"Gemahlener Kreuzkümmel","menge_anzeige":"1/2 TL (ca. 1 g)","gramm":1},{"name":"Zitronensaft, Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Zwiebel, Karotte und Knoblauch fein hacken. 2. Olivenöl in einem großen Topf erhitzen, Zwiebeln glasig anbraten, dann Knoblauch hinzufügen und eine Minute weiterbraten. 3. Gehackte Karotte hinzufügen und weitere 2-3 Minuten garen. 4. Linsen und Tomatenmark hinzufügen und umrühren. 5. Gemüsebrühe, Koriander und Kreuzkümmel hinzufügen und zum Kochen bringen. 6. Hitze reduzieren und 20-25 Minuten köcheln lassen, bis die Linsen weich sind. 7. Spinat hinzufügen und weitere 5 Minuten garen, bis der Spinat weich ist. 8. Mit Salz, Pfeffer und Zitronensaft abschmecken. 9. Heiß servieren.', 1, 'Bei n=1 liegt der Wert im Suppen-Richtwert und nah am alten kcal-Wert.', 379, 380, 19, 48, 12, 'Linsen (trocken) 50 g = 177 kcal; Spinat 100 g = 23 kcal; Zwiebel 50 g = 20 kcal; Karotte 50 g = 21 kcal; Knoblauch 5 g = 7 kcal; Olivenöl 10 g = 88 kcal; Gemüsebrühe 400 ml = 20 kcal; Tomatenmark 20 g = 16 kcal; Koriander 1 g = 3 kcal; Kreuzkümmel 1 g = 4 kcal; Summe = 379 kcal'),
  (25, 'Cremige Pilzsuppe', 'Suppen', 'Diese cremige Pilzsuppe eignet sich perfekt für ein Abendessen oder ein leichtes Mittagessen und überzeugt durch ihren reichhaltigen und aromatischen Geschmack dank der Pilze und Sahne.', '[{"name":"Champignons (frisch)","menge_anzeige":"200 g","gramm":200},{"name":"Zwiebel","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Knoblauch","menge_anzeige":"1 Zehe (5 g)","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL (10 g)","gramm":10},{"name":"Gemüsebrühe","menge_anzeige":"300 ml","gramm":300},{"name":"Sahne (10-20 %)","menge_anzeige":"50 ml","gramm":50},{"name":"Mehl","menge_anzeige":"1 EL (15 g)","gramm":15},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Petersilie","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Pilze, Zwiebel und Knoblauch fein hacken. 2. Olivenöl in einem großen Topf erhitzen, Zwiebeln glasig anbraten, dann Knoblauch hinzufügen und eine Minute weiterbraten. 3. Pilze hinzufügen und garen, bis sie Saft abgeben und ihr Volumen reduzieren (ca. 5-7 Minuten). 4. Mehl hinzufügen und gut umrühren, um Klumpen zu vermeiden. 5. Gemüsebrühe hinzufügen und zum Kochen bringen, dann Hitze reduzieren und 10-15 Minuten köcheln lassen. 6. Suppe mit einem Mixer pürieren, bis sie glatt ist. 7. Suppe zurück in den Topf geben, Sahne hinzufügen und aufkochen. 8. Mit Salz und Pfeffer abschmecken. 9. Heiß servieren und mit frischer Petersilie garnieren.', 1, 'Bei n=1 liegt der Wert im Suppen-Richtwert und am nächsten am alten kcal-Wert.', 308, 310, 11, 28, 18, 'Champignons 200 g = 44 kcal; Zwiebel 50 g = 20 kcal; Knoblauch 5 g = 7 kcal; Olivenöl 10 g = 88 kcal; Gemüsebrühe 300 ml = 15 kcal; Sahne 10-20 % 50 ml = 81 kcal; Mehl 15 g = 52 kcal; Summe = 308 kcal'),
  (26, 'Minestrone mit Bohnen und Gemüse', 'Suppen', 'Diese Minestrone mit Bohnen und Gemüse ist sättigend und bietet eine Vielfalt an Geschmack durch die Vielzahl an Gemüse und italienischen Kräutern.', '[{"name":"Weiße Bohnen (konserviert)","menge_anzeige":"100 g","gramm":100},{"name":"Karotte","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Stangensellerie","menge_anzeige":"1 Stiel (50 g)","gramm":50},{"name":"Zucchini","menge_anzeige":"1/2 Stk (100 g)","gramm":100},{"name":"Kartoffel","menge_anzeige":"1 Stk (150 g)","gramm":150},{"name":"Zwiebel","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Knoblauch","menge_anzeige":"1 Zehe (5 g)","gramm":5},{"name":"Tomaten (konserviert)","menge_anzeige":"200 g","gramm":200},{"name":"Olivenöl","menge_anzeige":"1 EL (10 g)","gramm":10},{"name":"Gemüsebrühe","menge_anzeige":"400 ml","gramm":400},{"name":"Erbsen (tiefgefroren)","menge_anzeige":"50 g","gramm":50},{"name":"Italienische Kräuter","menge_anzeige":"1 TL (ca. 2 g)","gramm":2},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Parmesan","menge_anzeige":"zum Servieren (optional)","gramm":null},{"name":"Frische Petersilie","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Alle Gemüse in Würfel schneiden, Knoblauch fein hacken. 2. Olivenöl in einem großen Topf erhitzen, Zwiebeln und Knoblauch glasig anbraten. 3. Karotte, Sellerie und Kartoffel hinzufügen und 5-7 Minuten unter gelegentlichem Rühren garen. 4. Zucchini hinzufügen und weitere 3-4 Minuten garen. 5. Gemüsebrühe und Tomaten (mit Saft) hinzufügen, italienische Kräuter hinzufügen und zum Kochen bringen. 6. Hitze reduzieren und 15-20 Minuten köcheln lassen, bis das Gemüse weich ist. 7. Bohnen und Erbsen hinzufügen, mit Salz und Pfeffer abschmecken und weitere 5 Minuten garen. 8. Heiß servieren, optional mit geriebenem Parmesan und frischer Petersilie garnieren.', 1, 'Bei n=1 liegt der Wert am nächsten am alten kcal-Wert; als sättigender Eintopf übersteigt er leicht den üblichen Suppen-Richtwert, was für eine Minestrone als Hauptmahlzeit plausibel ist.', 477, 475, 19, 74, 12, 'Weiße Bohnen 100 g = 100 kcal; Karotte 50 g = 21 kcal; Stangensellerie 50 g = 8 kcal; Zucchini 100 g = 17 kcal; Kartoffel 150 g = 116 kcal; Zwiebel 50 g = 20 kcal; Knoblauch 5 g = 7 kcal; Tomaten (konserviert) 200 g = 40 kcal; Olivenöl 10 g = 88 kcal; Gemüsebrühe 400 ml = 20 kcal; Erbsen 50 g = 35 kcal; Italienische Kräuter 2 g = 5 kcal; Summe = 477 kcal'),
  (27, 'Blumenkohlbrühe mit Kräutern', 'Suppen', 'Diese Blumenkohlbrühe mit Kräutern ist einfach zuzubereiten und hat einen angenehmen Geschmack und Aroma von frischem Gemüse. Perfekt für ein gesundes Abendessen oder ein leichtes Mittagessen.', '[{"name":"Blumenkohl","menge_anzeige":"200 g","gramm":200},{"name":"Karotte","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Zwiebel","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 TL (5 ml)","gramm":4},{"name":"Gemüsebrühe","menge_anzeige":"400 ml","gramm":400},{"name":"Frische Petersilie","menge_anzeige":"10 g","gramm":10},{"name":"Dill","menge_anzeige":"10 g","gramm":10},{"name":"Frühlingszwiebel","menge_anzeige":"10 g","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Zitronensaft","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Blumenkohl in kleine Röschen teilen, Karotte, Zwiebel und Knoblauch fein hacken.
2. Olivenöl in einem großen Topf erhitzen, Zwiebeln glasig anbraten, dann Knoblauch hinzufügen und eine Minute weiterbraten.
3. Karotte hinzufügen und weitere 2–3 Minuten garen.
4. Blumenkohl und Gemüsebrühe hinzufügen, zum Kochen bringen.
5. Hitze reduzieren und 15–20 Minuten köcheln lassen, bis das Gemüse weich ist.
6. Gehackte Kräuter (Petersilie, Dill und Frühlingszwiebel) hinzufügen, mit Salz und Pfeffer abschmecken. Optional mit Zitronensaft abschmecken.
7. Heiß servieren.', 1, 'Gesamtmenge und Nährwert (148 kcal) entsprechen einer leichten Portion für 1 Person; nahe am alten kcal-Wert (166).', 148, 150, 7, 16, 5, 'Blumenkohl (200 g) = 50 kcal; Karotte (50 g) = 12 kcal; Zwiebel (50 g) = 13 kcal; Knoblauch (5 g) = 6 kcal; Olivenöl (4 g) = 35 kcal; Gemüsebrühe (400 g) = 20 kcal; Frische Petersilie (10 g) = 4 kcal; Dill (10 g) = 4 kcal; Frühlingszwiebel (10 g) = 3 kcal; Salz und Pfeffer = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Zitronensaft = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Summe = 148 kcal'),
  (28, 'Brokkolicremesuppe mit Mandeln', 'Suppen', 'Diese Brokkolicremesuppe ist durch die Zugabe von Mandeln und Sahne besonders cremig und reich an Geschmack und eignet sich hervorragend für leichte und sättigende Gerichte.', '[{"name":"Brokkoli","menge_anzeige":"200 g","gramm":200},{"name":"Zwiebel","menge_anzeige":"50 g","gramm":50},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"15 ml","gramm":10},{"name":"Gemüsebrühe","menge_anzeige":"300 ml","gramm":300},{"name":"Mandeln (gemahlen)","menge_anzeige":"20 g","gramm":20},{"name":"Sahne (10-20%)","menge_anzeige":"50 ml","gramm":50},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Petersilie","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Brokkoli in Röschen teilen, Zwiebel und Knoblauch fein hacken.
2. Olivenöl in einem großen Topf erhitzen, Zwiebeln glasig anbraten, dann Knoblauch hinzufügen und eine Minute weiterbraten.
3. Brokkoli und Gemüsebrühe hinzufügen, zum Kochen bringen.
4. Hitze reduzieren und 10–15 Minuten köcheln lassen, bis der Brokkoli weich ist.
5. Gemahlene Mandeln und Sahne hinzufügen, umrühren.
6. Suppe mit einem Mixer pürieren, bis sie glatt ist.
7. Zurück in den Topf geben, aufkochen und mit Salz und Pfeffer abschmecken.
8. Heiß servieren und mit frischer Petersilie garnieren.', 1, '387 kcal Gesamtmenge passt zu einer sättigenden Portion Cremesuppe für 1 Person, nahe am alten Wert (432 kcal).', 387, 385, 13, 16, 29, 'Brokkoli (200 g) = 68 kcal; Zwiebel (50 g) = 13 kcal; Knoblauch (5 g) = 6 kcal; Olivenöl (10 g) = 88 kcal; Gemüsebrühe (300 g) = 15 kcal; Mandeln (gemahlen) (20 g) = 116 kcal; Sahne (10-20%) (50 g) = 80 kcal; Salz und Pfeffer = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Frische Petersilie = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Summe = 387 kcal'),
  (29, 'Fischsuppe mit Lachs und Gemüse', 'Suppen', 'Diese Fischsuppe mit Lachs und Gemüse hat einen reichen Geschmack und ist voller Nährstoffe. Ideal für ein Mittag- oder Abendessen, besonders in der kalten Jahreszeit.', '[{"name":"Lachsfilet","menge_anzeige":"100 g","gramm":100},{"name":"Karotte","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Kartoffel","menge_anzeige":"1 Stk (150 g)","gramm":150},{"name":"Stangensellerie","menge_anzeige":"1 Stiel (50 g)","gramm":50},{"name":"Zwiebel","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL (15 ml)","gramm":10},{"name":"Fischbrühe","menge_anzeige":"400 ml","gramm":400},{"name":"Tomate","menge_anzeige":"1 Stk (100 g)","gramm":100},{"name":"Lorbeerblatt","menge_anzeige":"1 Stk","gramm":null},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Petersilie oder Dill","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Lachsfilet in kleine Stücke schneiden. Karotte, Kartoffel, Sellerie, Zwiebel und Tomate würfeln, Knoblauch fein hacken.
2. Olivenöl in einem großen Topf erhitzen, Zwiebeln glasig anbraten, dann Knoblauch hinzufügen und eine Minute weiterbraten.
3. Karotte, Sellerie und Kartoffel hinzufügen und 5 Minuten weitergaren.
4. Fischbrühe und Lorbeerblatt hinzufügen, zum Kochen bringen.
5. Hitze reduzieren und 10 Minuten köcheln lassen, bis das Gemüse weich ist.
6. Tomate und Lachsstücke hinzufügen, weitere 5–7 Minuten garen, bis der Lachs gar ist.
7. Mit Salz und Pfeffer abschmecken.
8. Heiß servieren und mit frischer Petersilie oder Dill garnieren.', 1, '413 kcal Gesamtmenge entspricht einer kräftigen Hauptmahlzeit-Portion für 1 Person, in der Nähe des alten Werts (555 kcal).', 413, 415, 27, 35, 17, 'Lachsfilet (100 g) = 142 kcal; Karotte (50 g) = 12 kcal; Kartoffel (150 g) = 105 kcal; Stangensellerie (50 g) = 8 kcal; Zwiebel (50 g) = 13 kcal; Knoblauch (5 g) = 6 kcal; Olivenöl (10 g) = 88 kcal; Fischbrühe (400 g) = 20 kcal; Tomate (100 g) = 18 kcal; Lorbeerblatt = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Salz und Pfeffer = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Frische Petersilie oder Dill = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Summe = 413 kcal'),
  (30, 'Käsesuppe mit Lachs', 'Suppen', 'Diese Käsesuppe mit Lachs hat einen intensiven Geschmack dank des Käses und Lachses und ist durch die Zugabe von Kartoffeln und Gemüse ein vollwertiges Gericht.', '[{"name":"Lachsfilet","menge_anzeige":"100 g","gramm":100},{"name":"Kartoffel","menge_anzeige":"150 g","gramm":150},{"name":"Karotte","menge_anzeige":"50 g","gramm":50},{"name":"Zwiebel","menge_anzeige":"50 g","gramm":50},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"15 ml","gramm":10},{"name":"Gemüsebrühe","menge_anzeige":"400 ml","gramm":400},{"name":"Schmelzkäse","menge_anzeige":"50 g","gramm":50},{"name":"Hartkäse","menge_anzeige":"30 g","gramm":30},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Petersilie oder Dill","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Kartoffel in Würfel schneiden, Zwiebel und Karotte fein würfeln, Knoblauch hacken.
2. Olivenöl in einem großen Topf erhitzen, Zwiebeln glasig anbraten, dann Knoblauch und Karotte hinzufügen und 2–3 Minuten weitergaren.
3. Kartoffel und Gemüsebrühe hinzufügen, zum Kochen bringen.
4. Hitze reduzieren und 15–20 Minuten köcheln lassen, bis das Gemüse weich ist.
5. Lachs hinzufügen und weitere 5–7 Minuten garen, bis der Lachs gar ist.
6. Schmelzkäse und geriebenen Hartkäse hinzufügen und umrühren, bis der Käse vollständig geschmolzen ist.
7. Mit Salz und Pfeffer abschmecken. Optional die Suppe mit einem Mixer pürieren.
8. Heiß servieren und mit frischer Petersilie oder Dill garnieren.', 2, 'Gesamtmenge (641 kcal) ist für 1 Portion zu hoch für eine Suppe (Richtwert 150–400 kcal); aufgeteilt auf 2 Portionen à 320 kcal deutlich realistischer.', 641, 320, 20, 17, 19, 'Lachsfilet (100 g) = 142 kcal; Kartoffel (150 g) = 105 kcal; Karotte (50 g) = 12 kcal; Zwiebel (50 g) = 13 kcal; Knoblauch (5 g) = 6 kcal; Olivenöl (10 g) = 88 kcal; Gemüsebrühe (400 g) = 20 kcal; Schmelzkäse (50 g) = 140 kcal; Hartkäse (30 g) = 114 kcal; Salz und Pfeffer = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Frische Petersilie oder Dill = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Summe = 641 kcal'),
  (31, 'Kürbissuppe mit roten Linsen', 'Suppen', 'Diese Kürbissuppe mit roten Linsen ist sättigend und gesund, dank des Kürbisses und der Linsen sowie der aromatischen Gewürze.', '[{"name":"Kürbis (geschält)","menge_anzeige":"200 g","gramm":200},{"name":"Rote Linsen (trocken)","menge_anzeige":"50 g","gramm":50},{"name":"Zwiebel","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Karotte","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL (15 ml)","gramm":10},{"name":"Gemüsebrühe","menge_anzeige":"400 ml","gramm":400},{"name":"Tomatenmark","menge_anzeige":"1 EL (20 g)","gramm":20},{"name":"Gemahlener Kreuzkümmel","menge_anzeige":"1/2 TL","gramm":1},{"name":"Gemahlener Koriander","menge_anzeige":"1/2 TL","gramm":1},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Petersilie","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Kürbis in Würfel schneiden, Zwiebel und Karotte fein hacken, Knoblauch hacken.
2. Olivenöl in einem großen Topf erhitzen, Zwiebeln glasig anbraten, dann Knoblauch und Karotte hinzufügen und 2–3 Minuten weitergaren.
3. Kürbis hinzufügen und weitere 5 Minuten garen.
4. Rote Linsen und Tomatenmark hinzufügen und umrühren.
5. Gemüsebrühe, Kreuzkümmel und Koriander hinzufügen und zum Kochen bringen.
6. Hitze reduzieren und 20–25 Minuten köcheln lassen, bis das Gemüse und die Linsen weich sind.
7. Suppe mit einem Mixer pürieren, bis sie glatt ist.
8. Mit Salz und Pfeffer abschmecken.
9. Heiß servieren und mit frischer Petersilie garnieren.', 1, '378 kcal Gesamtmenge liegt im Suppen-Richtwert (150–400 kcal) und nahe am alten Wert (428 kcal) für 1 Portion.', 378, 380, 18, 48, 12, 'Kürbis (geschält) (200 g) = 52 kcal; Rote Linsen (trocken) (50 g) = 162 kcal; Zwiebel (50 g) = 13 kcal; Karotte (50 g) = 12 kcal; Knoblauch (5 g) = 6 kcal; Olivenöl (10 g) = 88 kcal; Gemüsebrühe (400 g) = 20 kcal; Tomatenmark (20 g) = 16 kcal; Gemahlener Kreuzkümmel (1 g) = 4 kcal; Gemahlener Koriander (1 g) = 3 kcal; Salz und Pfeffer = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Frische Petersilie = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Summe = 378 kcal'),
  (32, 'Ramen mit Huhn und Gemüse', 'Suppen', 'Ramen mit Huhn und Gemüse ist eine ausgezeichnete Wahl für alle, die ein leckeres und sättigendes Gericht genießen möchten. Dieses Rezept kombiniert den reichen Geschmack von Huhn, aromatischer Brühe und verschiedenen Texturen von Gemüse und Nudeln.', '[{"name":"Ramen-Nudeln","menge_anzeige":"100 g","gramm":100},{"name":"Hähnchenbrustfilet","menge_anzeige":"100 g","gramm":100},{"name":"Ei","menge_anzeige":"1 Stk (50 g)","gramm":50},{"name":"Champignons","menge_anzeige":"50 g","gramm":50},{"name":"Karotte","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Frühlingszwiebel","menge_anzeige":"20 g","gramm":20},{"name":"Spinat","menge_anzeige":"50 g","gramm":50},{"name":"Frischer Ingwer","menge_anzeige":"10 g","gramm":10},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Sojasoße","menge_anzeige":"2 EL (30 ml)","gramm":30},{"name":"Miso-Paste","menge_anzeige":"1 EL (15 g)","gramm":15},{"name":"Hühnerbrühe","menge_anzeige":"500 ml","gramm":500},{"name":"Pflanzenöl","menge_anzeige":"1 TL (5 ml)","gramm":4},{"name":"Sesam und Nori","menge_anzeige":"zum Garnieren","gramm":null},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. In einem kleinen Topf Wasser zum Kochen bringen und das Ei vorsichtig hineingeben. 7 Minuten für weiches Eigelb oder 10 Minuten für härteres kochen, danach in Eiswasser legen, um den Garprozess zu stoppen.
2. Hähnchenbrust in dünne Streifen schneiden.
3. Pflanzenöl in einem großen Topf erhitzen und gehackten Ingwer und Knoblauch anbraten, bis sie duften.
4. Hühnerbrühe hinzufügen und zum Kochen bringen, Hähnchenbrust hineingeben und bei mittlerer Hitze ca. 5–7 Minuten garen.
5. Karotte in dünne Streifen schneiden, Champignons in Scheiben, Frühlingszwiebel und Spinat grob hacken.
6. Sojasoße und Miso-Paste (optional) in die Brühe geben und rühren, bis sich die Miso-Paste auflöst.
7. In einem separaten Topf Wasser zum Kochen bringen und Ramen-Nudeln nach Packungsanweisung kochen, unter kaltem Wasser abspülen und beiseitestellen.
8. Karottenstreifen, Champignons und Spinat in die Brühe geben und 3–5 Minuten kochen, bis das Gemüse weich ist.
9. Ramen-Nudeln in eine Schüssel geben und mit der Brühe, Huhn und Gemüse übergießen. Ei halbieren und dazugeben.
10. Mit gehackter Frühlingszwiebel, Sesam und Nori garnieren, mit Salz und Pfeffer abschmecken.', 1, '702 kcal Gesamtmenge passt zu einer sättigenden Hauptgericht-Portion (Nudelsuppe als Mahlzeit) für 1 Person, nahe am alten Wert (538 kcal).', 702, 700, 48, 93, 14, 'Ramen-Nudeln (100 g) = 350 kcal; Hähnchenbrustfilet (100 g) = 110 kcal; Ei (50 g) = 78 kcal; Champignons (50 g) = 11 kcal; Karotte (50 g) = 12 kcal; Frühlingszwiebel (20 g) = 6 kcal; Spinat (50 g) = 12 kcal; Frischer Ingwer (10 g) = 8 kcal; Knoblauch (5 g) = 6 kcal; Sojasoße (30 g) = 18 kcal; Miso-Paste (15 g) = 30 kcal; Hühnerbrühe (500 g) = 25 kcal; Pflanzenöl (4 g) = 35 kcal; Sesam und Nori = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Salz und Pfeffer = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Summe = 702 kcal'),
  (33, 'Suppe mit Fleischbällchen', 'Suppen', 'Diese Suppe mit Fleischbällchen und Kartoffeln ist eine hervorragende Wahl für ein sättigendes Mittag- oder Abendessen. Sie kombiniert fleischige Bällchen, aromatisches Gemüse und eine reichhaltige Brühe.', '[{"name":"Hackfleisch (Rind- oder Hühnerfleisch)","menge_anzeige":"100 g","gramm":100},{"name":"Ei","menge_anzeige":"1/4 Stk (12,5 g)","gramm":12.5},{"name":"Semmelbrösel","menge_anzeige":"1 EL (15 g)","gramm":15},{"name":"Zwiebel","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Karotte","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Kartoffel","menge_anzeige":"1 Stk (150 g)","gramm":150},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL (15 ml)","gramm":10},{"name":"Gemüse- oder Hühnerbrühe","menge_anzeige":"400 ml","gramm":400},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Petersilie","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Für die Fleischbällchen Hackfleisch, Ei, Semmelbrösel, Salz und Pfeffer in einer Schüssel vermengen und gut durchmischen, kleine Bällchen in Walnussgröße formen.
2. Für die Suppe Zwiebel und Karotte fein hacken, Knoblauch hacken, Kartoffel in Würfel schneiden.
3. Olivenöl in einem großen Topf erhitzen, Zwiebeln glasig anbraten, dann Knoblauch und Karotte hinzufügen und 2–3 Minuten weitergaren.
4. Kartoffel und Gemüse- oder Hühnerbrühe hinzufügen, zum Kochen bringen.
5. Hitze reduzieren und die Fleischbällchen vorsichtig in die Brühe geben, 15–20 Minuten köcheln lassen, bis Kartoffeln und Fleischbällchen gar sind.
6. Mit Salz und Pfeffer abschmecken.
7. Heiß servieren und mit frischer Petersilie garnieren.', 1, '569 kcal Gesamtmenge liegt sehr nahe am alten Wert (626 kcal) und passt zu einer vollwertigen Mahlzeit-Portion für 1 Person.', 569, 570, 26, 42, 32, 'Hackfleisch (Rind- oder Hühnerfleisch) (100 g) = 250 kcal; Ei (12.5 g) = 19 kcal; Semmelbrösel (15 g) = 54 kcal; Zwiebel (50 g) = 13 kcal; Karotte (50 g) = 12 kcal; Kartoffel (150 g) = 105 kcal; Knoblauch (5 g) = 6 kcal; Olivenöl (10 g) = 88 kcal; Gemüse- oder Hühnerbrühe (400 g) = 20 kcal; Salz und Pfeffer = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Frische Petersilie = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Summe = 569 kcal'),
  (34, 'Leichte Gemüsesuppe', 'Suppen', 'Diese Gemüsesuppe ist perfekt für diejenigen, die auf ihre Ernährung achten und trotzdem ein gesundes und schmackhaftes Gericht genießen möchten. Sie ist reich an Vitaminen und Mineralstoffen, dank der Vielzahl an Gemüse.', '[{"name":"Karotte","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Stangensellerie","menge_anzeige":"1 Stiel (50 g)","gramm":50},{"name":"Zucchini","menge_anzeige":"1/2 Stk (100 g)","gramm":100},{"name":"Kartoffel","menge_anzeige":"1 Stk (150 g)","gramm":150},{"name":"Zwiebel","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 TL (5 ml)","gramm":4},{"name":"Gemüsebrühe","menge_anzeige":"400 ml","gramm":400},{"name":"Erbsen (tiefgefroren)","menge_anzeige":"50 g","gramm":50},{"name":"Lorbeerblatt","menge_anzeige":"1 Stk","gramm":null},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Petersilie","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Alle Gemüse in Würfel schneiden, Knoblauch hacken.
2. Olivenöl in einem großen Topf erhitzen, Zwiebeln glasig anbraten, dann Knoblauch hinzufügen und eine Minute weiterbraten.
3. Karotte, Sellerie und Kartoffel hinzufügen und 5–7 Minuten unter gelegentlichem Rühren garen.
4. Zucchini hinzufügen und weitere 3–4 Minuten garen.
5. Gemüsebrühe und Lorbeerblatt hinzufügen und zum Kochen bringen.
6. Hitze reduzieren und 15–20 Minuten köcheln lassen, bis das Gemüse weich ist.
7. Erbsen hinzufügen, mit Salz und Pfeffer abschmecken und weitere 5 Minuten garen.
8. Heiß servieren und mit frischer Petersilie garnieren.', 1, '247 kcal Gesamtmenge liegt im Suppen-Richtwert (150–400 kcal) für 1 Portion, nahe am alten Wert (288 kcal).', 247, 245, 9, 38, 5, 'Karotte (50 g) = 12 kcal; Stangensellerie (50 g) = 8 kcal; Zucchini (100 g) = 17 kcal; Kartoffel (150 g) = 105 kcal; Zwiebel (50 g) = 13 kcal; Knoblauch (5 g) = 6 kcal; Olivenöl (4 g) = 35 kcal; Gemüsebrühe (400 g) = 20 kcal; Erbsen (tiefgefroren) (50 g) = 30 kcal; Lorbeerblatt = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Salz und Pfeffer = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Frische Petersilie = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Summe = 247 kcal'),
  (35, 'Kartoffelsuppe', 'Suppen', 'Cremige Kartoffelsuppe mit Karotte und Sellerie, optional verfeinert mit Sahne – ein wärmendes Gericht für ein Mittag- oder Abendessen.', '[{"name":"Kartoffel","menge_anzeige":"2 Stk (300 g)","gramm":300},{"name":"Zwiebel","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Karotte","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Stangensellerie","menge_anzeige":"1 Stiel (50 g)","gramm":50},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL (15 ml)","gramm":10},{"name":"Gemüsebrühe","menge_anzeige":"500 ml","gramm":500},{"name":"Lorbeerblatt","menge_anzeige":"1 Stk","gramm":null},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Petersilie","menge_anzeige":"zum Garnieren","gramm":null},{"name":"Sahne (10-20%)","menge_anzeige":"50 ml (optional)","gramm":50}]'::jsonb, '1. Kartoffel in Würfel schneiden, Zwiebel, Karotte und Sellerie fein hacken, Knoblauch hacken.
2. Olivenöl in einem großen Topf erhitzen, Zwiebeln glasig anbraten, dann Knoblauch hinzufügen und eine Minute weiterbraten.
3. Karotte und Sellerie hinzufügen und 5–7 Minuten unter gelegentlichem Rühren garen.
4. Kartoffel und Gemüsebrühe hinzufügen, zum Kochen bringen.
5. Hitze reduzieren, Lorbeerblatt hinzufügen und 15–20 Minuten köcheln lassen, bis die Kartoffeln weich sind.
6. Optional Sahne hinzufügen und umrühren, mit Salz und Pfeffer abschmecken.
7. Optional die Suppe mit einem Mixer pürieren.
8. Heiß servieren und mit frischer Petersilie garnieren.', 1, '444 kcal Gesamtmenge nahe am alten Wert (518 kcal), passend für eine sättigende Portion für 1 Person.', 444, 445, 10, 57, 19, 'Kartoffel (300 g) = 210 kcal; Zwiebel (50 g) = 13 kcal; Karotte (50 g) = 12 kcal; Stangensellerie (50 g) = 8 kcal; Knoblauch (5 g) = 6 kcal; Olivenöl (10 g) = 88 kcal; Gemüsebrühe (500 g) = 25 kcal; Lorbeerblatt = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Salz und Pfeffer = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Frische Petersilie = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Sahne (10-20%) (50 g) = 80 kcal; Summe = 444 kcal'),
  (36, 'Lebersuppe', 'Suppen', 'Diese Lebersuppe ist ein leichtes und nahrhaftes Gericht, reich an Proteinen und Vitaminen.', '[{"name":"Hühnerleber","menge_anzeige":"100 g","gramm":100},{"name":"Kartoffel","menge_anzeige":"1 Stk (150 g)","gramm":150},{"name":"Karotte","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Zwiebel","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL (15 ml)","gramm":10},{"name":"Gemüsebrühe","menge_anzeige":"400 ml","gramm":400},{"name":"Lorbeerblatt","menge_anzeige":"1 Stk","gramm":null},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Petersilie oder Dill","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Hühnerleber in kleine Stücke schneiden, Kartoffel in Würfel schneiden, Zwiebel und Karotte fein hacken, Knoblauch hacken.
2. Olivenöl in einem großen Topf erhitzen, Zwiebeln glasig anbraten, dann Knoblauch und Karotte hinzufügen und 2–3 Minuten weitergaren.
3. Kartoffel und Gemüsebrühe hinzufügen, zum Kochen bringen.
4. Hitze reduzieren, Lorbeerblatt hinzufügen und 10 Minuten köcheln lassen.
5. Hühnerleber hinzufügen und weitere 10 Minuten garen, bis Leber und Kartoffeln gar sind.
6. Mit Salz und Pfeffer abschmecken.
7. Heiß servieren und mit frischer Petersilie oder Dill garnieren.', 1, '381 kcal Gesamtmenge liegt am oberen Rand des Suppen-Richtwerts (150–400 kcal) und ist nahe am alten Wert (438 kcal) für 1 Portion.', 381, 380, 22, 32, 17, 'Hühnerleber (100 g) = 136 kcal; Kartoffel (150 g) = 105 kcal; Karotte (50 g) = 12 kcal; Zwiebel (50 g) = 13 kcal; Knoblauch (5 g) = 6 kcal; Olivenöl (10 g) = 88 kcal; Gemüsebrühe (400 g) = 20 kcal; Lorbeerblatt = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Salz und Pfeffer = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Frische Petersilie oder Dill = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Summe = 381 kcal'),
  (37, 'Spargelsuppe', 'Suppen', 'Diese Spargelsuppe hat einen feinen Geschmack und ein angenehmes Aroma dank der Gemüsebrühe und der leichten Cremigkeit durch die Sahne.', '[{"name":"Spargel","menge_anzeige":"200 g","gramm":200},{"name":"Zwiebel","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Kartoffel","menge_anzeige":"1 Stk (150 g)","gramm":150},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL (15 ml)","gramm":10},{"name":"Gemüsebrühe","menge_anzeige":"400 ml","gramm":400},{"name":"Sahne (10-20%)","menge_anzeige":"50 ml (optional)","gramm":50},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Zitronensaft","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Petersilie oder Dill","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Spargel in kleine Stücke schneiden, Spitzen zum Garnieren beiseitelegen. Kartoffel in Würfel schneiden, Zwiebel fein hacken, Knoblauch hacken.
2. Olivenöl in einem großen Topf erhitzen, Zwiebeln glasig anbraten, dann Knoblauch hinzufügen und eine Minute weiterbraten.
3. Kartoffel und geschnittenen Spargel (außer Spitzen) hinzufügen und 5 Minuten garen.
4. Gemüsebrühe hinzufügen, zum Kochen bringen, Hitze reduzieren und 15–20 Minuten köcheln lassen, bis Kartoffeln und Spargel weich sind.
5. Suppe mit einem Mixer pürieren, bis sie glatt ist, zurück in den Topf geben.
6. Optional Sahne hinzufügen, aufkochen und mit Salz und Pfeffer abschmecken.
7. Spargelspitzen in leicht gesalzenem Wasser 2–3 Minuten bis zur Weichheit kochen. Optional Zitronensaft zur Suppe geben.
8. Heiß servieren, mit Spargelspitzen und frischen Kräutern garnieren.', 1, '353 kcal Gesamtmenge liegt im Suppen-Richtwert (150–400 kcal), nahe am alten Wert (410 kcal) für 1 Portion.', 353, 355, 11, 34, 19, 'Spargel (200 g) = 40 kcal; Zwiebel (50 g) = 13 kcal; Kartoffel (150 g) = 105 kcal; Knoblauch (5 g) = 6 kcal; Olivenöl (10 g) = 88 kcal; Gemüsebrühe (400 g) = 20 kcal; Sahne (10-20%) (50 g) = 80 kcal; Salz und Pfeffer = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Zitronensaft = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Frische Petersilie oder Dill = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Summe = 353 kcal'),
  (38, 'Zwiebelsuppe', 'Suppen', 'Diese Zwiebelsuppe hat einen intensiven Geschmack und ein angenehmes Aroma, besonders durch die Karamellisierung der Zwiebeln und die Zugabe von Weißwein. Das geröstete Baguette mit Käse verleiht dem Gericht zusätzliche Textur und Geschmack.', '[{"name":"Zwiebel","menge_anzeige":"2 Stk (200 g)","gramm":200},{"name":"Knoblauch","menge_anzeige":"2 Zehen","gramm":10},{"name":"Olivenöl","menge_anzeige":"1 EL (15 ml)","gramm":10},{"name":"Butter","menge_anzeige":"1 EL (15 g)","gramm":15},{"name":"Gemüse- oder Rinderbrühe","menge_anzeige":"400 ml","gramm":400},{"name":"Weißwein (trocken)","menge_anzeige":"50 ml","gramm":50},{"name":"Thymian","menge_anzeige":"1/2 TL","gramm":1},{"name":"Lorbeerblatt","menge_anzeige":"1 Stk","gramm":null},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Baguette","menge_anzeige":"1-2 Scheiben","gramm":40},{"name":"Hartkäse","menge_anzeige":"20 g","gramm":20},{"name":"Frische Petersilie","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Zwiebeln in dünne Halbringe schneiden, Knoblauch hacken.
2. Olivenöl und Butter in einem großen Topf erhitzen, Zwiebeln hinzufügen und bei mittlerer Hitze unter Rühren ca. 20–30 Minuten karamellisieren lassen, bis sie weich und goldbraun sind.
3. Knoblauch hinzufügen und 1–2 Minuten weitergaren.
4. Weißwein hinzufügen (optional) und garen, bis die Flüssigkeit fast vollständig verdampft ist.
5. Brühe, Thymian und Lorbeerblatt hinzufügen, zum Kochen bringen, Hitze reduzieren und 15–20 Minuten köcheln lassen.
6. Mit Salz und Pfeffer abschmecken.
7. Baguettescheiben im Ofen rösten, bis sie goldbraun sind.
8. Suppe in ofenfeste Schalen füllen, Baguettescheiben darauflegen und mit geriebenem Käse bestreuen.
9. Unter dem Grill im Ofen backen, bis der Käse schmilzt und goldbraun ist.
10. Heiß servieren und mit frischer Petersilie garnieren.', 1, '506 kcal Gesamtmenge liegt sehr nahe am alten Wert (536 kcal) und passt zu einer Hauptgericht-Portion Zwiebelsuppe gratiniert für 1 Person.', 506, 505, 13, 38, 29, 'Zwiebel (200 g) = 52 kcal; Knoblauch (10 g) = 13 kcal; Olivenöl (10 g) = 88 kcal; Butter (15 g) = 111 kcal; Gemüse- oder Rinderbrühe (400 g) = 20 kcal; Weißwein (trocken) (50 g) = 33 kcal; Thymian (1 g) = 3 kcal; Lorbeerblatt = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Salz und Pfeffer = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Baguette (40 g) = 110 kcal; Hartkäse (20 g) = 76 kcal; Frische Petersilie = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Summe = 506 kcal'),
  (39, 'Eintopf Pichelsteiner', 'Suppen', 'Dieser Eintopf Pichelsteiner ist reich an Geschmack und Nährstoffen dank der Vielzahl an Gemüse und Fleisch. Er eignet sich hervorragend für alle, die ausgewogene Mahlzeiten mit Fleisch und viel Gemüse bevorzugen.', '[{"name":"Rindfleisch (oder eine Mischung aus Schweine- und Rindfleisch)","menge_anzeige":"100 g","gramm":100},{"name":"Kartoffel","menge_anzeige":"2 Stk (300 g)","gramm":300},{"name":"Karotte","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Zwiebel","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Stangensellerie","menge_anzeige":"1 Stiel (50 g)","gramm":50},{"name":"Grüne Bohnen","menge_anzeige":"50 g","gramm":50},{"name":"Weißkohl","menge_anzeige":"100 g","gramm":100},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL (15 ml)","gramm":10},{"name":"Rinderbrühe","menge_anzeige":"500 ml","gramm":500},{"name":"Lorbeerblatt","menge_anzeige":"1 Stk","gramm":null},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Rindfleisch und Kartoffel in Würfel schneiden, Karotte, Zwiebel, Sellerie, grüne Bohnen und Kohl klein schneiden, Knoblauch hacken.
2. Olivenöl in einem großen Topf erhitzen, Zwiebeln glasig anbraten, Rindfleisch hinzufügen und goldbraun anbraten.
3. Knoblauch hinzufügen und eine Minute weitergaren.
4. Rinderbrühe hinzufügen und zum Kochen bringen.
5. Lorbeerblatt, Kartoffeln, Karotte, Sellerie und grüne Bohnen hinzufügen, Hitze reduzieren und 20 Minuten köcheln lassen.
6. Kohl hinzufügen und weitere 10–15 Minuten köcheln lassen, bis alle Zutaten weich sind.
7. Mit Salz und Pfeffer abschmecken.
8. Heiß servieren und mit frischer Petersilie garnieren.', 1, '522 kcal Gesamtmenge passt zu einer sättigenden Eintopf-Hauptgericht-Portion für 1 Person (Richtwert Hauptgericht 300–650 kcal).', 522, 520, 32, 62, 15, 'Rindfleisch (oder eine Mischung aus Schweine- und Rindfleisch) (100 g) = 118 kcal; Kartoffel (300 g) = 210 kcal; Karotte (50 g) = 12 kcal; Zwiebel (50 g) = 13 kcal; Stangensellerie (50 g) = 8 kcal; Grüne Bohnen (50 g) = 16 kcal; Weißkohl (100 g) = 25 kcal; Knoblauch (5 g) = 6 kcal; Olivenöl (10 g) = 88 kcal; Rinderbrühe (500 g) = 25 kcal; Lorbeerblatt = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Salz und Pfeffer = 0 kcal (nach Geschmack/Garnitur, nicht mitgerechnet); Summe = 522 kcal'),
  (40, 'Hühnersuppe mit Brokkoli und Blumenkohl', 'Suppen', 'Diese Hühnersuppe ist reich an Proteinen und Vitaminen dank des Hühnchens und des Gemüses und eignet sich hervorragend als gesundes und sättigendes Gericht.', '[{"name":"Hähnchenbrustfilet","menge_anzeige":"100 g","gramm":100},{"name":"Brokkoli","menge_anzeige":"100 g","gramm":100},{"name":"Blumenkohl","menge_anzeige":"100 g","gramm":100},{"name":"Kartoffel","menge_anzeige":"1 Stk (150 g)","gramm":150},{"name":"Zwiebel","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Karotte","menge_anzeige":"1/2 Stk (50 g)","gramm":50},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL (15 ml)","gramm":10},{"name":"Gemüse- oder Hühnerbrühe","menge_anzeige":"400 ml","gramm":400},{"name":"Lorbeerblatt","menge_anzeige":"1 Stk","gramm":0.3},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Petersilie","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Hähnchenbrust in kleine Stücke schneiden, Kartoffel in Würfel schneiden, Zwiebel und Karotte fein hacken und Knoblauch hacken. 2. Brokkoli und Blumenkohl in kleine Röschen teilen. 3. Olivenöl in einem großen Topf erhitzen, Zwiebeln glasig anbraten, dann Knoblauch und Karotte hinzufügen und 2–3 Minuten weitergaren. 4. Hähnchenbrust hinzufügen und goldbraun anbraten. 5. Brühe und Lorbeerblatt hinzufügen und zum Kochen bringen. 6. Kartoffeln, Brokkoli und Blumenkohl hinzufügen, Hitze reduzieren und 15–20 Minuten köcheln lassen, bis Gemüse und Huhn weich sind. 7. Mit Salz und Pfeffer abschmecken. 8. Heiß servieren und mit frischer Petersilie garnieren.', 1, 'Gesamt-kcal (429) liegt bei n=1 am nächsten am alten Wert (505); die Menge (400 ml Brühe, 100 g Hähnchenbrust) ergibt eine kräftige Einzelportion.', 429, 430, 32, 38, 12, 'Hähnchenbrustfilet 100g=110kcal; Brokkoli 100g=34kcal; Blumenkohl 100g=25kcal; Kartoffel 150g=105kcal; Zwiebel 50g=20kcal; Karotte 50g=17,5kcal; Knoblauch 5g=6,5kcal; Olivenöl 10g=90kcal; Brühe 400ml=20kcal; Petersilie ca. 3g=1kcal; Summe=429kcal'),
  (41, 'Griechischer Salat mit Feta und Oliven', 'Salate', 'Dieser griechische Salat mit Feta und Oliven ist ideal für ein leichtes Mittag- oder Abendessen – ein erfrischendes und nahrhaftes Gericht. Guten Appetit!', '[{"name":"Tomaten","menge_anzeige":"2 Stück (200 g)","gramm":200},{"name":"Gurke","menge_anzeige":"1 Stück (150 g)","gramm":150},{"name":"Rote Zwiebel","menge_anzeige":"1/2 Stück (50 g)","gramm":50},{"name":"Grüne Paprika","menge_anzeige":"1/2 Stück (50 g)","gramm":50},{"name":"Schwarze Oliven","menge_anzeige":"10 Stück (30 g)","gramm":30},{"name":"Feta","menge_anzeige":"50 g","gramm":50},{"name":"Olivenöl","menge_anzeige":"2 EL (30 ml)","gramm":20},{"name":"Zitronensaft","menge_anzeige":"1 EL (15 ml)","gramm":15},{"name":"Getrockneter Oregano","menge_anzeige":"1/2 TL","gramm":1},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Tomaten grob würfeln. 2. Gurke in Halbringe schneiden. 3. Rote Zwiebel in dünne Halbringe schneiden. 4. Grüne Paprika in Streifen schneiden. 5. Alles zusammen mit den schwarzen Oliven in eine Schüssel geben. 6. Feta würfeln und dazugeben. 7. Für das Dressing Olivenöl, Zitronensaft, Oregano, Salz und Pfeffer in einer separaten Schüssel mischen. 8. Salat mit dem Dressing übergießen, vorsichtig mischen und sofort servieren.', 1, 'Gesamt-kcal (434) liegt bei n=1 am nächsten am alten Wert (514); die Zutatenmenge ergibt eine großzügige Einzelportion als Hauptmahlzeit.', 434, 435, 11, 18, 35, 'Tomaten 200g=36kcal; Gurke 150g=18kcal; Rote Zwiebel 50g=20kcal; Grüne Paprika 50g=10kcal; Schwarze Oliven 30g=34,5kcal; Feta 50g=130kcal; Olivenöl 20g=180kcal; Zitronensaft 15g=3,3kcal; Oregano 1g=2,7kcal; Summe=434kcal'),
  (42, 'Salat mit Quinoa, Avocado und roten Bohnen', 'Salate', 'Dieser Salat mit Quinoa, Avocado und roten Bohnen ist ein nahrhaftes und gesundes Mittag- oder Abendessen – ein leichtes und sättigendes Gericht. Guten Appetit!', '[{"name":"Quinoa (gekocht)","menge_anzeige":"1/2 Tasse (90 g)","gramm":90},{"name":"Avocado","menge_anzeige":"1/2 Stück (70 g)","gramm":70},{"name":"Rote Bohnen (konserviert)","menge_anzeige":"1/2 Tasse (80 g)","gramm":80},{"name":"Kirschtomaten","menge_anzeige":"5-6 Stück (100 g)","gramm":100},{"name":"Rote Zwiebel","menge_anzeige":"1/4 Stück (25 g)","gramm":25},{"name":"Frische Kräuter","menge_anzeige":"2 EL (10 g)","gramm":10},{"name":"Zitronensaft","menge_anzeige":"1 EL (15 ml)","gramm":15},{"name":"Olivenöl","menge_anzeige":"1 EL (15 ml)","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Quinoa nach Packungsanweisung kochen und abkühlen lassen. 2. Avocado würfeln, Kirschtomaten halbieren, rote Zwiebel fein würfeln, Kräuter fein hacken. 3. Quinoa, Avocado, rote Bohnen, Kirschtomaten, rote Zwiebel und Kräuter in einer großen Schüssel mischen. 4. Zitronensaft, Olivenöl, Salz und Pfeffer in einer kleinen Schüssel mischen. 5. Salat mit dem Dressing übergießen, vorsichtig mischen und sofort servieren.', 1, 'Gesamt-kcal (425) liegt bei n=1 am nächsten am alten Wert (487); passt als sättigende Einzelportion.', 425, 425, 13, 39, 23, 'Quinoa gekocht 90g=108kcal; Avocado 70g=112kcal; Rote Bohnen 80g=80kcal; Kirschtomaten 100g=18kcal; Rote Zwiebel 25g=10kcal; Frische Kräuter 10g=3,6kcal; Zitronensaft 15g=3,3kcal; Olivenöl 10g=90kcal; Summe=425kcal'),
  (43, 'Salat mit Hähnchen und Gemüse', 'Salate', 'Dieser Salat kombiniert frisches Gemüse und zartes Hähnchenfilet und ergibt ein ausgewogenes Gericht – ideal für ein leichtes und nahrhaftes Mittag- oder Abendessen.', '[{"name":"Hähnchenfilet","menge_anzeige":"200 g","gramm":200},{"name":"Salatblätter","menge_anzeige":"100 g","gramm":100},{"name":"Gurken","menge_anzeige":"2 Stück (ca. 150 g je Stück)","gramm":300},{"name":"Kirschtomaten","menge_anzeige":"10 Stück","gramm":180},{"name":"Paprika","menge_anzeige":"1 Stück","gramm":100},{"name":"Rote Zwiebel","menge_anzeige":"1/2 Stück","gramm":50},{"name":"Olivenöl","menge_anzeige":"2 EL","gramm":20},{"name":"Zitronensaft","menge_anzeige":"1 EL","gramm":15},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Hähnchenfilet braten oder kochen, bis es gar ist (ca. 7–10 Minuten), dann in Scheiben oder Würfel schneiden. 2. Gurken in Halbringe schneiden, Kirschtomaten halbieren, Paprika in Streifen schneiden, rote Zwiebel in dünne Halbringe schneiden. 3. Salatblätter auf einen Teller legen, Gemüse (Gurken, Kirschtomaten, Paprika, rote Zwiebel) und Hähnchenfilet hinzufügen. 4. Salat mit Olivenöl und Zitronensaft übergießen, nach Geschmack salzen und pfeffern. 5. Vor dem Servieren gut mischen.', 3, 'Gesamt-kcal (533) geteilt durch 3 (178) liegt am nächsten am alten Wert (200); ergibt drei realistische Salatportionen.', 533, 180, 18, 8, 8, 'Hähnchenfilet 200g=220kcal; Salatblätter 100g=15kcal; Gurken 300g=36kcal; Kirschtomaten 180g=32,4kcal; Paprika 100g=26kcal; Rote Zwiebel 50g=20kcal; Olivenöl 20g=180kcal; Zitronensaft 15g=3,3kcal; Summe=533kcal'),
  (44, 'Salat mit Lachs und frischem Gemüse', 'Salate', 'Dieser Salat kombiniert gesunde Fette aus Avocado und Lachs mit frischem Gemüse und einem leichten Dressing – ideal für ein gesundes und sättigendes Mittag- oder Abendessen.', '[{"name":"Lachsfilet","menge_anzeige":"200 g","gramm":200},{"name":"Salatblätter","menge_anzeige":"100 g","gramm":100},{"name":"Gurken","menge_anzeige":"2 Stück","gramm":300},{"name":"Avocado","menge_anzeige":"1 Stück","gramm":140},{"name":"Kirschtomaten","menge_anzeige":"10 Stück","gramm":180},{"name":"Olivenöl","menge_anzeige":"2 EL","gramm":20},{"name":"Zitronensaft","menge_anzeige":"1 EL","gramm":15},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Dill","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Lachs braten oder backen, bis er gar ist, dann in Scheiben schneiden. 2. Gurken, Avocado und Kirschtomaten schneiden. 3. Salatblätter auf einen Teller legen, geschnittenes Gemüse und Lachs hinzufügen. 4. Mit Olivenöl und Zitronensaft beträufeln, nach Geschmack salzen und pfeffern. 5. Dill hinzufügen und gut mischen.', 3, 'Gesamt-kcal (908) geteilt durch 3 (303) liegt am nächsten am alten Wert (280); 200 g Lachs und eine ganze Avocado reichen für mehrere Portionen.', 908, 305, 16, 6, 23, 'Lachsfilet 200g=416kcal; Salatblätter 100g=15kcal; Gurken 300g=36kcal; Avocado 140g=224kcal; Kirschtomaten 180g=32,4kcal; Olivenöl 20g=180kcal; Zitronensaft 15g=3,3kcal; Dill ca. 2g=0,8kcal; Summe=908kcal'),
  (45, 'Salat mit Nüssen und Trockenfrüchten', 'Salate', 'Dieser Salat kombiniert frisches Gemüse, Nüsse und Trockenfrüchte zu einem ausgewogenen Gericht – ideal für ein leichtes und nahrhaftes Mittag- oder Abendessen.', '[{"name":"Salatblätter","menge_anzeige":"100 g","gramm":100},{"name":"Nüsse (Walnüsse oder Mandeln)","menge_anzeige":"50 g","gramm":50},{"name":"Trockenfrüchte (Rosinen, getrocknete Aprikosen)","menge_anzeige":"50 g","gramm":50},{"name":"Feta","menge_anzeige":"100 g","gramm":100},{"name":"Olivenöl","menge_anzeige":"2 EL","gramm":20},{"name":"Balsamico-Essig","menge_anzeige":"1 EL","gramm":15},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Trockenfrüchte und Feta schneiden. 2. Salatblätter auf einen Teller legen. 3. Nüsse, Trockenfrüchte und Feta hinzufügen. 4. Mit Olivenöl und Balsamico-Essig beträufeln, nach Geschmack salzen und pfeffern. 5. Gut mischen.', 4, 'Gesamt-kcal (935) geteilt durch 4 (234) liegt sehr nah am alten Wert (230); passt gut zu vier Beilagen-Portionen.', 935, 235, 6, 11, 18, 'Salatblätter 100g=15kcal; Nüsse 50g=327kcal; Trockenfrüchte 50g=140kcal; Feta 100g=260kcal; Olivenöl 20g=180kcal; Balsamico-Essig 15g=13,2kcal; Summe=935kcal'),
  (46, 'Salat mit Thunfisch und Ei', 'Salate', 'Dieser Salat kombiniert gesunde Fette und Proteine aus Thunfisch und Ei mit frischem Gemüse und einem leichten Dressing – ideal für ein gesundes und sättigendes Mittag- oder Abendessen.', '[{"name":"Konservierter Thunfisch","menge_anzeige":"200 g","gramm":200},{"name":"Eier","menge_anzeige":"2 Stück","gramm":110},{"name":"Salatblätter","menge_anzeige":"100 g","gramm":100},{"name":"Kirschtomaten","menge_anzeige":"10 Stück","gramm":180},{"name":"Gurken","menge_anzeige":"2 Stück","gramm":300},{"name":"Olivenöl","menge_anzeige":"2 EL","gramm":20},{"name":"Zitronensaft","menge_anzeige":"1 EL","gramm":15},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Eier hart kochen und in Scheiben schneiden. 2. Gurken und Kirschtomaten schneiden. 3. Salatblätter auf einen Teller legen, Thunfisch, Eier und geschnittenes Gemüse hinzufügen. 4. Mit Olivenöl und Zitronensaft beträufeln, nach Geschmack salzen und pfeffern. 5. Gut mischen.', 3, 'Gesamt-kcal (647) geteilt durch 3 (216) liegt am nächsten am alten Wert (240); die 2 Eier verteilen sich dabei ungleich auf die Portionen (ca. 2/3 Ei je Portion), da sie in Scheiben im Salat verteilt werden.', 647, 215, 22, 5, 12, 'Thunfisch 200g=210kcal; Eier 110g=170,5kcal; Salatblätter 100g=15kcal; Kirschtomaten 180g=32,4kcal; Gurken 300g=36kcal; Olivenöl 20g=180kcal; Zitronensaft 15g=3,3kcal; Summe=647kcal'),
  (47, 'Kohlsalat mit Karotten und Apfel', 'Salate', 'Dieser leichte und kalorienarme Salat ist reich an Vitaminen und Ballaststoffen dank frischem Gemüse und Obst. Er eignet sich hervorragend als Beilage oder Hauptgericht für ein leichtes Mittag- oder Abendessen.', '[{"name":"Weißkohl","menge_anzeige":"300 g","gramm":300},{"name":"Karotte","menge_anzeige":"1 Stück","gramm":100},{"name":"Apfel","menge_anzeige":"1 Stück","gramm":150},{"name":"Zitronensaft","menge_anzeige":"2 EL","gramm":30},{"name":"Olivenöl","menge_anzeige":"2 EL","gramm":20},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Kohl fein schneiden. 2. Karotte und Apfel grob raspeln. 3. Kohl, Karotte und Apfel mischen. 4. Mit Zitronensaft und Olivenöl beträufeln, nach Geschmack salzen und pfeffern. 5. Gut mischen.', 2, 'Bei n=3 läge die Portion (125 kcal) unter dem Richtwert für Salate (150–400 kcal); n=2 (187 kcal) ist realistisch und noch nah am alten Wert (150).', 375, 185, 3, 20, 11, 'Weißkohl 300g=75kcal; Karotte 100g=35kcal; Apfel 150g=78kcal; Zitronensaft 30g=6,6kcal; Olivenöl 20g=180kcal; Summe=375kcal'),
  (48, 'Rote-Bete-Salat mit Ziegenkäse', 'Salate', 'Dieser Salat ist reich an Proteinen und gesunden Fetten dank Ziegenkäse und Walnüssen und enthält durch die Rote Bete auch Kohlenhydrate und Ballaststoffe. Er eignet sich hervorragend für alle, die vollwertige Gerichte mit hohem Proteingehalt bevorzugen.', '[{"name":"Rote Bete","menge_anzeige":"2 Stück","gramm":200},{"name":"Ziegenkäse","menge_anzeige":"100 g","gramm":100},{"name":"Walnüsse","menge_anzeige":"50 g","gramm":50},{"name":"Rucola","menge_anzeige":"100 g","gramm":100},{"name":"Olivenöl","menge_anzeige":"2 EL","gramm":20},{"name":"Balsamico-Essig","menge_anzeige":"1 EL","gramm":15},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Rote Bete kochen oder backen, bis sie gar ist, dann in Würfel schneiden. 2. Ziegenkäse schneiden. 3. Rucola, Rote Bete und Ziegenkäse mischen, Walnüsse hinzufügen. 4. Mit Olivenöl und Balsamico-Essig beträufeln, nach Geschmack salzen und pfeffern. 5. Gut mischen.', 4, 'Gesamt-kcal (921) geteilt durch 4 (230) liegt fast exakt am alten Wert (220); ergibt vier realistische Portionen.', 921, 230, 9, 6, 19, 'Rote Bete 200g=86kcal; Ziegenkäse 100g=290kcal; Walnüsse 50g=327kcal; Rucola 100g=25kcal; Olivenöl 20g=180kcal; Balsamico-Essig 15g=13,2kcal; Summe=921kcal'),
  (49, 'Caesar Salat mit Hähnchen und leichtem Dressing', 'Salate', 'Dieser Salat ist reich an Proteinen, was ihn zu einer hervorragenden Wahl für eine proteinreiche und relativ kohlenhydratarme Mahlzeit macht. Er enthält auch gesunde Fette aus Olivenöl und Parmesan, was zu einem vollwertigen und schmackhaften Gericht beiträgt.', '[{"name":"Hähnchenfilet","menge_anzeige":"200 g","gramm":200},{"name":"Salatblätter (Römersalat)","menge_anzeige":"100 g","gramm":100},{"name":"Kirschtomaten","menge_anzeige":"10 Stück","gramm":180},{"name":"Parmesan","menge_anzeige":"50 g","gramm":50},{"name":"Brot für Croutons","menge_anzeige":"2 Scheiben","gramm":50},{"name":"Olivenöl","menge_anzeige":"2 EL","gramm":20},{"name":"Zitronensaft","menge_anzeige":"1 EL","gramm":15},{"name":"Naturjoghurt","menge_anzeige":"2 EL","gramm":30},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Hähnchenfilet braten, bis es gar ist, und in Scheiben schneiden. 2. Brot in Würfel schneiden und in Olivenöl goldbraun rösten. 3. Salatblätter auf einen Teller legen, Hähnchen, Kirschtomaten und Croutons hinzufügen. 4. Für das Dressing Joghurt, Zitronensaft, Knoblauch, Salz und Pfeffer im Mixer mischen. 5. Salat mit dem Dressing übergießen und mit geriebenem Parmesan bestreuen, gut mischen.', 3, 'Gesamt-kcal (808) geteilt durch 3 (269) liegt am nächsten am alten Wert (250).', 808, 270, 24, 12, 13, 'Hähnchenfilet 200g=220kcal; Salatblätter 100g=15kcal; Kirschtomaten 180g=32,4kcal; Parmesan 50g=200kcal; Brot 50g=132,5kcal; Olivenöl 20g=180kcal; Zitronensaft 15g=3,3kcal; Naturjoghurt 30g=18,6kcal; Knoblauch 5g=6,5kcal; Summe=808kcal'),
  (50, 'Salat mit Garnelen und Avocado', 'Salate', 'Dieser leichte und frische Salat ergänzt Ihre Ernährung mit wichtigen Nährstoffen und einem hervorragenden Geschmack.', '[{"name":"Garnelen (geschält)","menge_anzeige":"200 g","gramm":200},{"name":"Avocado","menge_anzeige":"1 Stück","gramm":140},{"name":"Gurken","menge_anzeige":"2 Stück","gramm":300},{"name":"Kirschtomaten","menge_anzeige":"10 Stück","gramm":180},{"name":"Salatblätter","menge_anzeige":"100 g","gramm":100},{"name":"Olivenöl","menge_anzeige":"2 EL","gramm":20},{"name":"Zitronensaft","menge_anzeige":"1 EL","gramm":15},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Garnelen in Salzwasser 3–5 Minuten kochen und abkühlen lassen. 2. Avocado, Gurken und Kirschtomaten schneiden. 3. Salatblätter auf einen Teller legen, Garnelen, Avocado und geschnittenes Gemüse hinzufügen. 4. Mit Olivenöl und Zitronensaft beträufeln, nach Geschmack salzen und pfeffern. 5. Gut mischen.', 3, 'Gesamt-kcal (671) geteilt durch 3 (224) liegt fast exakt am alten Wert (220).', 671, 225, 16, 6, 15, 'Garnelen 200g=180kcal; Avocado 140g=224kcal; Gurken 300g=36kcal; Kirschtomaten 180g=32,4kcal; Salatblätter 100g=15kcal; Olivenöl 20g=180kcal; Zitronensaft 15g=3,3kcal; Summe=671kcal'),
  (51, 'Salat mit Hühnerleber', 'Salate', 'Dieser Salat kombiniert zarte Hühnerleber und frisches Gemüse, wodurch ein ausgewogenes Gericht entsteht, das sich hervorragend für ein leichtes und nahrhaftes Mittag- oder Abendessen eignet.', '[{"name":"Hühnerleber","menge_anzeige":"300 g","gramm":300},{"name":"Salatblätter","menge_anzeige":"100 g","gramm":100},{"name":"Gurken","menge_anzeige":"2 Stück","gramm":300},{"name":"Kirschtomaten","menge_anzeige":"10 Stück","gramm":180},{"name":"Rote Zwiebel","menge_anzeige":"1/2 Stück","gramm":50},{"name":"Karotte","menge_anzeige":"1 Stück","gramm":100},{"name":"Olivenöl","menge_anzeige":"2 EL","gramm":20},{"name":"Zitronensaft","menge_anzeige":"1 EL","gramm":15},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Dill","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Hühnerleber waschen und putzen. 2. 1 EL Olivenöl in einer Pfanne erhitzen, Hühnerleber bei mittlerer Hitze braten, bis sie gar ist (ca. 5–7 Minuten pro Seite), abkühlen lassen und in Scheiben schneiden. 3. Gurken in Halbringe schneiden, Kirschtomaten halbieren, rote Zwiebel in dünne Halbringe schneiden, Karotte grob raspeln. 4. Salatblätter auf einen Teller legen, geschnittenes Gemüse und Hühnerleber hinzufügen. 5. Salat mit restlichem Olivenöl und Zitronensaft beträufeln, nach Geschmack salzen und pfeffern. 6. Dill hacken und über den Salat streuen. 7. Vor dem Servieren gut mischen.', 3, 'Gesamt-kcal (728) geteilt durch 3 (243) liegt fast exakt am alten Wert (250).', 728, 245, 21, 9, 13, 'Hühnerleber 300g=405kcal; Salatblätter 100g=15kcal; Gurken 300g=36kcal; Kirschtomaten 180g=32,4kcal; Rote Zwiebel 50g=20kcal; Karotte 100g=35kcal; Olivenöl 20g=180kcal; Zitronensaft 15g=3,3kcal; Dill ca. 2g=0,8kcal; Summe=728kcal'),
  (52, 'Warmer Salat mit Rindfleisch', 'Salate', 'Dieser warme Salat mit Rindfleisch eignet sich hervorragend für ein sättigendes, nahrhaftes Mittag- oder Abendessen. Er ist reich an Proteinen und frischem Gemüse, stillt den Hunger und liefert Energie für den ganzen Tag.', '[{"name":"Rinderfilet","menge_anzeige":"300 g","gramm":300},{"name":"Salatblätter (Rucola, Römersalat oder Mix)","menge_anzeige":"100 g","gramm":100},{"name":"Kirschtomaten","menge_anzeige":"10 Stück","gramm":180},{"name":"Paprika","menge_anzeige":"1 Stück","gramm":100},{"name":"Rote Zwiebel","menge_anzeige":"1/2 Stück","gramm":50},{"name":"Champignons","menge_anzeige":"150 g","gramm":150},{"name":"Olivenöl","menge_anzeige":"2 EL","gramm":20},{"name":"Sojasauce","menge_anzeige":"2 EL","gramm":30},{"name":"Zitronensaft","menge_anzeige":"1 EL","gramm":15},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Dill oder Petersilie","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Rinderfilet in dünne Streifen schneiden. 1 EL Olivenöl in einer Pfanne erhitzen, Rindfleisch bei mittlerer Hitze braten, bis es gar ist (ca. 5–7 Minuten), mit Salz und Pfeffer würzen, Sojasauce hinzufügen und weitere 1–2 Minuten braten. 2. Champignons in dünne Scheiben schneiden und in derselben Pfanne goldbraun braten (ca. 5 Minuten). 3. Kirschtomaten halbieren, Paprika in Streifen schneiden, rote Zwiebel in dünne Halbringe schneiden. 4. Salatblätter auf einen Teller legen, gebratene Pilze, Kirschtomaten, Paprika und rote Zwiebel hinzufügen, warmes Rindfleisch daraufgeben. 5. Mit restlichem Olivenöl und Zitronensaft beträufeln, nach Geschmack salzen und pfeffern. 6. Dill oder Petersilie hacken und über den Salat streuen.', 3, 'Gesamt-kcal (728) geteilt durch 3 (243) liegt am nächsten am alten Wert (300); 300 g Rinderfilet reichen für mehrere Portionen.', 728, 245, 25, 7, 12, 'Rinderfilet 300g=399kcal; Salatblätter 100g=15kcal; Kirschtomaten 180g=32,4kcal; Paprika 100g=26kcal; Rote Zwiebel 50g=20kcal; Champignons 150g=33kcal; Olivenöl 20g=180kcal; Sojasauce 30g=18kcal; Zitronensaft 15g=3,3kcal; Dill/Petersilie ca. 2g=0,8kcal; Summe=728kcal'),
  (53, 'Salat mit Meeresfrüchten', 'Salate', 'Dieser Salat kombiniert verschiedene Meeresfrüchte und frisches Gemüse und schafft ein köstliches und gesundes Gericht, das sich ideal für ein leichtes und nahrhaftes Mittag- oder Abendessen eignet.', '[{"name":"Geschälte Garnelen","menge_anzeige":"200 g","gramm":200},{"name":"Geschälte Miesmuscheln","menge_anzeige":"150 g","gramm":150},{"name":"Salatblätter (Römersalat, Rucola oder Mix)","menge_anzeige":"100 g","gramm":100},{"name":"Gurken","menge_anzeige":"2 Stück","gramm":300},{"name":"Kirschtomaten","menge_anzeige":"10 Stück","gramm":200},{"name":"Avocado","menge_anzeige":"1 Stück","gramm":200},{"name":"Rote Zwiebel","menge_anzeige":"1/2 Stück","gramm":50},{"name":"Olivenöl","menge_anzeige":"2 EL","gramm":20},{"name":"Zitronensaft","menge_anzeige":"1 EL","gramm":15},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Kräuter","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Garnelen in Salzwasser ca. 3–5 Minuten kochen, bis sie gar sind, dann abkühlen lassen. 2. Miesmuscheln 5–7 Minuten kochen und ebenfalls abkühlen lassen. 3. Gurken in Halbringe schneiden, Kirschtomaten halbieren, Avocado würfeln und die rote Zwiebel in dünne Halbringe schneiden. 4. Salatblätter auf einen Teller legen, das geschnittene Gemüse (Gurken, Kirschtomaten, Avocado, rote Zwiebel) sowie die Meeresfrüchte (Garnelen, Miesmuscheln) daraufgeben. 5. Salat mit Olivenöl und Zitronensaft beträufeln, nach Geschmack salzen und pfeffern. 6. Kräuter hacken und über den Salat streuen.', 4, '916 kcal geteilt durch 4 Portionen ergibt ca. 230 kcal, was dem alten Wert (250 kcal) am nächsten kommt und für einen proteinreichen Salat plausibel ist.', 916, 230, 17, 7, 15, 'Garnelen 200g=180; Miesmuscheln 150g=128; Salatblätter 100g=18; Gurken 300g=36; Kirschtomaten 200g=36; Avocado 200g=320; Rote Zwiebel 50g=15; Olivenöl 20g=180; Zitronensaft 15g=3; Kräuter/Gewürze=0; Summe=916 kcal'),
  (54, 'Salat mit Quinoa und Avocado', 'Salate', 'Der Salat mit Quinoa und Avocado ist ein Gericht, das schnell zuzubereiten ist. Er ist reich an Proteinen durch Gemüse und Quinoa. Ein leichtes Dressing verleiht ihm einen frischen und würzigen Geschmack.', '[{"name":"Quinoa","menge_anzeige":"45 g","gramm":45},{"name":"Wasser","menge_anzeige":"120 ml","gramm":120},{"name":"Avocado","menge_anzeige":"100 g","gramm":100},{"name":"Gurke","menge_anzeige":"100 g","gramm":100},{"name":"Kirschtomaten","menge_anzeige":"75 g","gramm":75},{"name":"Rote Zwiebel","menge_anzeige":"25 g","gramm":25},{"name":"Petersilie","menge_anzeige":"10 g","gramm":10},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Zitronensaft","menge_anzeige":"1 TL","gramm":5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Quinoa unter kaltem Wasser abspülen, um die Bitterkeit zu entfernen. 2. 1/2 Tasse (120 ml) Wasser zum Kochen bringen, Quinoa hinzufügen und bei mittlerer Hitze ca. 15 Minuten garen. Vom Herd nehmen, kurz ziehen lassen und abkühlen lassen. 3. Avocado würfeln, Gurke in Halbringe schneiden, Kirschtomaten halbieren, rote Zwiebel in dünne Halbringe schneiden und Petersilie fein hacken. 4. Abgekühlte Quinoa, geschnittenes Gemüse und Petersilie in einer großen Schüssel mischen. 5. Für das Dressing Olivenöl und Zitronensaft in einer separaten Schüssel verrühren, nach Geschmack salzen und pfeffern. 6. Salat mit dem Dressing übergießen und gut mischen, bis alle Zutaten gleichmäßig überzogen sind.', 1, 'Die Gesamtmenge ergibt bei 1 Portion ca. 455 kcal, was nahe am alten Wert (403 kcal) liegt und für ein sättigendes Salatgericht mit Quinoa realistisch ist.', 453, 455, 10, 38, 29, 'Quinoa 45g=166; Wasser 120ml=0; Avocado 100g=160; Gurke 100g=12; Kirschtomaten 75g=14; Rote Zwiebel 25g=8; Petersilie 10g=4; Olivenöl 10g=90; Zitronensaft 5g=1; Summe=453 kcal'),
  (55, 'Salat mit gebackenem Kürbis und Spinat', 'Salate', 'Dieser Salat ist ideal für ein leichtes Mittag- oder Abendessen, da er eine perfekte Balance aus süßen und herzhaften Aromen bietet und ausreichend Energie für den Tag liefert. Guten Appetit!', '[{"name":"Kürbis","menge_anzeige":"100 g","gramm":100},{"name":"Spinat","menge_anzeige":"50 g","gramm":50},{"name":"Feta","menge_anzeige":"25 g","gramm":25},{"name":"Pinienkerne","menge_anzeige":"10 g","gramm":10},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Honig","menge_anzeige":"1/2 TL","gramm":3.5},{"name":"Balsamico-Essig","menge_anzeige":"1 TL","gramm":5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Ofen auf 200 °C vorheizen. Kürbis in Würfel schneiden, mit 1/2 EL Olivenöl bestreichen, salzen und pfeffern. 2. Kürbis auf ein Backblech legen und ca. 25–30 Minuten backen, bis er weich ist. 3. Pinienkerne in einer trockenen Pfanne ca. 2–3 Minuten goldbraun rösten und abkühlen lassen. 4. Spinat auf einen Teller legen, den gebackenen Kürbis daraufgeben, Feta darüber zerbröckeln und die Pinienkerne hinzufügen. 5. Für das Dressing restliches Olivenöl, Honig und Balsamico-Essig in einer kleinen Schüssel verrühren, nach Geschmack salzen und pfeffern. 6. Salat mit dem Dressing übergießen und vorsichtig mischen, bis alle Zutaten gleichmäßig überzogen sind.', 1, 'Bei 1 Portion ergeben sich ca. 275 kcal, was gut zum alten Wert (317 kcal) passt und für einen Beilagensalat realistisch ist.', 276, 275, 7, 10, 22, 'Kürbis 100g=26; Spinat 50g=12; Feta 25g=66; Pinienkerne 10g=67; Olivenöl 10g=90; Honig 3,5g=11; Balsamico-Essig 5g=4; Summe=276 kcal'),
  (56, 'Salat mit Trauben, Nüssen und Brie-Käse', 'Salate', 'Dieser Salat ist ideal für ein leichtes Mittag- oder Abendessen und bietet eine wunderbare Kombination aus süßen, cremigen und knackigen Elementen. Er ist nicht nur ein kulinarischer Genuss, sondern liefert auch wertvolle Nährstoffe. Guten Appetit!', '[{"name":"Salatblätter (Rucola, Spinat oder Mix)","menge_anzeige":"50 g","gramm":50},{"name":"Trauben (grün oder rot)","menge_anzeige":"100 g","gramm":100},{"name":"Brie-Käse","menge_anzeige":"30 g","gramm":30},{"name":"Walnüsse","menge_anzeige":"15 g","gramm":15},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Balsamico-Essig","menge_anzeige":"1 TL","gramm":5},{"name":"Honig","menge_anzeige":"1/2 TL","gramm":3.5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Trauben waschen und halbieren. Brie-Käse in kleine Stücke schneiden. 2. Walnüsse in einer trockenen Pfanne goldbraun rösten. 3. Salatblätter auf einen Teller legen, Trauben und Brie-Käse hinzufügen, geröstete Walnüsse darüberstreuen. 4. Für das Dressing Olivenöl, Balsamico-Essig und Honig in einer kleinen Schüssel verrühren, nach Geschmack salzen und pfeffern. 5. Salat mit dem Dressing übergießen und vorsichtig mischen, bis alle Zutaten gleichmäßig überzogen sind.', 1, '1 Portion mit ca. 380 kcal liegt nah am alten Wert (408 kcal) und ist für diesen Salat mit Käse und Nüssen realistisch.', 379, 380, 10, 22, 29, 'Salatblätter 50g=9; Trauben 100g=67; Brie-Käse 30g=100; Walnüsse 15g=98; Olivenöl 10g=90; Balsamico-Essig 5g=4; Honig 3,5g=11; Summe=379 kcal'),
  (57, 'Fleischsalat mit Kohl und Karotten', 'Salate', 'Dieser Fleischsalat ist ideal für ein sättigendes Mittag- oder Abendessen und besticht durch seine frischen, knackigen Zutaten und den erfrischenden Geschmack des Dressings. Guten Appetit!', '[{"name":"Rind- oder Hühnerfleisch (gekocht oder gebraten)","menge_anzeige":"100 g","gramm":100},{"name":"Weißkohl","menge_anzeige":"100 g","gramm":100},{"name":"Karotte","menge_anzeige":"1 Stück","gramm":60},{"name":"Frühlingszwiebeln","menge_anzeige":"1-2 Stängel","gramm":15},{"name":"Dill","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Zitronensaft","menge_anzeige":"1 TL","gramm":5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Gekochtes oder gebratenes Fleisch in dünne Scheiben oder Würfel schneiden. 2. Kohl in dünne Streifen schneiden, Karotte grob raspeln, Frühlingszwiebeln fein hacken und Dill fein hacken. 3. Fleisch, Kohl, Karotte, Frühlingszwiebeln und Dill in einer großen Schüssel mischen. 4. Für das Dressing Olivenöl und Zitronensaft in einer separaten Schüssel verrühren, nach Geschmack salzen und pfeffern. 5. Salat mit dem Dressing übergießen und gut mischen, bis alle Zutaten gleichmäßig überzogen sind.', 1, '1 Portion mit ca. 335 kcal liegt am nächsten am alten Wert (392 kcal) unter den geprüften Teilungen und ist für einen Fleischsalat plausibel.', 336, 335, 31, 10, 18, 'Rind-/Hühnerfleisch 100g=190; Weißkohl 100g=25; Karotte 60g=25; Frühlingszwiebeln 15g=5; Olivenöl 10g=90; Zitronensaft 5g=1; Summe=336 kcal'),
  (58, 'Salat mit Avocado und Dosen-Thunfisch', 'Salate', 'Dieser Salat mit Avocado und Dosen-Thunfisch ist eine hervorragende Wahl für ein leichtes, aber nahrhaftes Mittag- oder Abendessen. Die Kombination aus frischem Gemüse, reichhaltigem Thunfisch und cremiger Avocado macht ihn nicht nur lecker, sondern auch gesund.', '[{"name":"Dosen-Thunfisch (im eigenen Saft)","menge_anzeige":"200 g","gramm":200},{"name":"Avocado","menge_anzeige":"1 Stück","gramm":200},{"name":"Gurken","menge_anzeige":"2 Stück","gramm":300},{"name":"Kirschtomaten","menge_anzeige":"10 Stück","gramm":200},{"name":"Rote Zwiebel","menge_anzeige":"1/2 Stück","gramm":50},{"name":"Salatblätter (Rucola, Römersalat oder Mix)","menge_anzeige":"100 g","gramm":100},{"name":"Olivenöl","menge_anzeige":"2 EL","gramm":20},{"name":"Zitronensaft","menge_anzeige":"1 EL","gramm":15},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Flüssigkeit aus dem Dosen-Thunfisch abgießen und den Thunfisch mit einer Gabel zerkleinern. 2. Avocado würfeln, Gurken in Halbringe schneiden, Kirschtomaten halbieren und rote Zwiebel in dünne Ringe schneiden. Salatblätter waschen und trocknen. 3. Thunfisch, Avocado, Gurken, Kirschtomaten und rote Zwiebel in einer großen Schüssel mischen, Salatblätter hinzufügen. 4. Für das Dressing Olivenöl und Zitronensaft in einer separaten Schüssel verrühren, über den Salat geben und nach Geschmack salzen und pfeffern. 5. Salat vor dem Servieren gut mischen.', 1, 'Die Zutatenmenge reicht für 1 großzügige Portion (ca. 840 kcal), was dem alten Wert (894 kcal) am nächsten kommt; die Menge an Thunfisch und Avocado macht dies zu einem sehr kalorienreichen Einzelsalat.', 840, 840, 62, 23, 55, 'Dosen-Thunfisch 200g=232; Avocado 200g=320; Gurken 300g=36; Kirschtomaten 200g=36; Rote Zwiebel 50g=15; Salatblätter 100g=18; Olivenöl 20g=180; Zitronensaft 15g=3; Summe=840 kcal'),
  (59, 'Salat mit Wachteleiern', 'Salate', 'Dieser Salat mit Wachteleiern ist leicht und nahrhaft und eignet sich hervorragend für ein gesundes Mittag- oder Abendessen. Guten Appetit!', '[{"name":"Wachteleier","menge_anzeige":"5 Stück","gramm":45},{"name":"Salatblätter (Rucola, Spinat oder Mix)","menge_anzeige":"50 g","gramm":50},{"name":"Kirschtomaten","menge_anzeige":"5-6 Stück","gramm":110},{"name":"Gurke","menge_anzeige":"1/2 Stück","gramm":75},{"name":"Radieschen","menge_anzeige":"3 Stück","gramm":45},{"name":"Rote Zwiebel","menge_anzeige":"1/4 Stück","gramm":25},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Zitronensaft","menge_anzeige":"1 TL","gramm":5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Kräuter (Dill oder Petersilie)","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Wachteleier in kochendem Wasser ca. 4–5 Minuten hart kochen, abkühlen lassen, schälen und halbieren. 2. Kirschtomaten halbieren, Gurke in Halbringe schneiden, Radieschen in dünne Scheiben schneiden, rote Zwiebel in dünne Halbringe schneiden und frische Kräuter fein hacken. 3. Salatblätter auf einen Teller legen, Wachteleier, Kirschtomaten, Gurke, Radieschen und rote Zwiebel hinzufügen. 4. Für das Dressing Olivenöl und Zitronensaft in einer kleinen Schüssel verrühren, nach Geschmack salzen und pfeffern. 5. Salat mit dem Dressing übergießen und gut mischen, bis alle Zutaten gleichmäßig überzogen sind. 6. Frische Kräuter über den Salat streuen.', 1, '1 Portion mit ca. 215 kcal liegt fast exakt beim alten Wert (220 kcal) und passt gut zu einem leichten Salat.', 215, 215, 9, 9, 15, 'Wachteleier 45g=71; Salatblätter 50g=9; Kirschtomaten 110g=20; Gurke 75g=9; Radieschen 45g=7; Rote Zwiebel 25g=8; Olivenöl 10g=90; Zitronensaft 5g=1; Summe=215 kcal'),
  (60, 'Salat mit Kartoffeln, frischen Gurken und Eiern', 'Salate', 'Dieser Salat ist ideal für ein sättigendes Mittag- oder Abendessen und besticht durch seine frischen, knackigen Zutaten und den mild-würzigen Geschmack des Dressings. Guten Appetit!', '[{"name":"Kartoffel","menge_anzeige":"150 g","gramm":150},{"name":"Gurke","menge_anzeige":"100 g","gramm":100},{"name":"Ei","menge_anzeige":"1 Stück","gramm":55},{"name":"Frühlingszwiebeln","menge_anzeige":"1-2 Stängel","gramm":15},{"name":"Dill","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Saure Sahne oder Mayonnaise","menge_anzeige":"1 EL","gramm":15},{"name":"Senf","menge_anzeige":"1/2 TL","gramm":2.5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Kartoffeln in der Schale kochen, bis sie gar sind (ca. 20–25 Minuten), abkühlen lassen, schälen und würfeln. 2. Ei hart kochen (ca. 10 Minuten), abkühlen lassen, schälen und würfeln. 3. Gurke in Halbringe oder Würfel schneiden, Frühlingszwiebeln fein hacken und Dill fein hacken. 4. Kartoffeln, Ei, Gurke, Frühlingszwiebeln und Dill in einer großen Schüssel mischen. 5. Für das Dressing saure Sahne oder Mayonnaise mit Senf verrühren, nach Geschmack salzen und pfeffern. 6. Salat mit dem Dressing übergießen und gut mischen, bis alle Zutaten gleichmäßig überzogen sind.', 1, '1 Portion mit ca. 250 kcal liegt am nächsten am alten Wert (303 kcal) unter den geprüften Teilungen.', 252, 250, 12, 34, 8, 'Kartoffel 150g=131; Gurke 100g=12; Ei 55g=85; Frühlingszwiebeln 15g=5; Saure Sahne 15g=17; Senf 2,5g=2; Summe=252 kcal'),
  (61, 'Gebackener Lachs mit Zitrone und Kräutern', 'Hauptgerichte', 'Dieser gebackene Lachs mit Zitrone und Kräutern ist ideal für ein leichtes Mittag- oder Abendessen und besticht durch seinen frischen, aromatischen Geschmack.', '[{"name":"Lachsfilet","menge_anzeige":"150-200 g","gramm":175},{"name":"Zitrone","menge_anzeige":"1/4 Stück","gramm":25},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Salz","menge_anzeige":"1/4 TL","gramm":1.5},{"name":"Schwarzer Pfeffer","menge_anzeige":"1/8 TL","gramm":0.25},{"name":"Frischer Dill","menge_anzeige":"ein paar Zweige","gramm":2},{"name":"Frischer Thymian","menge_anzeige":"ein paar Zweige","gramm":2},{"name":"Frischer Rosmarin","menge_anzeige":"ein paar Zweige","gramm":2}]'::jsonb, '1. Ofen auf 200 °C vorheizen. 2. Zitrone waschen und in dünne Scheiben schneiden. Knoblauch schälen und fein hacken. Dill fein hacken, einige Zweige Thymian und Rosmarin für die Dekoration ganz lassen. 3. Für die Marinade Olivenöl, gehackten Knoblauch, Dill, Salz und schwarzen Pfeffer in einer kleinen Schüssel mischen. 4. Lachsfilet auf ein mit Backpapier oder Folie ausgelegtes Backblech legen und mit der Marinade bestreichen. Zitronenscheiben daraufgeben und mit Thymian- und Rosmarinzweigen dekorieren. 5. Backblech in den vorgeheizten Ofen geben und den Lachs 15–20 Minuten backen, je nach Dicke des Filets, bis er gar ist und sich leicht mit einer Gabel zerteilen lässt. 6. Lachs auf einen Servierteller legen, heiß servieren und nach Wunsch mit zusätzlichen frischen Kräutern und Zitronenscheiben garnieren.', 1, '1 Portion mit ca. 475 kcal liegt nah am alten Wert (430 kcal) und ist für ein Lachs-Hauptgericht realistisch.', 474, 475, 36, 5, 33, 'Lachsfilet 175g=364; Zitrone 25g=7; Knoblauch 5g=7; Olivenöl 10g=90; Dill 2g=1; Thymian 2g=2; Rosmarin 2g=3; Summe=474 kcal'),
  (62, 'Hähnchenfilet in Teriyaki-Sauce mit Brokkoli', 'Hauptgerichte', 'Dieses Hähnchenfilet in Teriyaki-Sauce mit Brokkoli ist ideal für ein leichtes Mittag- oder Abendessen und besticht durch seinen süßlich-würzigen Geschmack und die knackige Konsistenz des Brokkolis.', '[{"name":"Hähnchenfilet","menge_anzeige":"125 g","gramm":125},{"name":"Brokkoli","menge_anzeige":"100 g","gramm":100},{"name":"Teriyaki-Sauce","menge_anzeige":"25 ml","gramm":25},{"name":"Sojasauce","menge_anzeige":"1/2 EL","gramm":7.5},{"name":"Honig","menge_anzeige":"1/4 EL","gramm":5},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Frischer Ingwer (gerieben)","menge_anzeige":"1/4 EL","gramm":2.5},{"name":"Olivenöl","menge_anzeige":"1/2 EL","gramm":5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Sesam (zum Garnieren)","menge_anzeige":"1/2 TL","gramm":2},{"name":"Frühlingszwiebel","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Hähnchenfilet in kleine Stücke schneiden, Brokkoli in Röschen teilen, Knoblauch fein hacken und Ingwer reiben. 2. Für die Sauce Teriyaki-Sauce, Sojasauce, Honig, gehackten Knoblauch und geriebenen Ingwer in einer kleinen Schüssel mischen. 3. 1/2 EL Olivenöl in einer Pfanne bei mittlerer Hitze erhitzen, das Hähnchenfilet hinzugeben und ca. 5–7 Minuten goldbraun braten. 4. Die vorbereitete Sauce zum Hähnchen geben, die Hitze reduzieren und weitere 5–7 Minuten köcheln lassen, bis die Sauce leicht eindickt und das Hähnchen gar ist. 5. In einem kleinen Topf leicht gesalzenes Wasser zum Kochen bringen, die Brokkoliröschen hinzugeben und ca. 3–4 Minuten kochen, bis der Brokkoli hellgrün und weich ist. Abgießen und in kaltem Wasser abschrecken. 6. Restliches Olivenöl in einer Pfanne bei mittlerer Hitze erhitzen, den Brokkoli hinzugeben und ca. 2–3 Minuten leicht anbraten, dann zum Hähnchen geben und vorsichtig vermischen. 7. Hähnchen mit Brokkoli auf einem Teller anrichten, mit Sesam und fein gehackten Frühlingszwiebeln garnieren.', 1, '1 Portion mit ca. 280 kcal liegt am nächsten am alten Wert (318 kcal) und ist für ein leichtes Hähnchengericht plausibel.', 279, 280, 34, 14, 8, 'Hähnchenfilet 125g=138; Brokkoli 100g=34; Teriyaki-Sauce 25g=22; Sojasauce 7,5g=4; Honig 5g=15; Knoblauch 5g=7; Ingwer 2,5g=2; Olivenöl 5g=45; Sesam 2g=11; Summe=279 kcal'),
  (63, 'Geschmortes Rindfleisch mit Gemüse', 'Hauptgerichte', 'Dieses geschmorte Rindfleisch mit Gemüse ist ideal für ein herzhaftes Mittag- oder Abendessen und besticht durch seine reichhaltigen Aromen und die zarte Konsistenz des Fleisches. Guten Appetit!', '[{"name":"Rindfleisch","menge_anzeige":"125 g","gramm":125},{"name":"Kartoffeln","menge_anzeige":"150 g","gramm":150},{"name":"Karotte","menge_anzeige":"50 g","gramm":50},{"name":"Zwiebel","menge_anzeige":"25 g","gramm":25},{"name":"Sellerie","menge_anzeige":"50 g","gramm":50},{"name":"Olivenöl","menge_anzeige":"1/2 EL","gramm":5},{"name":"Tomatenmark","menge_anzeige":"1/2 EL","gramm":7.5},{"name":"Wasser oder Brühe","menge_anzeige":"125 ml","gramm":125},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Lorbeerblatt","menge_anzeige":"1 Stück","gramm":null}]'::jsonb, '1. Rindfleisch in Würfel schneiden und in Olivenöl goldbraun anbraten. 2. Kartoffeln, Karotte, Zwiebel und Sellerie schneiden. 3. Das Gemüse zum Rindfleisch geben und ca. 5 Minuten mitbraten. 4. Tomatenmark, Wasser oder Brühe, Lorbeerblatt, Salz und Pfeffer hinzufügen. 5. Bei schwacher Hitze mit Deckel ca. 1,5–2 Stunden schmoren, bis das Fleisch weich ist.', 1, '1 Portion mit ca. 500 kcal liegt nah am alten Wert (472 kcal) und passt zu einem herzhaften Schmorgericht.', 499, 500, 30, 40, 23, 'Rindfleisch 125g=263; Kartoffeln 150g=131; Karotte 50g=21; Zwiebel 25g=8; Sellerie 50g=21; Olivenöl 5g=45; Tomatenmark 7,5g=6; Brühe 125ml=6; Summe=499 kcal'),
  (64, 'Vegetarische Lasagne mit Zucchini und Auberginen', 'Hauptgerichte', 'Diese vegetarische Lasagne mit Zucchini und Auberginen ist ideal für ein leichtes Mittag- oder Abendessen und besticht durch ihre frischen, aromatischen Zutaten und die cremige Textur.', '[{"name":"Lasagneblätter","menge_anzeige":"2 Stück","gramm":36},{"name":"Zucchini","menge_anzeige":"1/2 Stück","gramm":150},{"name":"Aubergine","menge_anzeige":"1/2 Stück","gramm":150},{"name":"Tomaten","menge_anzeige":"1 Stück","gramm":100},{"name":"Zwiebel","menge_anzeige":"1/4 Stück","gramm":25},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Tomatenmark","menge_anzeige":"1 EL","gramm":15},{"name":"Mozzarella","menge_anzeige":"50 g","gramm":50},{"name":"Parmesan","menge_anzeige":"10 g","gramm":10},{"name":"Basilikum","menge_anzeige":"ein paar Blätter, nach Geschmack","gramm":null},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Zucchini und Aubergine in dünne Scheiben schneiden. Tomate und Zwiebel würfeln. Knoblauch fein hacken. 2. Für die Sauce 1/2 EL Olivenöl in einer Pfanne erhitzen, gehackte Zwiebel und Knoblauch goldbraun andünsten. Gehackte Tomate und Tomatenmark hinzufügen und 5–7 Minuten köcheln lassen, bis sie weich sind. Nach Geschmack salzen und pfeffern. 3. Restliches Olivenöl in einer anderen Pfanne erhitzen, Zucchini und Aubergine auf beiden Seiten goldbraun anbraten, salzen und pfeffern. 4. Lasagneblätter nach Packungsanweisung vorkochen. Ein Lasagneblatt auf den Boden einer Auflaufform legen, gebratene Zucchini und Aubergine daraufschichten, etwas Tomatensauce darübergießen und mit der Hälfte des geriebenen Mozzarellas bestreuen. 5. Die Schichten (Lasagneblatt, Gemüse, Sauce, Mozzarella) wiederholen, mit einer Schicht Tomatensauce und dem restlichen Mozzarella abschließen und mit geriebenem Parmesan bestreuen. 6. Ofen auf 180 °C vorheizen und die Lasagne ca. 20–25 Minuten backen, bis der Käse geschmolzen und goldbraun ist. 7. Vor dem Servieren mit frischen Basilikumblättern garnieren.', 1, '1 Portion mit ca. 490 kcal liegt am nächsten am alten Wert (582 kcal) unter den geprüften Teilungen und ist für eine Lasagne als Hauptgericht plausibel.', 490, 490, 22, 45, 24, 'Lasagneblätter 36g=126; Zucchini 150g=26; Aubergine 150g=38; Tomate 100g=18; Zwiebel 25g=8; Knoblauch 5g=7; Olivenöl 10g=90; Tomatenmark 15g=12; Mozzarella 50g=127; Parmesan 10g=39; Summe=490 kcal'),
  (65, 'Gefüllte Paprika mit Reis und Bohnen', 'Hauptgerichte', 'Gefüllte Paprika mit Reis und Bohnen ist ein leckeres und sättigendes Gericht, das einfach zuzubereiten ist. Die Kombination aus frischem Gemüse, zartem Reis und herzhaften Bohnen macht dieses Rezept ideal für ein gesundes und nahrhaftes Mittag- oder Abendessen.', '[{"name":"Rote Paprika","menge_anzeige":"1 Stück","gramm":150},{"name":"Reis","menge_anzeige":"50 g","gramm":50},{"name":"Konservierte rote Bohnen","menge_anzeige":"60 g","gramm":60},{"name":"Zwiebel","menge_anzeige":"25 g","gramm":25},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Tomate","menge_anzeige":"75 g","gramm":75},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Tomatenmark","menge_anzeige":"1 EL","gramm":15},{"name":"Paprika (gemahlen)","menge_anzeige":"1/2 TL","gramm":1},{"name":"Kreuzkümmel","menge_anzeige":"1/4 TL","gramm":0.5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Petersilie","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Reis unter kaltem Wasser abspülen. 1/2 Tasse (120 ml) Wasser zum Kochen bringen, Reis hinzufügen und ca. 15 Minuten garen, bis er gar ist. Vom Herd nehmen und ruhen lassen. 2. Zwiebel und Knoblauch fein würfeln, Tomate würfeln. 3. Olivenöl in einer Pfanne erhitzen, Zwiebel und Knoblauch goldbraun andünsten. Gehackte Tomate und Tomatenmark hinzufügen und 5 Minuten köcheln lassen. 4. Bohnen, Paprikagewürz, Kreuzkümmel, Salz und Pfeffer hinzufügen. Gekochten Reis unterrühren und gründlich vermischen, weitere 2–3 Minuten köcheln lassen. 5. Den oberen Teil der Paprika abschneiden, Samen und Membranen entfernen. Paprika mit der vorbereiteten Füllung füllen. 6. Ofen auf 180 °C vorheizen, gefüllte Paprika in eine Auflaufform legen und ca. 25–30 Minuten backen, bis sie weich sind. 7. Heiß servieren und mit fein gehackter Petersilie oder Koriander bestreuen.', 1, '1 Portion mit ca. 420 kcal liegt am nächsten am alten Wert (456 kcal) und ist für gefüllte Paprika als Hauptgericht realistisch.', 422, 420, 11, 67, 12, 'Rote Paprika 150g=47; Reis 50g=175; Rote Bohnen 60g=66; Zwiebel 25g=8; Knoblauch 5g=7; Tomate 75g=14; Olivenöl 10g=90; Tomatenmark 15g=12; Paprikapulver 1g=3; Kreuzkümmel 0,5g=2; Summe=422 kcal'),
  (66, 'Putenfleisch in Sahnesauce mit Champignons', 'Hauptgerichte', 'Putenfleisch in Sahnesauce mit Champignons ist ein sättigendes und leckeres Gericht, das einfach zuzubereiten ist. Zartes Putenfleisch und aromatische Champignons, gekocht in einer reichhaltigen Sahnesauce, schaffen die perfekte Kombination von Aromen. Dieses Rezept eignet sich hervorragend für das Abendessen und liefert Ihrem Körper die notwendigen Proteine und Fette.', '[{"name":"Putenfilet","menge_anzeige":"150 g","gramm":150},{"name":"Champignons","menge_anzeige":"100 g","gramm":100},{"name":"Sahne (20% Fett)","menge_anzeige":"50 ml","gramm":50},{"name":"Zwiebel","menge_anzeige":"25 g","gramm":25},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Petersilie","menge_anzeige":"zum Garnieren","gramm":2}]'::jsonb, '1. Schneiden Sie das Putenfilet in kleine Stücke. 2. Schneiden Sie die Champignons in dünne Scheiben und hacken Sie Zwiebel und Knoblauch fein. 3. Erhitzen Sie das Olivenöl in einer Pfanne bei mittlerer Hitze. Geben Sie das Putenfleisch hinzu und braten Sie es ca. 5-7 Minuten goldbraun an. Nehmen Sie es aus der Pfanne und legen Sie es beiseite. 4. Geben Sie Zwiebel und Knoblauch in dieselbe Pfanne und braten Sie sie ca. 3 Minuten goldbraun an. Fügen Sie die Champignons hinzu und kochen Sie sie ca. 5-7 Minuten, bis sie weich sind. 5. Gießen Sie die Sahne hinzu, bringen Sie alles zum Kochen und reduzieren Sie die Hitze. 6. Geben Sie das Putenfleisch zurück in die Pfanne, mischen Sie alles und lassen Sie es bei schwacher Hitze 5-7 Minuten köcheln, bis es gar ist. Salzen und pfeffern Sie nach Geschmack. 7. Legen Sie das Putenfleisch in Sahnesauce mit Champignons auf einen Teller und garnieren Sie mit fein gehackter Petersilie. Guten Appetit!', 1, 'Die Zutatenmenge (150 g Putenfilet als Hauptzutat) und der Kaloriengehalt von rund 390 kcal entsprechen einer typischen Einzelportion für ein Hauptgericht.', 391, 390, 41, 7, 22, 'Putenfilet 150 g = 156 kcal; Champignons 100 g = 22 kcal; Sahne 20% 50 ml = 106 kcal; Zwiebel 25 g = 10 kcal; Knoblauch 5 g = 7,5 kcal; Olivenöl 10 g (1 EL) = 88,4 kcal; Salz/Pfeffer nach Geschmack = 0 kcal; Petersilie ca. 2 g = 1 kcal (vernachlässigbar); Summe = 391 kcal'),
  (67, 'Zucchini-Spaghetti', 'Hauptgerichte', 'Dieses Gericht ist ideal für ein leichtes Mittag- oder Abendessen und besticht durch seine frischen, aromatischen Zutaten und die einfache Zubereitung.', '[{"name":"Zucchini","menge_anzeige":"200 g","gramm":200},{"name":"Tomaten","menge_anzeige":"300 g","gramm":300},{"name":"Zwiebel","menge_anzeige":"25 g","gramm":25},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Tomatenmark","menge_anzeige":"1 EL","gramm":15},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Getrocknete italienische Kräuter","menge_anzeige":"1/2 TL","gramm":1},{"name":"Parmesan","menge_anzeige":"10 g","gramm":10}]'::jsonb, '1. Waschen Sie die Zucchini und schneiden Sie sie mit einem Gemüseschäler oder Spiralschneider in dünne, spaghettiartige Streifen. 2. Schneiden Sie die Tomaten in Würfel und hacken Sie Zwiebel und Knoblauch fein. 3. Erhitzen Sie das Olivenöl in einer Pfanne bei mittlerer Hitze. Geben Sie Zwiebel und Knoblauch hinzu und braten Sie sie ca. 3 Minuten goldbraun an. 4. Fügen Sie die gehackten Tomaten und das Tomatenmark hinzu und köcheln Sie alles 10 Minuten, bis es weich ist. Würzen Sie mit Salz, Pfeffer und den italienischen Kräutern und köcheln Sie weitere 5 Minuten, bis die Sauce eindickt. 5. Erhitzen Sie etwas Olivenöl in einer weiteren Pfanne. Braten Sie die Zucchini-Streifen bei mittlerer Hitze 2-3 Minuten unter gelegentlichem Rühren an, bis sie weich sind, aber ihre Form behalten. 6. Geben Sie die Zucchini-Spaghetti in die Pfanne mit der Tomatensauce und vermischen Sie alles gründlich. 7. Servieren Sie die Zucchini-Spaghetti mit Tomatensauce, garnieren Sie mit frischem Basilikum und bestreuen Sie nach Wunsch mit geriebenem Parmesan. Guten Appetit!', 1, 'Mit rund 246 kcal liegt das Gericht im Bereich einer leichten Einzelportion, wie sie im Kochbuch für Hauptgerichte üblich ist.', 246, 245, 10, 17, 14, 'Zucchini 200 g = 34 kcal; Tomaten 300 g = 54 kcal; Zwiebel 25 g = 10 kcal; Knoblauch 5 g = 7,5 kcal; Olivenöl 10 g (1 EL) = 88,4 kcal; Tomatenmark 15 g (1 EL) = 12,3 kcal; Salz/Pfeffer nach Geschmack = 0 kcal; getrocknete Kräuter ca. 1 g = 1 kcal (vernachlässigbar); Parmesan 10 g = 39,2 kcal; Summe = 246 kcal'),
  (68, 'Hähnchenbrust in Orangensauce', 'Hauptgerichte', 'Dieses Gericht ist ideal für ein leichtes und gesundes Abendessen und besticht durch seine frischen, aromatischen Zutaten und die einfache Zubereitung.', '[{"name":"Hähnchenbrust","menge_anzeige":"150 g","gramm":150},{"name":"Orange (für Saft und Schale)","menge_anzeige":"1/2 Stück","gramm":85},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Sojasauce","menge_anzeige":"1 EL","gramm":15},{"name":"Honig","menge_anzeige":"1 TL","gramm":7},{"name":"Frischer geriebener Ingwer","menge_anzeige":"1/2 TL","gramm":2},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Petersilie","menge_anzeige":"zum Garnieren","gramm":2}]'::jsonb, '1. Pressen Sie den Saft aus der halben Orange und reiben Sie die Schale ab (ca. 1/2 TL). 2. Hacken Sie den Knoblauch fein. Mischen Sie in einer Schüssel Orangensaft, Orangenschale, Knoblauch, Olivenöl, Sojasauce, Honig und geriebenen Ingwer. Salzen und pfeffern Sie nach Geschmack. 3. Legen Sie die Hähnchenbrust in die Marinade und wenden Sie sie gut. Lassen Sie sie mindestens 30 Minuten (für einen intensiveren Geschmack bis zu 2 Stunden) im Kühlschrank marinieren. 4. Erhitzen Sie den Grill oder eine Pfanne bei mittlerer Hitze. Nehmen Sie die Hähnchenbrust aus der Marinade und tupfen Sie sie leicht mit einem Papiertuch trocken. 5. Grillen oder braten Sie das Hähnchen 5-7 Minuten pro Seite, bis es vollständig durchgegart und goldbraun ist. Die Kerntemperatur sollte 75 °C erreichen. 6. Legen Sie die Hähnchenbrust auf einen Teller und garnieren Sie mit fein gehackter Petersilie. Servieren Sie nach Wunsch mit Gemüse, Salat oder Reis. Guten Appetit!', 1, '150 g Hähnchenbrust als Hauptzutat und ca. 334 kcal entsprechen einer klassischen Einzelportion.', 334, 335, 37, 16, 13, 'Hähnchenbrust 150 g = 165 kcal; Orange (1/2 Stück, ca. 85 g) = 40 kcal; Knoblauch 5 g = 7,5 kcal; Olivenöl 10 g (1 EL) = 88,4 kcal; Sojasauce 15 ml (1 EL) = 9 kcal; Honig 7 g (1 TL) = 21,3 kcal; Ingwer ca. 2 g = 2 kcal (vernachlässigbar); Salz/Pfeffer nach Geschmack = 0 kcal; Petersilie ca. 2 g = 1 kcal (vernachlässigbar); Summe = 334 kcal'),
  (69, 'Fischfrikadellen mit Gemüse', 'Hauptgerichte', 'Dieses Gericht ist ideal für ein leichtes Abend- oder Mittagessen und besticht durch seine frischen, aromatischen Zutaten und die einfache Zubereitung.', '[{"name":"Weißfischfilet","menge_anzeige":"150 g","gramm":150},{"name":"Karotte","menge_anzeige":"50 g","gramm":50},{"name":"Zwiebel","menge_anzeige":"25 g","gramm":25},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Ei","menge_anzeige":"1/2 Stück","gramm":27.5},{"name":"Paniermehl","menge_anzeige":"1 EL","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Olivenöl","menge_anzeige":"1 EL (zum Braten)","gramm":10},{"name":"Kräuter","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Zitrone","menge_anzeige":"zum Servieren","gramm":null}]'::jsonb, '1. Zerkleinern Sie das Fischfilet im Mixer oder Fleischwolf. 2. Reiben Sie die Karotte fein und hacken Sie Zwiebel, Knoblauch und die Kräuter fein. 3. Mischen Sie in einer Schüssel den zerkleinerten Fisch mit Karotte, Zwiebel, Knoblauch und Kräutern. Geben Sie Ei, Paniermehl, Salz und Pfeffer hinzu und vermischen Sie alles gründlich, bis eine homogene Masse entsteht. 4. Formen Sie aus der Masse Frikadellen. 5. Erhitzen Sie das Olivenöl in einer Pfanne bei mittlerer Hitze und braten Sie die Frikadellen auf beiden Seiten ca. 3-4 Minuten pro Seite goldbraun an. 6. Reduzieren Sie die Hitze, decken Sie die Pfanne ab und garen Sie die Frikadellen weitere 5-7 Minuten, bis sie vollständig durch sind. 7. Servieren Sie die Fischfrikadellen mit Zitronenspalten und frischem Gemüse oder Salat nach Wahl. Guten Appetit!', 1, '150 g Fischfilet als Basis und ca. 327 kcal deuten auf eine Einzelportion hin, konsistent mit den anderen Rezepten dieses Kochbuchs.', 327, 325, 33, 14, 14, 'Weißfischfilet 150 g = 123 kcal; Karotte 50 g = 17,5 kcal; Zwiebel 25 g = 10 kcal; Knoblauch 5 g = 7,5 kcal; Ei 1/2 Stück (ca. 27,5 g) = 41 kcal; Paniermehl 10 g (1 EL) = 39,5 kcal; Salz/Pfeffer nach Geschmack = 0 kcal; Olivenöl 10 g (1 EL) = 88,4 kcal; Kräuter nach Geschmack = 0 kcal; Zitrone zum Servieren = 0 kcal (Menge nicht spezifiziert); Summe = 327 kcal'),
  (70, 'Auflauf mit Brokkoli und Blumenkohl', 'Hauptgerichte', 'Dieser Auflauf mit Brokkoli und Blumenkohl ist ideal für ein gesundes Mittag- oder Abendessen und besticht durch seine frischen, aromatischen Zutaten und die einfache Zubereitung.', '[{"name":"Brokkoli","menge_anzeige":"100 g","gramm":100},{"name":"Blumenkohl","menge_anzeige":"100 g","gramm":100},{"name":"Ei","menge_anzeige":"3 Stück","gramm":165},{"name":"Käse (Cheddar oder Mozzarella)","menge_anzeige":"30 g","gramm":30},{"name":"Milch","menge_anzeige":"50 ml","gramm":50},{"name":"Olivenöl","menge_anzeige":"1/2 EL","gramm":5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Muskatnuss","menge_anzeige":"eine Prise (nach Wunsch)","gramm":0.2},{"name":"Kräuter","menge_anzeige":"zum Garnieren","gramm":2}]'::jsonb, '1. Teilen Sie Brokkoli und Blumenkohl in kleine Röschen. Blanchieren Sie sie ca. 3-4 Minuten in kochendem Salzwasser und schrecken Sie sie danach sofort in kaltem Wasser ab, um den Garvorgang zu stoppen. 2. Verquirlen Sie in einer Schüssel 1 Ei mit der Milch. Geben Sie den geriebenen Käse, Salz, Pfeffer und nach Wunsch etwas Muskatnuss hinzu und vermischen Sie alles gründlich. 3. Legen Sie Brokkoli und Blumenkohl in eine mit Olivenöl eingefettete Auflaufform. Gießen Sie die Ei-Milch-Käse-Mischung darüber und geben Sie die restlichen 2 Eier obenauf. 4. Heizen Sie den Ofen auf 180 °C vor. Backen Sie den Auflauf ca. 20-25 Minuten, bis er goldbraun und fest ist. 5. Legen Sie den fertigen Auflauf auf einen Teller und garnieren Sie mit fein gehackten Kräutern. Guten Appetit!', 1, '3 Eier plus Gemüse ergeben mit ca. 479 kcal eine vollwertige Einzelportion im typischen Hauptgericht-Bereich (300-650 kcal).', 479, 480, 35, 11, 32, 'Brokkoli 100 g = 34 kcal; Blumenkohl 100 g = 25 kcal; Ei 3 Stück (ca. 165 g) = 246 kcal; Käse 30 g = 105 kcal; Milch 50 ml = 23,5 kcal; Olivenöl 5 g (1/2 EL) = 44,2 kcal; Salz/Pfeffer nach Geschmack = 0 kcal; Muskatnuss eine Prise (ca. 0,2 g) = 0 kcal (vernachlässigbar); Kräuter zum Garnieren ca. 2 g = 1 kcal (vernachlässigbar); Summe = 479 kcal'),
  (71, 'Geschmorter Weißkohl', 'Hauptgerichte', 'Dieses geschmorte Weißkohlgericht ist ideal für ein leichtes Mittag- oder Abendessen und besticht durch seine Einfachheit und den reichen Geschmack.', '[{"name":"Weißkohl","menge_anzeige":"1 Stück (ca. 300 g)","gramm":300},{"name":"Karotte","menge_anzeige":"50 g","gramm":50},{"name":"Zwiebel","menge_anzeige":"60 g","gramm":60},{"name":"Tomatenmark","menge_anzeige":"1 EL","gramm":15},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Wasser oder Gemüsebrühe","menge_anzeige":"100 ml","gramm":100},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Lorbeerblatt","menge_anzeige":"1 Stück","gramm":0.2},{"name":"Kräuter (Dill oder Petersilie)","menge_anzeige":"nach Wunsch","gramm":2}]'::jsonb, '1. Schneiden Sie den Kohl in dünne Streifen, reiben Sie die Karotte grob und hacken Sie die Zwiebel fein. 2. Erhitzen Sie das Olivenöl in einer tiefen Pfanne oder einem Topf bei mittlerer Hitze. Geben Sie Zwiebel und Karotte hinzu und braten Sie sie ca. 5 Minuten weich und goldbraun an. 3. Geben Sie den Kohl hinzu, vermischen Sie alles und kochen Sie weitere 5 Minuten, bis der Kohl etwas an Volumen verliert. 4. Rühren Sie das Tomatenmark unter, gießen Sie Wasser oder Gemüsebrühe hinzu und geben Sie das Lorbeerblatt dazu. Salzen und pfeffern Sie nach Geschmack. 5. Reduzieren Sie die Hitze, decken Sie die Pfanne ab und schmoren Sie den Kohl ca. 20-30 Minuten unter gelegentlichem Rühren, bis er weich und saftig ist. 6. Legen Sie den geschmorten Kohl auf einen Teller und garnieren Sie mit fein gehackten Kräutern. Guten Appetit!', 1, 'Die berechneten ca. 223 kcal liegen nah am alten Wert (216 kcal) und passen zu einer Einzelportion als Beilage bzw. leichtes Hauptgericht.', 223, 225, 6, 23, 11, 'Weißkohl 1 Stück (ca. 300 g angenommen) = 75 kcal; Karotte 50 g = 17,5 kcal; Zwiebel 60 g = 24 kcal; Tomatenmark 15 g (1 EL) = 12,3 kcal; Olivenöl 10 g (1 EL) = 88,4 kcal; Gemüsebrühe 100 ml = 5 kcal; Salz/Pfeffer nach Geschmack = 0 kcal; Lorbeerblatt 1 Stück (ca. 0,2 g) = 0 kcal (vernachlässigbar); Kräuter nach Wunsch ca. 2 g = 1 kcal (vernachlässigbar); Summe = 223 kcal'),
  (72, 'Hähnchenschenkel in Honig-Senf-Sauce', 'Hauptgerichte', 'Hähnchenschenkel in Honig-Senf-Sauce ist ein Gericht, das die Zartheit des Hähnchenfleischs mit dem süß-würzigen Geschmack der Sauce kombiniert. Das schnelle Marinieren und Braten ermöglicht es Ihnen, dieses kulinarische Meisterwerk in wenigen Minuten zuzubereiten, was es zur idealen Wahl für ein Abendessen unter der Woche macht.', '[{"name":"Hähnchenschenkel","menge_anzeige":"150 g","gramm":150},{"name":"Honig","menge_anzeige":"1 EL","gramm":20},{"name":"Senf","menge_anzeige":"1 EL","gramm":15},{"name":"Sojasauce","menge_anzeige":"1 EL","gramm":15},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Mischen Sie in einer Schüssel Honig, Senf, Sojasauce, gehackten Knoblauch, Olivenöl, Salz und Pfeffer. 2. Marinieren Sie den Hähnchenschenkel für 30 Minuten in der vorbereiteten Mischung. 3. Erhitzen Sie eine Pfanne bei mittlerer Hitze und braten Sie den Hähnchenschenkel 5-7 Minuten pro Seite, bis er goldbraun und vollständig durchgegart ist. 4. Servieren Sie mit einer Beilage nach Wahl. Guten Appetit!', 1, '150 g Hähnchenschenkel als Hauptzutat und ca. 449 kcal entsprechen einer typischen Einzelportion.', 449, 450, 28, 20, 30, 'Hähnchenschenkel 150 g = 270 kcal; Honig 20 g (1 EL) = 60,8 kcal; Senf 15 g (1 EL) = 13,35 kcal; Sojasauce 15 ml (1 EL) = 9 kcal; Knoblauch 5 g = 7,5 kcal; Olivenöl 10 g (1 EL) = 88,4 kcal; Salz/Pfeffer nach Geschmack = 0 kcal; Summe = 449 kcal'),
  (73, 'Rindfleisch mit Pilzen in Sahnesauce', 'Hauptgerichte', 'Rindfleisch mit Pilzen in Sahnesauce ist ein klassisches Gericht, das zartes Rindfleisch und aromatische Pilze in einer reichhaltigen Sahnesauce kombiniert. Dieses Gericht ist nicht nur lecker, sondern auch sättigend und eignet sich ideal für besondere Anlässe oder gemütliche Abendessen zu Hause. Guten Appetit!', '[{"name":"Rindfleisch (Filet)","menge_anzeige":"150 g","gramm":150},{"name":"Champignons","menge_anzeige":"100 g","gramm":100},{"name":"Sahne (20%)","menge_anzeige":"50 ml","gramm":50},{"name":"Zwiebel","menge_anzeige":"1/4 Stück","gramm":25},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Petersilie","menge_anzeige":"zum Garnieren","gramm":2}]'::jsonb, '1. Schneiden Sie das Rindfleisch und die Pilze in dünne Scheiben. 2. Braten Sie die Zwiebel und den Knoblauch in Olivenöl goldbraun an. 3. Fügen Sie das Rindfleisch und die Pilze hinzu und braten Sie sie, bis sie gar sind. 4. Gießen Sie die Sahne hinzu, salzen und pfeffern Sie, und lassen Sie es 5-7 Minuten köcheln. 5. Servieren Sie und garnieren Sie mit Petersilie.', 1, '150 g Rindfleisch als Hauptzutat und die berechneten ca. 434 kcal entsprechen einer typischen Einzelportion für ein Hauptgericht in diesem Kochbuch, was auch zum alten kcal-Wert (400) passt.', 434, 435, 36, 7, 28, 'Rindfleisch (Filet) 150 g = 199,5 kcal; Champignons 100 g = 22 kcal; Sahne 50 g = 106 kcal; Zwiebel 25 g = 10 kcal; Knoblauch 5 g = 7,5 kcal; Olivenöl 10 g = 88,4 kcal; Petersilie 2 g = 1 kcal (vernachlässigbar); Salz/Pfeffer nach Geschmack = 0 kcal; Summe = 434,4 kcal ≈ 434 kcal'),
  (74, 'Lachs in Zitronen-Knoblauch-Sauce', 'Hauptgerichte', 'Lachs in Zitronen-Knoblauch-Sauce ist ein raffiniertes Gericht, das den zarten Geschmack des Fischs mit der Frische der Zitrone und der Schärfe des Knoblauchs unterstreicht. Die schnelle Zubereitung und der minimale Einsatz von Zutaten machen dieses Gericht ideal für ein leichtes und gesundes Abendessen. Guten Appetit!', '[{"name":"Lachsfilet","menge_anzeige":"150 g","gramm":150},{"name":"Zitrone","menge_anzeige":"1/2 Stück","gramm":50},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frischer Dill","menge_anzeige":"zum Garnieren","gramm":2}]'::jsonb, '1. Mischen Sie in einer Schüssel Zitronensaft, Zitronenschale, gehackten Knoblauch, Olivenöl, Salz und Pfeffer. 2. Marinieren Sie das Lachsfilet in der vorbereiteten Mischung für 15 Minuten. 3. Braten Sie den Lachs in einer Pfanne 3-4 Minuten auf jeder Seite goldbraun an. 4. Servieren Sie und garnieren Sie mit Dill.', 1, '150 g Lachsfilet als Hauptzutat und die berechneten ca. 423 kcal entsprechen einer typischen Einzelportion für ein Hauptgericht in diesem Kochbuch.', 423, 425, 31, 6, 30, 'Lachsfilet 150 g = 312 kcal; Zitrone 50 g = 14,5 kcal; Knoblauch 5 g = 7,5 kcal; Olivenöl 10 g = 88,4 kcal; Frischer Dill 2 g = 1 kcal (vernachlässigbar); Salz/Pfeffer nach Geschmack = 0 kcal; Summe = 423,4 kcal ≈ 423 kcal'),
  (75, 'Truthahnfrikadellen mit Haferflocken', 'Hauptgerichte', 'Truthahnfrikadellen mit Haferflocken sind eine gesunde und nahrhafte Wahl für Ihr Mittag- oder Abendessen. Die Kombination aus zartem Putenfleisch und gesunden Haferflocken sorgt für einen ausgezeichneten Geschmack und versorgt den Körper mit notwendigen Proteinen und Ballaststoffen. Guten Appetit!', '[{"name":"Putenfilet","menge_anzeige":"150 g","gramm":150},{"name":"Haferflocken","menge_anzeige":"2 EL (ca. 20 g)","gramm":20},{"name":"Ei","menge_anzeige":"1/2 Stück","gramm":28},{"name":"Zwiebel","menge_anzeige":"1/4 Stück","gramm":25},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10}]'::jsonb, '1. Zerkleinern Sie das Putenfilet, die Haferflocken, die Zwiebel und den Knoblauch im Mixer. 2. Fügen Sie das Ei, Salz und Pfeffer hinzu und mischen Sie gut. 3. Formen Sie Frikadellen und braten Sie sie in Olivenöl goldbraun an, ca. 3-4 Minuten pro Seite. 4. Servieren Sie mit einer Beilage nach Wahl.', 1, '150 g Putenfilet als Hauptzutat und die berechneten ca. 378 kcal entsprechen einer typischen Einzelportion für ein Hauptgericht in diesem Kochbuch.', 378, 380, 43, 15, 16, 'Putenfilet 150 g = 156 kcal; Haferflocken 20 g = 74,4 kcal; Ei 28 g = 41,7 kcal; Zwiebel 25 g = 10 kcal; Knoblauch 5 g = 7,5 kcal; Olivenöl 10 g = 88,4 kcal; Salz/Pfeffer nach Geschmack = 0 kcal; Summe = 378 kcal'),
  (76, 'Garnelen in Knoblauchbutter', 'Hauptgerichte', 'Garnelen in Knoblauchbutter sind ein einfaches und schnelles Gericht, das mit seinem intensiven Aroma und Geschmack begeistert. Dieses Gericht eignet sich hervorragend als leichtes Abendessen oder Vorspeise und wird Liebhaber von Meeresfrüchten erfreuen.', '[{"name":"Garnelen (geschält)","menge_anzeige":"150 g","gramm":150},{"name":"Knoblauch","menge_anzeige":"2 Zehen","gramm":10},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Butter","menge_anzeige":"1 EL","gramm":15},{"name":"Petersilie","menge_anzeige":"zum Garnieren","gramm":2},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Hacken Sie den Knoblauch fein. Erhitzen Sie Butter und Olivenöl in einer Pfanne und dünsten Sie den Knoblauch kurz darin an, bis er duftet. 2. Geben Sie die Garnelen dazu und würzen Sie mit Salz und Pfeffer. 3. Braten Sie die Garnelen ca. 2-3 Minuten pro Seite in der Knoblauchbutter, bis sie rosa und gar sind (nicht zu lange braten, sonst werden sie gummiartig). 4. Servieren Sie und garnieren Sie mit Petersilie.', 1, '150 g Garnelen als Hauptzutat und die berechneten ca. 318 kcal entsprechen einer typischen Einzelportion für ein leichtes Hauptgericht in diesem Kochbuch.', 318, 320, 21, 4, 24, 'Garnelen (geschält) 150 g = 106,5 kcal; Knoblauch 10 g = 15 kcal; Olivenöl 10 g = 88,4 kcal; Butter 15 g = 107,6 kcal; Petersilie 2 g = 1 kcal (vernachlässigbar); Salz/Pfeffer nach Geschmack = 0 kcal; Summe = 318,5 kcal ≈ 318 kcal'),
  (77, 'Hähnchenfrikadellen mit Zucchini', 'Hauptgerichte', 'Hähnchenfrikadellen mit Zucchini sind ein zartes und saftiges Gericht, das sich hervorragend für ein leichtes und gesundes Abendessen eignet. Die Kombination aus Hähnchenfilet und frischer Zucchini verleiht den Frikadellen eine weiche und saftige Konsistenz und macht sie lecker und gesund. Guten Appetit!', '[{"name":"Hähnchenfilet","menge_anzeige":"150 g","gramm":150},{"name":"Zucchini","menge_anzeige":"1/2 Stück (ca. 100 g)","gramm":100},{"name":"Ei","menge_anzeige":"1/2 Stück","gramm":28},{"name":"Zwiebel","menge_anzeige":"1/4 Stück","gramm":25},{"name":"Haferflocken","menge_anzeige":"1 EL (ca. 10 g)","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Kräuter (Dill oder Petersilie)","menge_anzeige":"nach Geschmack","gramm":2}]'::jsonb, '1. Zerkleinern Sie das Hähnchenfilet im Mixer oder Fleischwolf. 2. Reiben Sie die Zucchini fein und drücken Sie überschüssige Flüssigkeit aus. 3. Hacken Sie die Zwiebel und die Kräuter fein. 4. Mischen Sie das Hähnchenfilet, die Zucchini, das Ei, die Haferflocken, die Zwiebel, die Kräuter, Salz und Pfeffer. 5. Formen Sie Frikadellen und braten Sie sie in Olivenöl goldbraun an, ca. 3-4 Minuten pro Seite. 6. Servieren Sie mit Gemüse oder Salat.', 1, '150 g Hähnchenfilet als Hauptzutat und die berechneten ca. 360 kcal entsprechen einer typischen Einzelportion für ein Hauptgericht in diesem Kochbuch.', 360, 360, 41, 10, 17, 'Hähnchenfilet 150 g = 165 kcal; Zucchini 100 g = 17 kcal; Ei 28 g = 41,7 kcal; Zwiebel 25 g = 10 kcal; Haferflocken 10 g = 37,2 kcal; Olivenöl 10 g = 88,4 kcal; Kräuter 2 g = 1 kcal (vernachlässigbar); Salz/Pfeffer nach Geschmack = 0 kcal; Summe = 360,3 kcal ≈ 360 kcal'),
  (78, 'Thunfischsteak mit Zitrone und Knoblauch', 'Hauptgerichte', 'Thunfischsteak mit Zitrone und Knoblauch ist ein raffiniertes und nahrhaftes Gericht, das einfach zuzubereiten ist. Zarter Thunfisch, durchzogen mit dem Aroma von Zitrone und Knoblauch, wird Ihren Tisch schmücken. Dieses Rezept eignet sich hervorragend für diejenigen, die den Geschmack und die Vorteile von Meeresfrüchten schätzen.', '[{"name":"Thunfischsteak","menge_anzeige":"150 g","gramm":150},{"name":"Zitrone","menge_anzeige":"1/2 Stück","gramm":50},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Petersilie","menge_anzeige":"zum Garnieren","gramm":2}]'::jsonb, '1. Mischen Sie Zitronensaft, Zitronenschale, gehackten Knoblauch, Olivenöl, Salz und Pfeffer. 2. Marinieren Sie das Thunfischsteak in dieser Mischung für 15 Minuten. 3. Braten Sie den Thunfisch auf dem Grill oder in der Pfanne für 2-3 Minuten auf jeder Seite bis zur gewünschten Garstufe. 4. Servieren Sie und garnieren Sie mit Petersilie und Zitronenspalten.', 1, '150 g Thunfischsteak als Hauptzutat und die berechneten ca. 327 kcal entsprechen einer typischen Einzelportion für ein Hauptgericht in diesem Kochbuch.', 327, 325, 35, 6, 18, 'Thunfischsteak 150 g = 216 kcal; Zitrone 50 g = 14,5 kcal; Knoblauch 5 g = 7,5 kcal; Olivenöl 10 g = 88,4 kcal; Petersilie 2 g = 1 kcal (vernachlässigbar); Salz/Pfeffer nach Geschmack = 0 kcal; Summe = 327,4 kcal ≈ 327 kcal'),
  (79, 'Gebackenes Schweinefilet mit Äpfeln und Zwiebeln', 'Hauptgerichte', 'Gebackenes Schweinefilet mit Äpfeln und Zwiebeln ist ein köstliches Gericht mit einer harmonischen Mischung aus süßen und salzigen Aromen. Saftiges Schweinefleisch, gebacken mit Äpfeln und Zwiebeln, eignet sich perfekt für ein gemütliches Familienessen.', '[{"name":"Schweinefilet","menge_anzeige":"150 g","gramm":150},{"name":"Apfel","menge_anzeige":"75 g","gramm":75},{"name":"Zwiebel","menge_anzeige":"25 g","gramm":25},{"name":"Honig","menge_anzeige":"1 TL","gramm":7},{"name":"Senf","menge_anzeige":"1 TL","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Rosmarin","menge_anzeige":"nach Wunsch","gramm":null}]'::jsonb, '1. Honig, Senf, Olivenöl, Salz und Pfeffer mischen. 2. Schweinefilet 30 Minuten in dieser Mischung marinieren. 3. Apfel und Zwiebel in dünne Scheiben schneiden. 4. Schweinefilet in eine Auflaufform legen und mit den Apfel- und Zwiebelscheiben belegen. 5. Im vorgeheizten Ofen bei 180°C ca. 25–30 Minuten backen, bis das Fleisch gar ist. 6. Servieren und mit Rosmarin garnieren.', 1, '150 g Schweinefilet entsprechen einer üblichen Einzelportion Hauptgericht.', 323, 325, 33, 17, 13, 'Schweinefilet 150 g = 159 kcal; Apfel 75 g = 39 kcal; Zwiebel 25 g = 10 kcal; Honig 7 g = 21 kcal; Senf 5 g = 4 kcal; Olivenöl 10 g = 90 kcal; Summe = 323 kcal'),
  (80, 'Lasagne mit Huhn und Spinat', 'Hauptgerichte', 'Herzhafte Lasagne mit Hühnerfilet, Spinat und Ricotta (oder Hüttenkäse), geschichtet mit Tomatensauce und Käse und im Ofen gebacken.', '[{"name":"Lasagneblätter","menge_anzeige":"2 Stück","gramm":40},{"name":"Hühnerfilet","menge_anzeige":"100 g","gramm":100},{"name":"Spinat","menge_anzeige":"50 g","gramm":50},{"name":"Ricotta oder Hüttenkäse","menge_anzeige":"50 g","gramm":50},{"name":"Tomatensauce","menge_anzeige":"50 ml","gramm":50},{"name":"Käse","menge_anzeige":"30 g","gramm":30},{"name":"Zwiebel","menge_anzeige":"1/4 Stück","gramm":25},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Lasagneblätter bis zur Halbgarheit kochen. 2. Hühnerfilet in kleine Würfel schneiden und mit Zwiebel und Knoblauch anbraten, bis es gar ist. 3. Spinat zum Huhn geben und mitkochen, bis er weich ist. 4. Ricotta oder Hüttenkäse mit Huhn und Spinat mischen, salzen und pfeffern. 5. Eine Schicht Lasagneblätter in eine Auflaufform legen, darüber die Huhn-Spinat-Mischung, dann Tomatensauce und Käse verteilen; Schichten wiederholen. 6. Im vorgeheizten Ofen bei 180°C ca. 20–25 Minuten backen, bis die Oberfläche goldbraun ist. 7. Heiß servieren. Guten Appetit!', 1, '100 g Hühnerfilet und 2 Lasagneblätter sind für eine Einzelportion ausgelegt; 578 kcal liegen im Hauptgericht-Bereich.', 578, 580, 43, 38, 27, 'Lasagneblätter 40 g = 140 kcal; Hühnerfilet 100 g = 110 kcal; Spinat 50 g = 12 kcal; Ricotta/Hüttenkäse 50 g = 87 kcal; Tomatensauce 50 ml = 15 kcal; Käse 30 g = 107 kcal; Zwiebel 25 g = 10 kcal; Knoblauch 5 g = 7 kcal; Olivenöl 10 g = 90 kcal; Summe = 578 kcal'),
  (81, 'Gebackene Kartoffeln mit Rosmarin', 'Beilagen', 'Gebackene Kartoffeln mit Rosmarin sind ein einfaches, aromatisches Gericht. Knusprige Kruste und zarter Geschmack machen sie zur perfekten Beilage oder Mahlzeit. Guten Appetit!', '[{"name":"Kartoffel","menge_anzeige":"200 g","gramm":200},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Rosmarin","menge_anzeige":"1 TL","gramm":1},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Paprika (Gewürz)","menge_anzeige":"1/2 TL (optional)","gramm":1}]'::jsonb, '1. Kartoffel waschen und in Spalten oder Scheiben schneiden, Knoblauch hacken. 2. In einer Schüssel die Kartoffeln mit Olivenöl, Rosmarin, Knoblauch, Salz, Pfeffer und Paprika (falls verwendet) mischen. 3. Ofen auf 200°C vorheizen, Kartoffeln in einer Schicht auf ein mit Backpapier ausgelegtes Blech legen. 4. Ca. 25–30 Minuten backen, dabei zur Halbzeit wenden, bis sie goldbraun und weich sind. 5. Heiß servieren und nach Wunsch mit frischen Kräutern garnieren.', 1, '200 g Kartoffeln sind eine übliche Einzelportion als Beilage; 241 kcal liegen im Beilagen-Bereich und nahe am alten Wert.', 241, 240, 4, 32, 10, 'Kartoffel 200 g = 140 kcal; Olivenöl 10 g = 90 kcal; Rosmarin 1 g = 1 kcal; Knoblauch 5 g = 7 kcal; Paprika (Gewürz) 1 g = 3 kcal; Summe = 241 kcal'),
  (82, 'Gebackenes Gemüse mit Kräutern', 'Beilagen', 'Gebackenes Gemüse mit Kräutern ist eine aromatische und leckere Beilage zu Fleisch- und Fischgerichten. Die provenzalischen Kräuter verleihen dem Gemüse ein unverwechselbares Aroma, und das Backen bewahrt seine Nährstoffe und den Geschmack.', '[{"name":"Zucchini","menge_anzeige":"200 g","gramm":200},{"name":"Aubergine","menge_anzeige":"200 g","gramm":200},{"name":"Rote Paprika","menge_anzeige":"100 g","gramm":100},{"name":"Kirschtomaten","menge_anzeige":"100 g","gramm":100},{"name":"Olivenöl","menge_anzeige":"30 ml","gramm":30},{"name":"Provenzalische Kräuter","menge_anzeige":"1 TL","gramm":1},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Ofen auf 200°C vorheizen. 2. Zucchini, Aubergine und rote Paprika in grobe Stücke schneiden; Kirschtomaten ganz lassen oder halbieren. 3. Gemüse mit Olivenöl, Kräutern, Salz und Pfeffer mischen. 4. Gemüse auf ein Backblech legen und 25–30 Minuten backen, bis es goldbraun ist. 5. Heiß servieren.', 2, '600 g Gemüse plus 30 ml Olivenöl ergeben eine größere Menge; aufgeteilt auf 2 Portionen liegt der Wert (≈200 kcal) im Beilagen-Bereich und nahe am ursprünglich angegebenen Wert.', 404, 200, 3, 11, 16, 'Zucchini 200 g = 34 kcal; Aubergine 200 g = 48 kcal; Rote Paprika 100 g = 31 kcal; Kirschtomaten 100 g = 18 kcal; Olivenöl 30 g = 270 kcal; Provenzalische Kräuter 1 g = 3 kcal; Summe = 404 kcal (÷2 Portionen = 202 kcal)'),
  (83, 'Bulgur mit Pinienkernen und Rosinen', 'Beilagen', 'Bulgur mit Pinienkernen und Rosinen ist eine schmackhafte orientalische Beilage. Pinienkerne geben einen milden Nussgeschmack, Rosinen fügen Süße hinzu, und Minze sorgt für Frische und besonderes Aroma.', '[{"name":"Bulgur","menge_anzeige":"100 g","gramm":100},{"name":"Pinienkerne","menge_anzeige":"20 g","gramm":20},{"name":"Rosinen","menge_anzeige":"20 g","gramm":20},{"name":"Olivenöl","menge_anzeige":"1 EL (15 ml)","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Minze","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Bulgur in gesalzenem Wasser kochen, bis er gar ist. 2. Pinienkerne in einer Pfanne leicht anrösten, bis sie goldbraun sind. 3. Gekochten Bulgur mit Rosinen und Pinienkernen mischen. 4. Olivenöl, Salz, Pfeffer und fein gehackte Minze hinzufügen und gut mischen. 5. Heiß servieren.', 2, '100 g trockener Bulgur mit Nüssen und Rosinen ergibt gekocht eine für 2 Portionen als Beilage ausreichende Menge; 313 kcal pro Portion passen in den Beilagen-Bereich.', 626, 315, 8, 42, 13, 'Bulgur 100 g = 342 kcal; Pinienkerne 20 g = 135 kcal; Rosinen 20 g = 60 kcal; Olivenöl 10 g = 90 kcal; Summe = 626 kcal (÷2 Portionen = 313 kcal)'),
  (84, 'Hähnchenspieße mit Gemüse', 'Beilagen', 'Hähnchenspieße mit Gemüse sind ein leckeres und nahrhaftes Gericht, ideal für Grill oder Grillpfanne. Saftiges Hähnchen und frisches Gemüse in aromatischer Marinade bieten einen unverwechselbaren Geschmack. Guten Appetit!', '[{"name":"Hähnchenbrust","menge_anzeige":"150 g","gramm":150},{"name":"Paprika (Gemüse)","menge_anzeige":"50 g","gramm":50},{"name":"Zucchini","menge_anzeige":"100 g","gramm":100},{"name":"Rote Zwiebel","menge_anzeige":"25 g","gramm":25},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Zitronensaft","menge_anzeige":"1 EL","gramm":15},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Paprika (Gewürz)","menge_anzeige":"1/2 TL","gramm":1},{"name":"Getrockneter Thymian","menge_anzeige":"1/2 TL","gramm":0.5}]'::jsonb, '1. Marinade vorbereiten: Olivenöl, Zitronensaft, gehackten Knoblauch, Salz, Pfeffer, Paprika und getrockneten Thymian in einer Schüssel mischen. 2. Hähnchen marinieren: Hähnchenbrust in Würfel schneiden und 30 Minuten in der Marinade ziehen lassen. 3. Gemüse vorbereiten: Paprika, Zucchini und rote Zwiebel in Würfel schneiden. 4. Spieße zusammenstellen: Abwechselnd Hähnchen- und Gemüsestücke auf Spieße stecken. 5. Spieße grillen: Grill oder Grillpfanne erhitzen, Spieße je 3–4 Minuten pro Seite grillen, bis das Hähnchen durchgegart und das Gemüse goldbraun ist. 6. Servieren: Hähnchenspieße mit Lieblingssauce oder Beilage servieren.', 1, '150 g Hähnchenbrust entsprechen einer Einzelportion; 312 kcal liegen nahe am alten Wert.', 312, 310, 37, 12, 12, 'Hähnchenbrust 150 g = 165 kcal; Paprika (Gemüse) 50 g = 16 kcal; Zucchini 100 g = 17 kcal; Rote Zwiebel 25 g = 10 kcal; Olivenöl 10 g = 90 kcal; Zitronensaft 15 g = 3 kcal; Knoblauch 5 g = 7 kcal; Paprika (Gewürz) 1 g = 3 kcal; Thymian 0,5 g = 1 kcal; Summe = 312 kcal'),
  (85, 'Spaghetti mit Pesto-Sauce', 'Beilagen', 'Spaghetti mit Pesto-Sauce sind ein klassisches italienisches Gericht, das Einfachheit und Raffinesse vereint. Frischer Basilikum, Parmesan und Pinienkerne geben der Pesto-Sauce einen unverwechselbaren Geschmack. Ideal für ein schnelles, leckeres Abendessen.', '[{"name":"Spaghetti","menge_anzeige":"75 g","gramm":75},{"name":"Frischer Basilikum","menge_anzeige":"30 g","gramm":30},{"name":"Parmesan","menge_anzeige":"10 g","gramm":10},{"name":"Pinienkerne","menge_anzeige":"10 g","gramm":10},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"2 EL","gramm":20},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Zitronensaft","menge_anzeige":"1/2 TL (optional)","gramm":2.5}]'::jsonb, '1. Pesto-Sauce zubereiten: Basilikum, geriebenen Parmesan, Pinienkerne, gehackten Knoblauch, Olivenöl, Salz und Pfeffer im Mixer oder Mörser zu einer glatten Masse verarbeiten; Zitronensaft nach Wunsch hinzufügen. 2. Spaghetti kochen: In gesalzenem Wasser nach Packungsanweisung al dente kochen, Wasser abgießen und etwas Nudelwasser aufbewahren. 3. Spaghetti mit Pesto mischen und bei Bedarf etwas Nudelwasser hinzufügen, damit sich die Sauce besser verteilt. 4. Servieren: Auf einen Teller geben, nach Wunsch mit geriebenem Parmesan und Basilikumblättern garnieren.', 1, '75 g Spaghetti sind eine übliche Einzelportion; 567 kcal liegen nahe am alten Wert und im Hauptgericht-Bereich.', 567, 565, 16, 57, 31, 'Spaghetti 75 g = 265 kcal; Basilikum 30 g = 7 kcal; Parmesan 10 g = 40 kcal; Pinienkerne 10 g = 67 kcal; Knoblauch 5 g = 7 kcal; Olivenöl 20 g = 180 kcal; Zitronensaft 2,5 g = 1 kcal; Summe = 567 kcal'),
  (86, 'Quinoa mit Gemüse', 'Beilagen', 'Quinoa mit Gemüse ist ein leckeres und gesundes Gericht, das einfach zuzubereiten ist. Proteinreiche Quinoa und frisches Gemüse bieten eine ideale Kombination aus Geschmack und Textur, perfekt für ein gesundes Mittag- oder Abendessen. Guten Appetit!', '[{"name":"Quinoa","menge_anzeige":"45 g","gramm":45},{"name":"Wasser","menge_anzeige":"120 ml","gramm":120},{"name":"Rote Paprika","menge_anzeige":"50 g","gramm":50},{"name":"Zucchini","menge_anzeige":"100 g","gramm":100},{"name":"Karotte","menge_anzeige":"50 g","gramm":50},{"name":"Rote Zwiebel","menge_anzeige":"1/4 Stück","gramm":25},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Paprika (Gewürz)","menge_anzeige":"1/2 TL","gramm":1},{"name":"Frische Petersilie","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Quinoa kochen: Unter kaltem Wasser abspülen, mit Wasser aufsetzen und bei mittlerer Hitze ca. 15 Minuten kochen, bis sie gar ist; kurz stehen und abkühlen lassen. 2. Gemüse vorbereiten: Paprika, Zucchini, Karotte und rote Zwiebel in kleine Würfel schneiden, Knoblauch hacken. 3. Gemüse anbraten: Olivenöl erhitzen, Knoblauch ca. 1 Minute anbraten, bis er duftet; Gemüse hinzufügen und 5–7 Minuten anbraten, bis es weich ist; mit Salz, Pfeffer und Paprika würzen. 4. Quinoa mit dem Gemüse mischen und abschmecken. 5. Servieren: Auf einen Teller geben, vor dem Servieren mit frischer Petersilie garnieren.', 1, '45 g trockene Quinoa und die Gemüsemenge entsprechen einer üblichen Einzelportion als Beilage; 330 kcal liegen im Beilagen-Bereich.', 329, 330, 9, 44, 13, 'Quinoa 45 g = 166 kcal; Rote Paprika 50 g = 16 kcal; Zucchini 100 g = 17 kcal; Karotte 50 g = 21 kcal; Rote Zwiebel 25 g = 10 kcal; Olivenöl 10 g = 90 kcal; Knoblauch 5 g = 7 kcal; Paprika (Gewürz) 1 g = 3 kcal; Summe = 330 kcal (Wasser und Petersilie ohne nennenswerten Kalorienbeitrag)'),
  (87, 'Reis mit Erbsen und Mais', 'Beilagen', 'Reis mit Erbsen und Mais ist ein einfaches und schmackhaftes Gericht, das leicht zuzubereiten ist. Die Kombination aus weichem Reis und süßem Gemüse bietet einen harmonischen Geschmack, ideal für Mittag- oder Abendessen. Guten Appetit!', '[{"name":"Reis","menge_anzeige":"50 g","gramm":50},{"name":"Wasser","menge_anzeige":"120 ml","gramm":120},{"name":"Grüne Erbsen","menge_anzeige":"40 g (gefroren oder frisch)","gramm":40},{"name":"Mais","menge_anzeige":"40 g (gefroren oder aus der Dose)","gramm":40},{"name":"Zwiebel","menge_anzeige":"25 g","gramm":25},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Petersilie oder Dill","menge_anzeige":"optional","gramm":null}]'::jsonb, '1. Reis kochen: Unter kaltem Wasser abspülen, mit Wasser aufsetzen und bei mittlerer Hitze ca. 15 Minuten kochen, bis er gar ist; kurz stehen und abkühlen lassen. 2. Gemüse vorbereiten: Zwiebel fein hacken, Knoblauch hacken. 3. Gemüse anbraten: Olivenöl erhitzen, Zwiebel und Knoblauch ca. 3 Minuten goldbraun anbraten; Erbsen und Mais hinzufügen und ca. 5 Minuten mitkochen, bis sie weich sind; mit Salz und Pfeffer abschmecken. 4. Reis mit dem Gemüse mischen. 5. Servieren: Auf einen Teller geben, vor dem Servieren mit frischer Petersilie oder Dill garnieren.', 1, '50 g Reis mit je 40 g Erbsen und Mais entsprechen einer Einzelportion; 353 kcal liegen nahe am alten Wert.', 353, 355, 8, 56, 11, 'Reis 50 g = 175 kcal; Grüne Erbsen 40 g = 32 kcal; Mais 40 g = 38 kcal; Zwiebel 25 g = 10 kcal; Olivenöl 10 g = 90 kcal; Knoblauch 5 g = 7 kcal; Summe = 353 kcal'),
  (88, 'Blumenkohlpüree', 'Beilagen', 'Blumenkohlpüree ist ein leichtes und gesundes Gericht, das einfach zuzubereiten ist. Zartes, luftiges Püree mit Milch und Butter ist eine hervorragende Beilage oder ein eigenständiger Genuss. Guten Appetit!', '[{"name":"Blumenkohl","menge_anzeige":"200 g","gramm":200},{"name":"Milch (1,5 % Fett)","menge_anzeige":"60 ml","gramm":60},{"name":"Butter","menge_anzeige":"1 TL","gramm":5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Muskatnuss","menge_anzeige":"eine Prise","gramm":0.3},{"name":"Kräuter (Dill oder Petersilie)","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Blumenkohl vorbereiten: In kleine Röschen teilen und gründlich waschen. 2. Blumenkohl kochen: In gesalzenem Wasser 10–15 Minuten kochen, bis er weich ist; abtropfen lassen. 3. Püree zubereiten: Blumenkohl pürieren, bis eine glatte Masse entsteht; Milch, Butter, Salz und Pfeffer hinzufügen und gut mischen; nach Wunsch eine Prise Muskatnuss hinzufügen. 4. Servieren: Auf einen Teller geben, vor dem Servieren mit frischen Kräutern garnieren.', 1, '200 g Blumenkohl als Püree ergeben eine übliche Einzelportion; 116 kcal liegen fast exakt beim alten Wert und im Beilagen-Bereich.', 116, 115, 6, 9, 5, 'Blumenkohl 200 g = 50 kcal; Milch (1,5 %) 60 ml = 28 kcal; Butter 5 g = 36 kcal; Muskatnuss 1 Prise = 2 kcal; Summe = 116 kcal'),
  (89, 'Buchweizen mit Pilzen', 'Beilagen', 'Buchweizen mit Pilzen ist ein sättigendes und aromatisches Gericht, das einfach zuzubereiten ist. Proteinreicher Buchweizen und zarte Pilze bieten ein ideales Zusammenspiel von Geschmack und Textur. Perfekt für Mittag- oder Abendessen, versorgt es den Körper mit wichtigen Nährstoffen. Guten Appetit!', '[{"name":"Buchweizen","menge_anzeige":"50 g","gramm":50},{"name":"Wasser","menge_anzeige":"120 ml","gramm":120},{"name":"Champignons oder andere Pilze","menge_anzeige":"100 g","gramm":100},{"name":"Zwiebel","menge_anzeige":"25 g","gramm":25},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Kräuter (Dill oder Petersilie)","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Buchweizen kochen: Unter kaltem Wasser abspülen, mit Wasser und etwas Salz aufsetzen und kochen, bis das Wasser vollständig aufgenommen ist; vom Herd nehmen und zugedeckt ruhen lassen. 2. Gemüse und Pilze vorbereiten: Pilze in Scheiben schneiden, Zwiebel und Knoblauch fein hacken. 3. Pilze und Gemüse anbraten: Olivenöl erhitzen, Zwiebel und Knoblauch ca. 3 Minuten goldbraun anbraten; Pilze hinzufügen und 5–7 Minuten braten, bis sie weich und goldbraun sind; mit Salz und Pfeffer abschmecken. 4. Buchweizen mit den Pilzen mischen und 2–3 Minuten bei schwacher Hitze erwärmen, damit sich die Aromen verbinden. 5. Servieren: Auf einen Teller geben, vor dem Servieren mit frischen Kräutern garnieren.', 1, '50 g trockener Buchweizen mit 100 g Pilzen entspricht einer üblichen Einzelportion als Beilage; 300 kcal liegen im Beilagen-Bereich, etwas unter dem alten Wert.', 301, 300, 10, 43, 12, 'Buchweizen 50 g = 172 kcal; Champignons 100 g = 22 kcal; Zwiebel 25 g = 10 kcal; Knoblauch 5 g = 7 kcal; Olivenöl 10 g = 90 kcal; Summe = 301 kcal'),
  (90, 'Geschmorte Zucchini mit Knoblauch und Kräutern', 'Beilagen', 'Geschmorte Zucchini mit Knoblauch und Kräutern sind ein leichtes und gesundes Gericht, das einfach zuzubereiten ist. Zarte Zucchini, aromatischer Knoblauch und frische Kräuter machen es perfekt für ein leichtes Mittag- oder Abendessen. Guten Appetit!', '[{"name":"Zucchini","menge_anzeige":"200 g","gramm":200},{"name":"Knoblauch","menge_anzeige":"2 Zehen","gramm":10},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Kräuter (Dill, Petersilie)","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Zucchini vorbereiten: Waschen und in Scheiben oder Halbscheiben schneiden, wenn sie groß sind. 2. Knoblauch schälen und fein hacken. 3. Knoblauch anbraten: Olivenöl in einer tiefen Pfanne erhitzen, Knoblauch ca. 1 Minute goldbraun anbraten, dabei ständig rühren, damit er nicht anbrennt. 4. Zucchini hinzufügen, mit Salz und Pfeffer würzen und bei mittlerer Hitze 10–15 Minuten schmoren, gelegentlich umrühren, bis sie weich und leicht goldbraun ist. 5. Servieren: Auf einen Teller geben, vor dem Servieren mit frischen Kräutern garnieren.', 1, '200 g Zucchini als geschmorte Beilage entsprechen einer Einzelportion; 139 kcal liegen leicht unter dem alten Wert, sind aber für eine leichte Gemüsebeilage plausibel.', 139, 140, 3, 10, 11, 'Zucchini 200 g = 34 kcal; Knoblauch 10 g = 15 kcal; Olivenöl 10 g = 90 kcal; Summe = 139 kcal'),
  (91, 'Ratatouille mit Auberginen und Tomaten', 'Beilagen', 'Ratatouille mit Auberginen und Tomaten ist ein farbenfrohes und aromatisches Gericht, ideal für ein leichtes Mittag- oder Abendessen. Frisches Gemüse, gebacken mit provenzalischen Kräutern und Knoblauch, bietet eine unglaublich schmackhafte und gesunde Kombination. Guten Appetit!', '[{"name":"Aubergine","menge_anzeige":"200 g","gramm":200},{"name":"Tomaten","menge_anzeige":"200 g","gramm":200},{"name":"Zucchini","menge_anzeige":"200 g","gramm":200},{"name":"Paprika","menge_anzeige":"100 g","gramm":100},{"name":"Zwiebel","menge_anzeige":"100 g","gramm":100},{"name":"Knoblauch","menge_anzeige":"2 Zehen","gramm":10},{"name":"Olivenöl","menge_anzeige":"30 ml","gramm":30},{"name":"Provenzalische Kräuter","menge_anzeige":"1 TL","gramm":1},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Kräuter (Basilikum, Petersilie)","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Ofen auf 180°C vorheizen. 2. Aubergine, Tomaten, Zucchini und Paprika in dünne Scheiben schneiden; Zwiebel in Halbringe schneiden, Knoblauch hacken. 3. Geschnittenes Gemüse abwechselnd in eine Auflaufform schichten, mit Zwiebeln und Knoblauch bestreuen. 4. Mit Olivenöl beträufeln, mit Kräutern, Salz und Pfeffer bestreuen. 5. Form mit Folie abdecken und 30 Minuten im vorgeheizten Ofen backen. 6. Folie entfernen und weitere 10–15 Minuten backen, bis das Gemüse goldbraun ist. 7. Heiß servieren und mit frischen Kräutern garnieren.', 2, 'Insgesamt 800 g Gemüse plus 30 ml Öl ergeben eine größere Menge, die typischerweise für 2 Portionen als Beilage reicht; 239 kcal pro Portion liegen im Beilagen-Bereich und näher am alten Wert als 1 Portion.', 477, 240, 5, 19, 16, 'Aubergine 200 g = 48 kcal; Tomaten 200 g = 36 kcal; Zucchini 200 g = 34 kcal; Paprika 100 g = 31 kcal; Zwiebel 100 g = 40 kcal; Knoblauch 10 g = 15 kcal; Olivenöl 30 g = 270 kcal; Provenzalische Kräuter 1 g = 3 kcal; Summe = 477 kcal (÷2 Portionen = 239 kcal)'),
  (92, 'Couscous mit Minze und Zitrone', 'Beilagen', 'Couscous mit Minze und Zitrone ist ein leichtes Mittagessen oder eine erfrischende Beilage – ideal, wenn es schnell gehen soll. Guten Appetit!', '[{"name":"Couscous","menge_anzeige":"100 g","gramm":100},{"name":"Wasser","menge_anzeige":"200 ml","gramm":200},{"name":"Frische Minze","menge_anzeige":"10 g","gramm":10},{"name":"Zitrone (Saft und Schale)","menge_anzeige":"1/2 Stück (ca. 50 g)","gramm":50},{"name":"Olivenöl","menge_anzeige":"15 ml","gramm":15},{"name":"Salz","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Schwarzer Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Wasser zum Kochen bringen und leicht salzen. 2. Couscous in eine tiefe Schüssel geben und mit dem kochenden Wasser übergießen. 3. Schüssel abdecken und 5-10 Minuten stehen lassen, bis der Couscous das Wasser vollständig aufgenommen hat. 4. Minze fein hacken, Zitronenschale abreiben und den Saft auspressen. 5. Couscous mit einer Gabel auflockern, Olivenöl, Zitronensaft und -schale sowie die gehackte Minze hinzufügen. 6. Gut mischen und nach Geschmack mit Salz und Pfeffer würzen. 7. Warm oder kalt servieren.', 2, '528 kcal gesamt ergeben bei 2 Portionen ca. 264 kcal, was als leichte Mittags-Beilage am plausibelsten ist und am ehesten zum alten Wert (320 kcal) passt.', 528, 265, 7, 41, 8, 'Couscous 100g=376kcal; Minze 10g=4kcal; Zitrone 50g=15kcal; Olivenöl 15g=133kcal; Wasser/Salz/Pfeffer=0kcal; Summe=528kcal'),
  (93, 'Bohnen-Tomaten-Ragout', 'Beilagen', 'Bohnen-Tomaten-Ragout ist ein sättigendes und nahrhaftes Gericht, das als Beilage oder Hauptgericht serviert werden kann. Bohnen sind reich an Eiweiß und Ballaststoffen, während Tomaten für Frische und Saftigkeit sorgen. Ideal für Vegetarier und gesundheitsbewusste Genießer.', '[{"name":"Weiße Bohnen (Konserve)","menge_anzeige":"150 g","gramm":150},{"name":"Tomaten","menge_anzeige":"200 g","gramm":200},{"name":"Zwiebel","menge_anzeige":"100 g","gramm":100},{"name":"Knoblauch","menge_anzeige":"2 Zehen (10 g)","gramm":10},{"name":"Olivenöl","menge_anzeige":"15 ml","gramm":15},{"name":"Salz, Pfeffer und Basilikum","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Zwiebel und Knoblauch hacken und in Olivenöl anbraten, bis sie weich sind. 2. Tomaten in Würfel schneiden, hinzufügen und bei mittlerer Hitze kochen, bis sie weich sind. 3. Weiße Bohnen hinzufügen, mit Salz und Pfeffer abschmecken und weitere 5-10 Minuten kochen. 4. Heiß servieren und mit frischem Basilikum bestreuen.', 1, '359 kcal liegen nah am alten Wert (300 kcal) und passen als sättigende Einzelportion Haupt- oder Beilagengericht.', 359, 360, 13, 38, 16, 'Weiße Bohnen 150g=135kcal; Tomaten 200g=36kcal; Zwiebel 100g=40kcal; Knoblauch 10g=15kcal; Olivenöl 15g=133kcal; Gewürze=0kcal; Summe=359kcal'),
  (94, 'Gebackene Rote Beete mit Balsamico-Essig', 'Beilagen', 'Gebackene Rote Beete mit Balsamico-Essig ist eine farbenfrohe und schmackhafte Beilage, die zu jedem Hauptgericht passt. Die süßliche Rote Beete harmoniert perfekt mit der Säure des Balsamico-Essigs und dem Aroma des frischen Thymians. Dieses Gericht ist reich an Antioxidantien und Vitaminen.', '[{"name":"Rote Beete","menge_anzeige":"200 g","gramm":200},{"name":"Balsamico-Essig","menge_anzeige":"15 ml","gramm":15},{"name":"Olivenöl","menge_anzeige":"15 ml","gramm":15},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frischer Thymian","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Ofen auf 200°C vorheizen. 2. Rote Beete schälen und in Würfel schneiden. 3. Rote Beete auf ein Backblech legen, mit Olivenöl und Balsamico-Essig beträufeln, mit Salz, Pfeffer und Thymian bestreuen. 4. 30-40 Minuten im Ofen backen, bis sie weich ist. 5. Warm oder kalt servieren.', 1, '200 g Rote Beete sind eine realistische Einzelportion als Beilage; 232 kcal liegen im Beilagen-Richtwert (150-400 kcal).', 232, 230, 3, 20, 15, 'Rote Beete 200g=86kcal; Balsamico-Essig 15g=13kcal; Olivenöl 15g=133kcal; Gewürze=0kcal; Summe=232kcal'),
  (95, 'Süßkartoffel-Pommes', 'Beilagen', 'Süßkartoffel-Pommes sind eine leckere und gesunde Alternative zu traditionellen Pommes Frites, ideal als Snack oder Beilage. Guten Appetit!', '[{"name":"Süßkartoffel","menge_anzeige":"200 g","gramm":200},{"name":"Olivenöl","menge_anzeige":"15 ml","gramm":15},{"name":"Salz","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Paprika (gemahlen)","menge_anzeige":"1/2 TL (ca. 1 g)","gramm":1},{"name":"Knoblauchpulver","menge_anzeige":"1/4 TL (ca. 0,5 g)","gramm":0.5},{"name":"Schwarzer Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Ofen auf 220°C vorheizen. 2. Süßkartoffel schälen und in dünne Streifen schneiden. 3. Süßkartoffelstreifen in einer Schüssel mit Olivenöl, Salz, Paprika, Knoblauchpulver und Pfeffer vermengen. 4. Süßkartoffeln in einer Schicht auf ein Backblech legen, sodass sich die Stücke nicht berühren. 5. 25-30 Minuten im vorgeheizten Ofen backen, dabei zur Halbzeit wenden, bis die Pommes goldbraun und knusprig sind.', 1, '200 g Süßkartoffel ergeben eine realistische Einzelportion; 309 kcal liegen im Beilagen-Richtwert (150-400 kcal).', 309, 310, 3, 41, 15, 'Süßkartoffel 200g=172kcal; Olivenöl 15g=133kcal; Paprika 1g=3kcal; Knoblauchpulver 0,5g=2kcal; Salz/Pfeffer=0kcal; Summe=309kcal'),
  (96, 'Geschmorte Linsen mit Karotten und Sellerie', 'Beilagen', 'Geschmorte Linsen mit Karotten und Sellerie sind eine sättigende und nahrhafte Beilage, reich an Eiweiß und Ballaststoffen. Linsen harmonieren hervorragend mit Gemüse und schaffen ein aromatisches und schmackhaftes Gericht. Ideal für alle, die auf ihre Gesundheit achten und mehr pflanzliche Proteine in ihre Ernährung aufnehmen möchten.', '[{"name":"Linsen (trocken)","menge_anzeige":"100 g","gramm":100},{"name":"Karotte","menge_anzeige":"100 g","gramm":100},{"name":"Sellerie","menge_anzeige":"50 g","gramm":50},{"name":"Zwiebel","menge_anzeige":"50 g","gramm":50},{"name":"Knoblauch","menge_anzeige":"1 Zehe (5 g)","gramm":5},{"name":"Olivenöl","menge_anzeige":"15 ml","gramm":15},{"name":"Tomatenmark","menge_anzeige":"20 g","gramm":20},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Gemüsebrühe (oder Wasser)","menge_anzeige":"300 ml","gramm":300}]'::jsonb, '1. Karotte, Sellerie und Zwiebel in Würfel schneiden, Knoblauch hacken. 2. Olivenöl in einem Topf erhitzen und Zwiebel, Karotte, Sellerie und Knoblauch anbraten, bis sie weich sind. 3. Tomatenmark hinzufügen und 2-3 Minuten weitergaren. 4. Linsen abspülen und in den Topf geben. 5. Mit Wasser oder Gemüsebrühe aufgießen, zum Kochen bringen, dann Hitze reduzieren und zugedeckt 20-25 Minuten köcheln lassen, bis die Linsen gar sind. 6. Mit Salz und Pfeffer abschmecken und heiß servieren.', 2, '593 kcal gesamt geteilt durch 2 ergeben ca. 297 kcal, was sehr nah am alten Wert (320 kcal) liegt und als sättigende Beilage realistisch ist.', 593, 295, 14, 36, 8, 'Linsen 100g=353kcal; Karotte 100g=41kcal; Sellerie 50g=8kcal; Zwiebel 50g=20kcal; Knoblauch 5g=7kcal; Olivenöl 15g=133kcal; Tomatenmark 20g=16kcal; Gemüsebrühe 300ml=15kcal; Salz/Pfeffer=0kcal; Summe=593kcal'),
  (97, 'Gebackener Spargel mit Zitrone und Parmesan', 'Beilagen', 'Gebackener Spargel mit Zitrone und Parmesan ist eine leichte und elegante Beilage, die zu jedem festlichen Tisch passt. Reich an Vitaminen und Mineralstoffen, wird der Spargel durch den Parmesan mit einem pikanten Geschmack veredelt. Dieses Gericht passt hervorragend zu Fleisch und Fisch.', '[{"name":"Spargel","menge_anzeige":"200 g","gramm":200},{"name":"Olivenöl","menge_anzeige":"15 ml","gramm":15},{"name":"Zitrone (Saft und Schale)","menge_anzeige":"1/2 Stück (ca. 50 g)","gramm":50},{"name":"Parmesan","menge_anzeige":"20 g","gramm":20},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Ofen auf 200°C vorheizen. 2. Spargel auf ein Backblech legen, mit Olivenöl und Zitronensaft beträufeln. 3. Mit Salz, Pfeffer und Zitronenschale bestreuen. 4. 15-20 Minuten im Ofen backen, bis der Spargel goldbraun ist. 5. Mit geriebenem Parmesan bestreuen und weitere 2-3 Minuten backen, bis der Käse schmilzt. 6. Heiß servieren.', 1, '200 g Spargel sind eine übliche Einzelportion als Beilage; 266 kcal liegen im Beilagen-Richtwert (150-400 kcal).', 266, 265, 12, 12, 21, 'Spargel 200g=40kcal; Olivenöl 15g=133kcal; Zitrone 50g=15kcal; Parmesan 20g=78kcal; Salz/Pfeffer=0kcal; Summe=266kcal'),
  (98, 'Geschmorter Weißkohl mit Äpfeln', 'Beilagen', 'Geschmorter Weißkohl mit Äpfeln ist eine ungewöhnliche und schmackhafte Beilage, ideal für die Winterzeit. Äpfel verleihen Süße und Frische, während der Kohl weich und aromatisch wird. Einfach zuzubereiten und eine perfekte Ergänzung zu Fleischgerichten.', '[{"name":"Weißkohl","menge_anzeige":"200 g","gramm":200},{"name":"Apfel","menge_anzeige":"1 Stück (ca. 150 g)","gramm":150},{"name":"Zwiebel","menge_anzeige":"1/2 Stück (ca. 50 g)","gramm":50},{"name":"Olivenöl","menge_anzeige":"1 EL (10 g)","gramm":10},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Apfelessig","menge_anzeige":"1 EL (15 ml)","gramm":15},{"name":"Süßstoff","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Weißkohl, Apfel und Zwiebel schneiden. 2. Olivenöl in einer Pfanne erhitzen und die Zwiebel glasig braten. 3. Weißkohl und Apfel hinzufügen und bei mittlerer Hitze schmoren, bis sie weich sind. 4. Apfelessig und Süßstoff hinzufügen, mit Salz und Pfeffer abschmecken. 5. Weitere 5-10 Minuten schmoren, bis der Kohl weich und aromatisch ist. 6. Heiß servieren.', 1, 'Bei 2 Portionen läge der Wert (120 kcal) unter dem Beilagen-Richtwert (150-400 kcal); als 1 Portion (240 kcal) ist die Menge realistischer.', 240, 240, 4, 33, 11, 'Weißkohl 200g=50kcal; Apfel 150g=78kcal; Zwiebel 50g=20kcal; Olivenöl 10g=88kcal; Apfelessig 15g=3kcal; Süßstoff=0kcal; Summe=240kcal'),
  (99, 'Gebratener Spinat mit Knoblauch', 'Beilagen', 'Gebratener Spinat mit Knoblauch ist eine leichte und gesunde Beilage, die schnell zuzubereiten ist und zu jedem Hauptgericht passt. Spinat ist reich an Eisen und Vitaminen, während Knoblauch einen pikanten Geschmack beisteuert. Zitronensaft verleiht dem Gericht Frische und macht es noch appetitlicher.', '[{"name":"Frischer Spinat","menge_anzeige":"200 g","gramm":200},{"name":"Knoblauch","menge_anzeige":"2 Zehen (10 g)","gramm":10},{"name":"Olivenöl","menge_anzeige":"15 ml","gramm":15},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Zitronensaft","menge_anzeige":"1 TL (5 ml)","gramm":5}]'::jsonb, '1. Olivenöl in einer Pfanne bei mittlerer Hitze erhitzen. 2. Knoblauch hacken und in die Pfanne geben, bis er goldbraun ist. 3. Spinat hinzufügen und unter Rühren braten, bis er welk ist. 4. Mit Salz, Pfeffer und Zitronensaft abschmecken. 5. Heiß servieren.', 1, '200 g Spinat sind eine übliche Einzelportion als Beilage; 195 kcal liegen im Beilagen-Richtwert (150-400 kcal).', 195, 195, 6, 11, 16, 'Spinat 200g=46kcal; Knoblauch 10g=15kcal; Olivenöl 15g=133kcal; Zitronensaft 5g=1kcal; Salz/Pfeffer=0kcal; Summe=195kcal'),
  (100, 'Gebackenes Gemüse mit Quinoa und Hummus', 'Beilagen', 'Dieses Gericht ist nicht nur schmackhaft, sondern auch gesund, da es reich an Eiweiß und Ballaststoffen aus Quinoa und Gemüse ist. Hummus fügt eine cremige Textur und zusätzliche Nährstoffe hinzu. Es ist perfekt als Hauptgericht oder als leichtes Mittagessen bzw. Beilage zu einem Hauptgericht.', '[{"name":"Quinoa","menge_anzeige":"1 Tasse (ca. 170 g)","gramm":170},{"name":"Wasser","menge_anzeige":"2 Tassen (480 ml)","gramm":480},{"name":"Paprika (rot und gelb)","menge_anzeige":"2 Stück (ca. 300 g)","gramm":300},{"name":"Zucchini","menge_anzeige":"200 g","gramm":200},{"name":"Rote Zwiebel","menge_anzeige":"1 Stück (ca. 100 g)","gramm":100},{"name":"Blumenkohlröschen","menge_anzeige":"1 Tasse (ca. 100 g)","gramm":100},{"name":"Olivenöl","menge_anzeige":"3 EL (30 g)","gramm":30},{"name":"Paprika (gemahlen)","menge_anzeige":"1 TL (ca. 2 g)","gramm":2},{"name":"Gemahlener Kreuzkümmel","menge_anzeige":"1 TL (ca. 2 g)","gramm":2},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Hummus","menge_anzeige":"1/2 Tasse (ca. 120 g)","gramm":120},{"name":"Frische Kräuter (Petersilie oder Koriander)","menge_anzeige":"zum Garnieren","gramm":null}]'::jsonb, '1. Quinoa zubereiten: Quinoa unter kaltem Wasser abspülen. Wasser in einem Topf zum Kochen bringen. 2. Quinoa hinzufügen, die Hitze auf mittlere Stufe reduzieren und 15 Minuten köcheln lassen, bis das Wasser vollständig aufgenommen ist. 3. Vom Herd nehmen, abdecken und 5 Minuten stehen lassen, dann mit einer Gabel auflockern. 4. Gemüse backen: Ofen auf 200°C vorheizen. In einer großen Schüssel das geschnittene Gemüse (Paprika, Zucchini, rote Zwiebel und Blumenkohl) mit Olivenöl, Paprika, Kreuzkümmel, Salz und Pfeffer mischen. 5. Das Gemüse auf ein mit Backpapier ausgelegtes Backblech legen und 25-30 Minuten backen, bis es weich und leicht gebräunt ist. 6. Gericht zusammenstellen: Quinoa und gebackenes Gemüse in einer großen Schüssel mischen und auf Teller verteilen. 7. Obenauf je einen Löffel Hummus und (nach Wunsch) ein Spiegelei geben. 8. Vor dem Servieren mit frischen Kräutern garnieren.', 6, 'Die große Menge an Gemüse (700 g), Quinoa (170 g) und Hummus ergibt bei realistischer Portionierung als Beilage 6 Portionen, was mit ca. 216 kcal pro Portion auch am nächsten am alten Wert (230 kcal) liegt.', 1295, 215, 7, 26, 9, 'Quinoa 170g=626kcal; Paprika (Gemüse) 300g=93kcal; Zucchini 200g=34kcal; Rote Zwiebel 100g=40kcal; Blumenkohl 100g=25kcal; Olivenöl 30g=265kcal; Paprika-Gewürz 2g=6kcal; Kreuzkümmel 2g=8kcal; Hummus 120g=199kcal; Wasser/Salz/Pfeffer/Kräuter=0kcal; Summe=1295kcal'),
  (101, 'Nussriegel mit Honig', 'Snacks', 'Diese Nussriegel sind reich an Proteinen, gesunden Fetten und Ballaststoffen und eignen sich gut als nahrhafter Snack oder Energiespender für unterwegs.', '[{"name":"Mandeln","menge_anzeige":"50 g","gramm":50},{"name":"Walnüsse","menge_anzeige":"50 g","gramm":50},{"name":"Haselnüsse","menge_anzeige":"50 g","gramm":50},{"name":"Kürbiskerne","menge_anzeige":"25 g","gramm":25},{"name":"Sonnenblumenkerne","menge_anzeige":"25 g","gramm":25},{"name":"Getrocknete Cranberries","menge_anzeige":"50 g","gramm":50},{"name":"Honig","menge_anzeige":"100 g","gramm":100},{"name":"Kokosöl","menge_anzeige":"15 ml","gramm":15}]'::jsonb, '1. Ofen auf 180°C vorheizen. 2. Große Nüsse (Mandeln, Walnüsse, Haselnüsse) in Stücke schneiden. 3. Alle Nüsse, Kerne und getrocknete Cranberries in einer Schüssel mischen. 4. Honig und Kokosöl in einem kleinen Topf bei mittlerer Hitze erhitzen, bis sie flüssig sind. 5. Honig-Kokosöl-Mischung zu den Nüssen geben und gut vermengen, bis alle Zutaten gleichmäßig bedeckt sind. 6. Mischung auf ein mit Backpapier ausgelegtes Blech geben und glattstreichen. 7. Im vorgeheizten Ofen 15-20 Minuten goldbraun backen, dann vollständig abkühlen lassen. 8. In Riegel schneiden und servieren.', 3, '1812 kcal gesamt geteilt durch 3 ergeben ca. 604 kcal, was fast exakt dem alten Wert (620 kcal) entspricht; die Riegel sind damit eher große, energiedichte Portionen als klassische kleine Snacks (Hinweis: liegt über dem üblichen Snack-Richtwert von 100-350 kcal – bei kleineren Stücken wären 6-8 Portionen realistischer).', 1812, 605, 13, 50, 43, 'Mandeln 50g=290kcal; Walnüsse 50g=327kcal; Haselnüsse 50g=314kcal; Kürbiskerne 25g=140kcal; Sonnenblumenkerne 25g=146kcal; Cranberries 50g=163kcal; Honig 100g=304kcal; Kokosöl 15g=129kcal; Summe=1812kcal'),
  (102, 'Joghurtbällchen mit Früchten', 'Snacks', 'Diese Joghurtbällchen mit Früchten sind eine gesunde und leckere Option für einen Snack oder ein Dessert, reich an Proteinen, Ballaststoffen und wertvollen Nährstoffen aus den Früchten und Haferflocken.', '[{"name":"Griechischer Joghurt","menge_anzeige":"200 g","gramm":200},{"name":"Honig","menge_anzeige":"1 EL (20 g)","gramm":20},{"name":"Haferflocken","menge_anzeige":"50 g","gramm":50},{"name":"Trockenfrüchte (Rosinen, getrocknete Aprikosen, Pflaumen)","menge_anzeige":"50 g","gramm":50},{"name":"Kokosraspeln","menge_anzeige":"30 g","gramm":30},{"name":"Frische Früchte (Erdbeeren, Himbeeren, Blaubeeren)","menge_anzeige":"100 g","gramm":100}]'::jsonb, '1. Griechischen Joghurt und Honig in einer Schüssel zu einer homogenen Masse verrühren. 2. Trockenfrüchte zerkleinern und zur Joghurtmischung geben. 3. Haferflocken hinzufügen und gut vermengen. 4. Aus der Mischung kleine Bällchen formen. 5. Bällchen in Kokosraspeln wälzen. 6. Bällchen 1-2 Stunden im Kühlschrank fest werden lassen. 7. Mit geschnittenen frischen Früchten servieren.', 2, '827 kcal gesamt geteilt durch 2 ergeben ca. 414 kcal, was fast exakt dem alten Wert (410 kcal) entspricht.', 827, 415, 10, 50, 21, 'Griech. Joghurt 200g=230kcal; Honig 20g=61kcal; Haferflocken 50g=186kcal; Trockenfrüchte 50g=135kcal; Kokosraspeln 30g=178kcal; Frische Früchte 100g=38kcal; Summe=827kcal'),
  (103, 'Hummus mit Karottensticks', 'Snacks', 'Diese Kombination aus cremigem Hummus und frischen Karottensticks ist reich an Ballaststoffen, Proteinen und gesunden Fetten und eignet sich ideal als gesunder Snack oder als Vorspeise.', '[{"name":"Kichererbsen (gekocht oder aus der Dose)","menge_anzeige":"150 g","gramm":150},{"name":"Tahini (Sesampaste)","menge_anzeige":"1 EL (15 g)","gramm":15},{"name":"Olivenöl","menge_anzeige":"1 EL (10 g)","gramm":10},{"name":"Knoblauch","menge_anzeige":"1 Zehe (5 g)","gramm":5},{"name":"Zitronensaft","menge_anzeige":"1 EL (15 ml)","gramm":15},{"name":"Wasser","menge_anzeige":"2-3 EL","gramm":null},{"name":"Salz, Paprika","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Olivenöl (zum Garnieren)","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Karotten","menge_anzeige":"2 Stück (ca. 120 g)","gramm":120}]'::jsonb, '1. Für den Hummus: Kichererbsen, Tahini, Olivenöl, Knoblauch, Zitronensaft und Salz in einem Mixer vermengen. 2. Wasser hinzufügen, um die gewünschte Konsistenz zu erreichen. Mixen, bis eine homogene Masse entsteht. 3. Hummus in eine Schüssel geben und nach Belieben mit Paprika und Olivenöl garnieren. 4. Karotten schälen und in Sticks schneiden. 5. Hummus mit Karottensticks servieren.', 2, 'Die Menge Hummus (ca. 200 g fertige Masse) plus 2 Karotten ergibt realistisch 2 Portionen als Snack/Vorspeise; mit ca. 223 kcal pro Portion liegt dies gut im Snack-Richtwert (100-350 kcal).', 446, 225, 8, 23, 11, 'Kichererbsen 150g=209kcal; Tahini 15g=89kcal; Olivenöl 10g=88kcal; Knoblauch 5g=7kcal; Zitronensaft 15g=3kcal; Karotten 120g=49kcal; Wasser/Salz/Paprika=0kcal; Summe=446kcal'),
  (104, 'Overnight Oats mit Beeren', 'Snacks', 'Diese Overnight Oats bieten eine gute Balance aus Proteinen, gesunden Fetten und Kohlenhydraten. Sie sind reich an Ballaststoffen und sättigen gut, was sie zu einer idealen Wahl für einen energiereichen Start in den Tag macht.', '[{"name":"Haferflocken","menge_anzeige":"50 g","gramm":50},{"name":"Mandelmilch","menge_anzeige":"100 ml","gramm":100},{"name":"Griechischer Joghurt","menge_anzeige":"50 g","gramm":50},{"name":"Frische Beeren (Blaubeeren, Himbeeren, Erdbeeren)","menge_anzeige":"50 g","gramm":50},{"name":"Honig","menge_anzeige":"1 TL (7 g)","gramm":7},{"name":"Chiasamen","menge_anzeige":"1 EL (15 g)","gramm":15}]'::jsonb, '1. Haferflocken, Mandelmilch, griechischen Joghurt, Honig und Chiasamen in ein Glas oder einen Behälter geben und gut vermischen. 2. Frische Beeren hinzufügen. 3. Glas verschließen und über Nacht oder mindestens 4 Stunden im Kühlschrank aufbewahren. 4. Gekühlt servieren.', 1, 'Die Zutatenmenge entspricht einem typischen Einzelportions-Glas Overnight Oats; 374 kcal liegen nah am alten Wert (300 kcal).', 374, 375, 13, 48, 15, 'Haferflocken 50g=186kcal; Mandelmilch 100g=17kcal; Griech. Joghurt 50g=58kcal; Frische Beeren 50g=19kcal; Honig 7g=21kcal; Chiasamen 15g=73kcal; Summe=374kcal'),
  (105, 'Zuckerfreie Mandelkekse', 'Snacks', 'Diese zuckerfreien Mandelkekse sind eine köstliche Option für alle, die auf zugesetzten Zucker verzichten möchten, aber dennoch etwas Süßes genießen möchten.', '[{"name":"Mandelmehl","menge_anzeige":"100 g","gramm":100},{"name":"Ei","menge_anzeige":"1 Stück","gramm":55},{"name":"Kokosöl (geschmolzen)","menge_anzeige":"2 EL","gramm":20},{"name":"Vanilleextrakt","menge_anzeige":"1 TL","gramm":5},{"name":"Süßstoff (z. B. Stevia)","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Salz","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Ofen auf 180 °C vorheizen und ein Backblech mit Backpapier auslegen.
2. Mandelmehl, Ei, geschmolzenes Kokosöl, Vanilleextrakt, Süßstoff und Salz in einer Schüssel zu einem Teig vermengen.
3. Aus dem Teig kleine Kugeln formen und leicht flach drücken, um Kekse zu formen.
4. Kekse auf das Backblech legen und 12–15 Minuten goldbraun backen.
5. Vor dem Servieren vollständig abkühlen lassen.', 4, 'Der Teig ergibt mehrere kleine Kekse; bei 871 kcal Gesamtmenge liegt eine Aufteilung in 4 Portionen (218 kcal) sehr nah am Altwert von 220 kcal.', 871, 220, 7, 2, 20, 'Mandelmehl 100 g = 610 kcal; Ei 55 g = 85 kcal; Kokosöl 20 g = 172 kcal; Vanilleextrakt 5 g = 3 kcal; Süßstoff/Salz nach Geschmack = 0 kcal; Summe = 871 kcal (÷4 Portionen = 218 ≈ 220 kcal/Portion)'),
  (106, 'Fruchtspieße', 'Snacks', 'Diese Fruchtspieße sind eine erfrischende und gesunde Snackoption, die sich ideal für Partys, Picknicks oder einfach als leichter Genuss zwischendurch eignet.', '[{"name":"Erdbeeren","menge_anzeige":"50 g","gramm":50},{"name":"Kiwi","menge_anzeige":"1 Stück","gramm":70},{"name":"Trauben","menge_anzeige":"50 g","gramm":50},{"name":"Ananas","menge_anzeige":"50 g","gramm":50}]'::jsonb, '1. Kiwi und Ananas in kleine Stücke schneiden.
2. Erdbeeren, Kiwi, Trauben und Ananas abwechselnd auf Spieße oder Holzstäbchen stecken.
3. Sofort servieren oder bis zum Servieren im Kühlschrank aufbewahren.', 1, 'Die Menge ergibt einen Fruchtspieß als Einzelportion (117 kcal), passend zum Snack-Richtwert und nah am Altwert von 100 kcal.', 117, 115, 2, 24, 1, 'Erdbeeren 50 g = 16 kcal; Kiwi 70 g = 43 kcal; Trauben 50 g = 34 kcal; Ananas 50 g = 25 kcal; Summe = 117 kcal'),
  (107, 'Smoothie Bowl mit Beeren und Chiasamen', 'Snacks', 'Diese Smoothie Bowl bietet eine gute Balance aus Proteinen, gesunden Fetten und Kohlenhydraten. Sie ist reich an Ballaststoffen und sättigt gut, was sie zu einer idealen Wahl für einen energiereichen Start in den Tag macht.', '[{"name":"Gefrorene Beeren (Blaubeeren, Himbeeren, Erdbeeren)","menge_anzeige":"150 g","gramm":150},{"name":"Banane","menge_anzeige":"1 Stück","gramm":120},{"name":"Griechischer Joghurt","menge_anzeige":"100 g","gramm":100},{"name":"Mandelmilch","menge_anzeige":"100 ml","gramm":100},{"name":"Chiasamen","menge_anzeige":"1 EL","gramm":10},{"name":"Frische Beeren zum Garnieren","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Granola","menge_anzeige":"2 EL","gramm":30},{"name":"Kokosraspeln","menge_anzeige":"1 EL","gramm":8},{"name":"Minze","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Gefrorene Beeren, Banane, griechischen Joghurt und Mandelmilch in einem Mixer zu einer homogenen Masse vermixen.
2. Chiasamen hinzufügen und gut verrühren.
3. Smoothie in eine Schüssel geben.
4. Mit frischen Beeren, Granola, Kokosraspeln und Minze garnieren.
5. Sofort servieren.', 1, 'Die Zutatenmenge (u. a. 150 g Beeren, 1 Banane, 100 g Joghurt) entspricht einer typischen Einzelportion Frühstücks-Smoothie-Bowl (543 kcal), im Rahmen des Richtwerts 300–650 kcal.', 543, 545, 13, 58, 25, 'Gefrorene Beeren 150 g = 63 kcal; Banane 120 g = 107 kcal; Griechischer Joghurt 100 g = 115 kcal; Mandelmilch 100 ml = 15 kcal; Chiasamen 10 g = 49 kcal; Granola 30 g = 141 kcal; Kokosraspeln 8 g = 53 kcal; Summe = 543 kcal'),
  (108, 'Avocado-Tomaten-Toast', 'Snacks', 'Dieser Avocado-Tomaten-Toast ist nicht nur lecker, sondern auch gesund und bietet eine gute Mischung aus gesunden Fetten, Proteinen und Kohlenhydraten für einen perfekten Start in den Tag.', '[{"name":"Vollkornbrot","menge_anzeige":"2 Scheiben","gramm":60},{"name":"Avocado","menge_anzeige":"1/2 Stück","gramm":75},{"name":"Tomate","menge_anzeige":"1 Stück","gramm":120},{"name":"Zitronensaft","menge_anzeige":"1 TL","gramm":5},{"name":"Olivenöl","menge_anzeige":"1 TL","gramm":4},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frischer Basilikum oder Koriander","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Vollkornbrot im Toaster oder in einer trockenen Pfanne goldbraun rösten.
2. Avocado schälen und in einer Schüssel mit einer Gabel zerdrücken.
3. Zitronensaft, Olivenöl, Salz und Pfeffer zur Avocado geben und gut vermengen.
4. Tomate in dünne Scheiben schneiden.
5. Avocado auf die gerösteten Brotscheiben streichen.
6. Tomatenscheiben darauflegen.
7. Mit frischem Basilikum oder Koriander garnieren.
8. Sofort servieren.', 1, 'Zwei Scheiben Toast mit Belag ergeben eine übliche Einzelportion (308 kcal), sehr nah am Altwert von 300 kcal.', 308, 310, 8, 28, 17, 'Vollkornbrot 60 g = 132 kcal; Avocado 75 g = 120 kcal; Tomate 120 g = 22 kcal; Zitronensaft 5 g = 1 kcal; Olivenöl 4 g = 33 kcal; Summe = 308 kcal'),
  (109, 'Energiekugeln mit Datteln und Nüssen', 'Snacks', 'Diese Energiekugeln sind eine köstliche und nahrhafte Option für Zwischenmahlzeiten oder als Energieboost vor oder nach dem Sport.', '[{"name":"Datteln","menge_anzeige":"100 g","gramm":100},{"name":"Mandeln","menge_anzeige":"50 g","gramm":50},{"name":"Kokosraspeln","menge_anzeige":"20 g","gramm":20},{"name":"Kakaopulver","menge_anzeige":"1 EL","gramm":8},{"name":"Kokosöl","menge_anzeige":"1 EL","gramm":10},{"name":"Vanilleextrakt","menge_anzeige":"1 TL","gramm":5}]'::jsonb, '1. Datteln und Mandeln in einem Mixer zu feinen Krümeln zerkleinern.
2. Kokosraspeln, Kakaopulver, Kokosöl und Vanilleextrakt hinzufügen.
3. Zu einer homogenen Masse vermengen.
4. Aus der Mischung kleine Kugeln formen.
5. Kugeln 1–2 Stunden im Kühlschrank fest werden lassen.
6. Gekühlt servieren.', 3, 'Bei einem Snack-Richtwert von 100–350 kcal und 806 kcal Gesamtmenge ergeben sich realistisch 3 Portionen (je ca. 269 kcal, mehrere Kugeln pro Portion).', 806, 270, 5, 23, 17, 'Datteln 100 g = 277 kcal; Mandeln 50 g = 290 kcal; Kokosraspeln 20 g = 132 kcal; Kakaopulver 8 g = 18 kcal; Kokosöl 10 g = 86 kcal; Vanilleextrakt 5 g = 3 kcal; Summe = 806 kcal (÷3 Portionen = 269 kcal/Portion)'),
  (110, 'Bananen-Rolle', 'Snacks', 'Diese Bananen-Rolle ist eine einfache und köstliche Option für ein schnelles Frühstück oder einen Snack, besonders geeignet für unterwegs oder zwischendurch.', '[{"name":"Fladenbrot (oder Tortilla)","menge_anzeige":"1 Stück","gramm":60},{"name":"Banane","menge_anzeige":"1 Stück","gramm":120},{"name":"Erdnussbutter (oder andere Nussbutter)","menge_anzeige":"2 EL","gramm":32},{"name":"Honig","menge_anzeige":"1 TL","gramm":7},{"name":"Zimt","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Fladenbrot oder Tortilla auf eine ebene Fläche legen.
2. Erdnussbutter gleichmäßig auf dem Fladenbrot verteilen.
3. Optional: Erdnussbutter mit Honig beträufeln.
4. Banane schälen und an den Rand des Fladenbrots legen.
5. Banane nach Geschmack mit Zimt bestreuen.
6. Fladenbrot fest einrollen, beginnend am Rand mit der Banane.
7. Rolle in kleine Stücke schneiden und sofort servieren.', 2, 'Als Snack (Kategorie) wird der ganze Wrap realistischerweise in 2 Portionen geteilt (je ca. 240 kcal), passend zum Snack-Richtwert 100–350 kcal.', 481, 240, 7, 33, 9, 'Fladenbrot 60 g = 165 kcal; Banane 120 g = 107 kcal; Erdnussbutter 32 g = 188 kcal; Honig 7 g = 21 kcal; Summe = 481 kcal (÷2 Portionen = 240 kcal/Portion)'),
  (111, 'Putenröllchen mit Gemüse', 'Snacks', 'Diese Putenröllchen mit Gemüse sind eine gesunde Wahl für ein leckeres Mittag- oder Abendessen.', '[{"name":"Putenfilet","menge_anzeige":"150 g","gramm":150},{"name":"Karotte","menge_anzeige":"1 Stück","gramm":60},{"name":"Paprika","menge_anzeige":"1/2 Stück","gramm":75},{"name":"Zucchini","menge_anzeige":"1/2 Stück","gramm":100},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Knoblauch","menge_anzeige":"1 Zehe","gramm":5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Frische Kräuter (Petersilie, Dill)","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Putenfilet in dünne Scheiben schneiden und leicht klopfen, um sie weich und dünn zu machen.
2. Karotte, Paprika und Zucchini in dünne Streifen schneiden.
3. Olivenöl in einer Pfanne erhitzen und den zerkleinerten Knoblauch goldbraun anbraten.
4. Karotte, Paprika und Zucchini in die Pfanne geben und 3–4 Minuten weich braten.
5. Mit Salz und Pfeffer abschmecken.
6. Eine kleine Menge Gemüse auf jede Putenfiletscheibe legen und einrollen.
7. Röllchen mit Zahnstochern fixieren.
8. Ofen auf 180 °C vorheizen.
9. Röllchen auf ein Backblech legen und 20–25 Minuten backen, bis die Pute gar ist.
10. Heiße Röllchen mit frischen Kräutern bestreuen und servieren.', 1, '150 g Putenfilet mit Gemüsefüllung ergeben eine übliche Hauptgericht-Einzelportion (309 kcal), passend zum Altwert 280 kcal und dem Richtwert 300–650 kcal.', 309, 310, 39, 11, 11, 'Putenfilet 150 g = 158 kcal; Karotte 60 g = 21 kcal; Paprika 75 g = 23 kcal; Zucchini 100 g = 17 kcal; Olivenöl 10 g = 83 kcal; Knoblauch 5 g = 7 kcal; Summe = 309 kcal'),
  (112, 'Gewürzpopcorn', 'Snacks', 'Dieses Gewürzpopcorn ist eine köstliche und aromatische Snackoption für gemütliche Abende oder gesellige Zusammenkünfte.', '[{"name":"Maiskörner für Popcorn","menge_anzeige":"50 g","gramm":50},{"name":"Olivenöl","menge_anzeige":"1 EL","gramm":10},{"name":"Salz","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Paprika (gemahlen)","menge_anzeige":"1/2 TL","gramm":1},{"name":"Knoblauchpulver","menge_anzeige":"1/4 TL","gramm":0.6},{"name":"Cayennepfeffer","menge_anzeige":"1 Prise (optional)","gramm":0.3},{"name":"Getrockneter Oregano","menge_anzeige":"1/2 TL","gramm":0.5}]'::jsonb, '1. Olivenöl in einer großen, tiefen Pfanne oder einem Topf bei mittlerer Hitze erhitzen.
2. Maiskörner in die Pfanne geben und mit einem Deckel abdecken.
3. Pfanne gelegentlich schütteln, bis die Körner aufhören zu poppen (ca. 2–3 Minuten).
4. Pfanne vom Herd nehmen und Deckel öffnen, um Dampf abzulassen.
5. Popcorn in eine große Schüssel geben.
6. Mit Salz, Paprika, Knoblauchpulver, Cayennepfeffer und Oregano bestreuen.
7. Gut mischen, damit die Gewürze gleichmäßig verteilt sind.
8. Sofort servieren.', 2, '50 g rohe Maiskörner ergeben aufgepoppt ein großes Volumen; realistisch für 2 Snack-Portionen (je 135 kcal), nah am Altwert 180 kcal.', 270, 135, 2, 17, 6, 'Maiskörner 50 g = 181 kcal; Olivenöl 10 g = 83 kcal; Paprika 1 g = 3 kcal; Knoblauchpulver 0,6 g = 2 kcal; Cayennepfeffer 0,3 g = 1 kcal; Oregano 0,5 g = 1 kcal; Summe = 270 kcal (÷2 Portionen = 135 kcal/Portion)'),
  (113, 'Fruchtsalat', 'Snacks', 'Dieser Fruchtsalat ist eine erfrischende und gesunde Option, perfekt für einen leichten Snack oder als Beilage zu anderen Gerichten.', '[{"name":"Apfel","menge_anzeige":"1 Stück","gramm":125},{"name":"Banane","menge_anzeige":"1 Stück","gramm":120},{"name":"Kiwi","menge_anzeige":"1 Stück","gramm":70},{"name":"Orange","menge_anzeige":"1/2 Stück","gramm":65},{"name":"Trauben (weiß oder rot)","menge_anzeige":"50 g","gramm":50},{"name":"Erdbeeren","menge_anzeige":"50 g","gramm":50},{"name":"Zitronensaft","menge_anzeige":"1 EL","gramm":15},{"name":"Honig","menge_anzeige":"1 TL","gramm":7}]'::jsonb, '1. Apfel, Kiwi, Banane und Orange schälen und in kleine Stücke schneiden.
2. Trauben und Erdbeeren halbieren oder vierteln, wenn die Beeren groß sind.
3. Alle geschnittenen Früchte in eine große Schüssel geben.
4. Zitronensaft darüber geben und optional Honig hinzufügen.
5. Vorsichtig mischen, damit alle Früchte gleichmäßig mit Saft und Honig bedeckt sind.
6. Sofort servieren.', 2, 'Die Fruchtmenge (u. a. 1 Apfel, 1 Banane, 1 Kiwi) ergibt realistisch 2 Portionen Fruchtsalat (je 160 kcal), näher am Altwert 200 kcal als eine Einzelportion (319 kcal).', 319, 160, 2, 34, 1, 'Apfel 125 g = 65 kcal; Banane 120 g = 107 kcal; Kiwi 70 g = 43 kcal; Orange 65 g = 31 kcal; Trauben 50 g = 34 kcal; Erdbeeren 50 g = 16 kcal; Zitronensaft 15 g = 3 kcal; Honig 7 g = 21 kcal; Summe = 319 kcal (÷2 Portionen = 160 kcal/Portion)'),
  (114, 'Hafer-Nuss-Riegel mit Trockenfrüchten', 'Snacks', 'Diese Hafer-Nuss-Riegel mit Trockenfrüchten sind ein köstlicher und energiereicher Snack, ideal für unterwegs oder als gesunde Zwischenmahlzeit.', '[{"name":"Haferflocken","menge_anzeige":"50 g","gramm":50},{"name":"Mandeln","menge_anzeige":"20 g","gramm":20},{"name":"Walnüsse","menge_anzeige":"20 g","gramm":20},{"name":"Trockenfrüchte (Rosinen, getrocknete Aprikosen, Pflaumen)","menge_anzeige":"30 g","gramm":30},{"name":"Honig","menge_anzeige":"2 EL","gramm":40},{"name":"Kokosöl","menge_anzeige":"1 EL","gramm":10},{"name":"Zimt","menge_anzeige":"1/2 TL","gramm":1.3},{"name":"Prise Salz","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Ofen auf 180 °C vorheizen und eine Backform mit Backpapier auslegen.
2. Haferflocken, gehackte Nüsse und Trockenfrüchte in einer Schüssel mischen.
3. Honig und Kokosöl in einem kleinen Topf bei mittlerer Hitze erhitzen, bis sie flüssig sind.
4. Zimt und Salz in den Topf geben und umrühren.
5. Honigmischung in die Schüssel mit Haferflocken, Nüssen und Trockenfrüchten gießen.
6. Gut mischen.
7. Mischung in die Backform geben und glattstreichen.
8. Im vorgeheizten Ofen 15–20 Minuten goldbraun backen.
9. Riegel vollständig abkühlen lassen, dann in Stücke schneiden und servieren.', 3, 'Die Backform-Mischung wird realistisch in 3 Riegel-Portionen geschnitten (je 243 kcal), passend zum Snack-Richtwert 100–350 kcal.', 728, 245, 5, 27, 12, 'Haferflocken 50 g = 186 kcal; Mandeln 20 g = 116 kcal; Walnüsse 20 g = 131 kcal; Trockenfrüchte 30 g = 84 kcal; Honig 40 g = 122 kcal; Kokosöl 10 g = 86 kcal; Zimt 1,3 g = 3 kcal; Summe = 728 kcal (÷3 Portionen = 243 kcal/Portion)'),
  (115, 'Joghurt mit Beeren und Honig', 'Snacks', 'Genießen Sie diesen erfrischenden und nährstoffreichen Joghurt mit Beeren und Honig als leckeres Frühstück oder gesunde Zwischenmahlzeit!', '[{"name":"Griechischer Joghurt","menge_anzeige":"150 g","gramm":150},{"name":"Frische Beeren (Blaubeeren, Himbeeren, Erdbeeren)","menge_anzeige":"100 g","gramm":100},{"name":"Honig","menge_anzeige":"21 g","gramm":21},{"name":"Walnüsse","menge_anzeige":"20 g","gramm":20}]'::jsonb, '1. Griechischen Joghurt und Honig in einer Schüssel zu einer homogenen Masse verrühren.
2. Frische Beeren hinzufügen und vorsichtig mischen.
3. Mit gehackten Walnüssen bestreuen.
4. Sofort servieren.', 2, '150 g Joghurt mit 100 g Beeren ergeben realistisch 2 Portionen (je 205 kcal), näher am Altwert 250 kcal als eine Einzelportion (409 kcal).', 409, 205, 6, 15, 13, 'Griechischer Joghurt 150 g = 173 kcal; Frische Beeren 100 g = 42 kcal; Honig 21 g = 64 kcal; Walnüsse 20 g = 131 kcal; Summe = 409 kcal (÷2 Portionen = 205 kcal/Portion)'),
  (116, 'Käse-Sticks mit Sesam', 'Snacks', 'Diese Käse-Sticks mit Sesam sind eine köstliche und proteinreiche Snack-Option für zwischendurch.', '[{"name":"Hartkäse","menge_anzeige":"50 g","gramm":50},{"name":"Sesam","menge_anzeige":"1 EL","gramm":9}]'::jsonb, '1. Käse in lange Sticks schneiden.
2. Jeden Stick in Sesam wälzen.
3. Sofort servieren oder bis zum Servieren im Kühlschrank aufbewahren.', 1, '50 g Käse mit Sesam ergeben eine übliche Einzelportion Snack (242 kcal), nah am Altwert 200 kcal.', 242, 240, 15, 2, 20, 'Hartkäse 50 g = 190 kcal; Sesam 9 g = 52 kcal; Summe = 242 kcal'),
  (117, 'Nuss-Frucht-Mischung', 'Snacks', 'Diese Nuss-Frucht-Mischung ist ein leckerer und nahrhafter Snack, ideal für unterwegs oder als Energieschub zwischendurch.', '[{"name":"Mandeln","menge_anzeige":"20 g","gramm":20},{"name":"Walnüsse","menge_anzeige":"20 g","gramm":20},{"name":"Haselnüsse","menge_anzeige":"20 g","gramm":20},{"name":"Getrocknete Cranberries","menge_anzeige":"20 g","gramm":20},{"name":"Getrocknete Äpfel","menge_anzeige":"20 g","gramm":20}]'::jsonb, '1. Alle Nüsse und Trockenfrüchte in einer Schüssel mischen.
2. Sofort servieren oder in einem luftdichten Behälter für die Verwendung in der Woche aufbewahren.', 2, 'Die 100 g Mischung (5 × 20 g) ergeben realistisch 2 Portionen (je 245 kcal), passend zum Snack-Richtwert und näher am Altwert 300 kcal als eine Einzelportion (486 kcal).', 486, 245, 5, 15, 18, 'Mandeln 20 g = 116 kcal; Walnüsse 20 g = 131 kcal; Haselnüsse 20 g = 126 kcal; Getrocknete Cranberries 20 g = 65 kcal; Getrocknete Äpfel 20 g = 49 kcal; Summe = 486 kcal (÷2 Portionen = 243 kcal/Portion)'),
  (118, 'Guacamole mit Gemüsesticks', 'Snacks', 'Diese Guacamole mit Gemüsesticks ist eine gesunde und köstliche Option für einen Snack oder als Vorspeise.', '[{"name":"Avocado","menge_anzeige":"150 g","gramm":150},{"name":"Limette (Saft)","menge_anzeige":"1/2 Stück (ca. 15 ml)","gramm":15},{"name":"Rote Zwiebel","menge_anzeige":"1/4 Stück (ca. 25 g)","gramm":25},{"name":"Tomate","menge_anzeige":"1/2 Stück (ca. 60 g)","gramm":60},{"name":"Knoblauch","menge_anzeige":"1 Zehe (5 g)","gramm":5},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null},{"name":"Gurke","menge_anzeige":"1 Stück (ca. 300 g)","gramm":300},{"name":"Karotte","menge_anzeige":"1 Stück (ca. 70 g)","gramm":70},{"name":"Paprika","menge_anzeige":"1/2 Stück (ca. 75 g)","gramm":75}]'::jsonb, '1. Avocado in einer Schüssel mit einer Gabel zu Püree zerdrücken. 2. Rote Zwiebel, Tomate und Knoblauch fein hacken und zur Avocado geben. 3. Limettensaft hinzufügen und mit Salz und Pfeffer abschmecken. 4. Gut mischen, damit alle Zutaten gleichmäßig verteilt sind. 5. Gurke, Karotte und Paprika in Sticks schneiden. 6. Guacamole mit den Gemüsesticks servieren.', 2, 'Die Menge an Gemüsesticks (ganze Gurke, Karotte, halbe Paprika) plus Guacamole reicht für 2 Snack-Portionen; bei 1 Portion läge der Wert am oberen Rand der Snack-Kategorie.', 348, 175, 4, 12, 11, 'Avocado 150 g = 240 kcal; Limette Saft 15 ml = 3 kcal; Rote Zwiebel 25 g = 8 kcal; Tomate 60 g = 11 kcal; Knoblauch 5 g = 8 kcal; Salz/Pfeffer nach Geschmack = 0 kcal; Gurke 300 g = 36 kcal; Karotte 70 g = 25 kcal; Paprika 75 g = 19 kcal; Summe = 348 kcal'),
  (119, 'Detox-Getränk mit Zitrone und Ingwer', 'Getränke', 'Dieses Detox-Getränk ist erfrischend und gesund, unterstützt die Entgiftung des Körpers und fördert das allgemeine Wohlbefinden. Zitronen und Ingwer sind reich an Vitaminen und Antioxidantien, während die Minze ein angenehmes Aroma und Geschmack verleiht. Perfekt zur Durstlöschung und für ein gutes Gefühl den ganzen Tag über. Guten Appetit!', '[{"name":"Wasser","menge_anzeige":"500 ml","gramm":500},{"name":"Zitrone","menge_anzeige":"1/2 Stück (ca. 50 g)","gramm":50},{"name":"Frischer Ingwer","menge_anzeige":"2 cm Wurzel (ca. 10 g)","gramm":10},{"name":"Honig","menge_anzeige":"1 TL (7 g)","gramm":7},{"name":"Minzblätter","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Wasser aufkochen und etwas abkühlen lassen, damit es warm und nicht heiß ist. 2. Zitrone in dünne Scheiben schneiden, Ingwer schälen und reiben. 3. Zitrone, Ingwer und Minzblätter in einen Krug oder ein Glas geben. 4. Mit warmem Wasser übergießen und nach Wunsch Honig für die Süße hinzufügen. 5. Das Getränk 10–15 Minuten ziehen lassen, bevor es serviert wird.', 1, '500 ml aromatisiertes Wasser werden üblicherweise als eine Portion (Krug/Flasche) über den Tag verteilt getrunken.', 44, 45, 1, 9, 0, 'Wasser 500 ml = 0 kcal; Zitrone 50 g = 15 kcal; Frischer Ingwer 10 g = 8 kcal; Honig 7 g (1 TL) = 21 kcal; Minzblätter nach Geschmack = 0 kcal; Summe = 44 kcal'),
  (120, 'Johannisbeersaft ohne Zucker', 'Getränke', 'Johannisbeersaft ohne Zucker ist ein erfrischendes und gesundes Getränk, das perfekt ist, um den Durst zu stillen und die Hydratation zu unterstützen. Johannisbeeren sind reich an Vitaminen, insbesondere Vitamin C, und Antioxidantien, was dieses Getränk nicht nur lecker, sondern auch gesund macht. Guten Appetit!', '[{"name":"Johannisbeeren (schwarz oder rot, frisch oder gefroren)","menge_anzeige":"200 g","gramm":200},{"name":"Wasser","menge_anzeige":"1 Liter","gramm":1000},{"name":"Minze","menge_anzeige":"einige Blätter (optional)","gramm":null}]'::jsonb, '1. Johannisbeeren unter kaltem Wasser abspülen. 2. Wasser in einem Topf zum Kochen bringen. 3. Johannisbeeren ins kochende Wasser geben und bei mittlerer Hitze 10–15 Minuten kochen lassen. 4. Topf vom Herd nehmen und den Saft abkühlen lassen. 5. Saft durch ein Sieb oder Käsetuch abseihen, um die Beeren zu entfernen. 6. Bei Bedarf Minzblätter für zusätzliches Aroma hinzufügen. 7. Den Saft im Kühlschrank kühlen, bevor er serviert wird.', 2, '1 Liter Wasser plus 200 g Johannisbeeren ergeben nach dem Abseihen Saft für 2 Gläser; dieser Wert liegt am nächsten am ursprünglich angegebenen kcal-Wert.', 110, 55, 1, 10, 0, 'Johannisbeeren 200 g = 110 kcal; Wasser 1000 ml = 0 kcal; Minze einige Blätter (optional) = 0 kcal; Summe = 110 kcal'),
  (121, 'Gurkenwasser mit Zitrone', 'Getränke', 'Gurkenwasser mit Zitrone ist ein erfrischendes Getränk, das den Durst stillt und die Hydratation unterstützt. Gurke und Zitrone verleihen Frische und leichte Säure, während die Minze ein angenehmes Aroma hinzufügt. Perfekt für den ganzen Tag. Guten Appetit!', '[{"name":"Wasser","menge_anzeige":"500 ml","gramm":500},{"name":"Gurke","menge_anzeige":"1/2 Stück (ca. 150 g)","gramm":150},{"name":"Zitrone","menge_anzeige":"1/2 Stück (ca. 50 g)","gramm":50},{"name":"Minzblätter","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Gurke und Zitrone in dünne Scheiben schneiden. 2. Gurke und Zitrone in einen Krug oder ein Glas geben. 3. Mit Wasser auffüllen und gut umrühren. 4. Bei Bedarf Minzblätter für zusätzliches Aroma hinzufügen. 5. Das Getränk 10–15 Minuten im Kühlschrank ziehen lassen, bevor es serviert wird.', 1, '500 ml aromatisiertes Wasser werden üblicherweise als eine Portion (Krug/Flasche) über den Tag verteilt getrunken.', 33, 35, 1, 5, 0, 'Wasser 500 ml = 0 kcal; Gurke 150 g = 18 kcal; Zitrone 50 g = 15 kcal; Minzblätter nach Geschmack = 0 kcal; Summe = 33 kcal'),
  (122, 'Bananen-Hafermilchshake', 'Getränke', 'Der Bananen-Hafermilchshake ist ein nahrhaftes und leckeres Getränk, ideal zum Frühstück oder als Snack. Banane, Haferflocken und Milch liefern natürliche Süße, Ballaststoffe, Eiweiß und Kalzium. Einfach zuzubereiten und gesund. Guten Appetit!', '[{"name":"Milch (fettreduziert oder pflanzliche Milch)","menge_anzeige":"250 ml","gramm":250},{"name":"Banane","menge_anzeige":"1 Stück (ca. 120 g)","gramm":120},{"name":"Haferflocken","menge_anzeige":"2 EL (ca. 20 g)","gramm":20},{"name":"Honig","menge_anzeige":"1 TL (7 g)","gramm":7},{"name":"Eis","menge_anzeige":"nach Wunsch","gramm":null}]'::jsonb, '1. Milch, Banane, Haferflocken und Honig im Mixer zu einer glatten Masse verrühren. 2. Bei Bedarf Eis hinzufügen und erneut mixen. 3. Den Shake in ein Glas gießen und sofort servieren.', 1, 'Die Zutatenmengen (250 ml Milch, 1 Banane, 2 EL Haferflocken) ergeben einen typischen Frühstücksshake für 1 Person, was auch am nächsten am alten kcal-Wert liegt.', 325, 325, 12, 54, 6, 'Milch (1,5% Fett) 250 ml = 115 kcal; Banane 120 g = 114 kcal; Haferflocken 20 g = 74 kcal; Honig 7 g (1 TL) = 21 kcal; Eis nach Wunsch = 0 kcal; Summe = 325 kcal'),
  (123, 'Beeren-Smoothie mit Kefir', 'Getränke', 'Beeren-Smoothie mit Kefir ist ein nahrhaftes und erfrischendes Getränk für jede Tageszeit. Kefir liefert Eiweiß und Probiotika, während Beeren und Banane Vitamine und Süße hinzufügen. Perfekt als Snack oder zum Frühstück. Guten Appetit!', '[{"name":"Kefir","menge_anzeige":"200 ml","gramm":200},{"name":"Frische oder gefrorene Beeren (Himbeeren, Blaubeeren, Erdbeeren)","menge_anzeige":"100 g","gramm":100},{"name":"Banane","menge_anzeige":"1/2 Stück (ca. 60 g)","gramm":60},{"name":"Honig","menge_anzeige":"1 TL (7 g)","gramm":7}]'::jsonb, '1. Kefir, Beeren und Banane im Mixer zu einer glatten Masse verrühren. 2. Bei Bedarf Honig für zusätzliche Süße hinzufügen und alle Zutaten glatt mixen. 3. Sofort servieren.', 1, 'Die Zutatenmenge ergibt ein übliches Smoothie-Glas (ca. 350 ml) für 1 Portion.', 200, 200, 8, 33, 4, 'Kefir 200 ml = 82 kcal; Beeren 100 g = 40 kcal; Banane 60 g = 57 kcal; Honig 7 g (1 TL) = 21 kcal; Summe = 200 kcal'),
  (124, 'Frisch gepresster Orangensaft', 'Getränke', 'Frisch gepresster Orangensaft ist ein erfrischendes und vitaminreiches Getränk, das hilft, den Durst zu stillen und das Immunsystem zu unterstützen. Orangen sind reich an Vitamin C und anderen nützlichen Nährstoffen, was diesen Saft zu einer ausgezeichneten Wahl für die Gesundheit macht. Guten Appetit!', '[{"name":"Orangen","menge_anzeige":"3 Stück (ca. 130 g je Stück)","gramm":390}]'::jsonb, '1. Orangen halbieren. 2. Mit einer Zitruspresse den Saft aus den Orangen pressen. 3. Den frisch gepressten Saft in ein Glas gießen und sofort servieren.', 2, '3 gepresste Orangen ergeben ca. 300–350 ml Saft, was für 2 kleinere Gläser reicht und am nächsten am alten kcal-Wert liegt.', 183, 90, 2, 19, 0, 'Orangen 390 g (3 Stück à ca. 130 g) = 183 kcal; Summe = 183 kcal'),
  (125, 'Beeren-Smoothie mit Mandelmilch', 'Getränke', 'Beeren-Smoothie mit Mandelmilch ist ein nahrhaftes und erfrischendes Getränk für jede Tageszeit. Mandelmilch liefert gesunde Fette und Vitamine, während Beeren und Banane natürliche Süße und Antioxidantien hinzufügen. Perfekt als Snack oder zum Frühstück.', '[{"name":"Mandelmilch","menge_anzeige":"200 ml","gramm":200},{"name":"Frische oder gefrorene Beeren (Himbeeren, Blaubeeren, Erdbeeren)","menge_anzeige":"100 g","gramm":100},{"name":"Banane","menge_anzeige":"1/2 Stück (ca. 60 g)","gramm":60},{"name":"Honig","menge_anzeige":"1 TL (7 g)","gramm":7}]'::jsonb, '1. Mandelmilch, Beeren und Banane im Mixer zu einer glatten Masse verrühren. 2. Bei Bedarf Honig für zusätzliche Süße hinzufügen und alle Zutaten glatt mixen. 3. Sofort servieren.', 1, 'Die Gesamtkalorienzahl (ca. 152 kcal) entspricht fast genau dem alten kcal-Wert bei 1 Portion – einem üblichen Smoothie-Glas.', 152, 150, 3, 26, 3, 'Mandelmilch 200 ml = 34 kcal; Beeren 100 g = 40 kcal; Banane 60 g = 57 kcal; Honig 7 g (1 TL) = 21 kcal; Summe = 152 kcal'),
  (126, 'Erdbeer-Bananen-Smoothie', 'Getränke', 'Erdbeer-Bananen-Smoothie ist ein leckeres und erfrischendes Getränk, ideal zum Frühstück oder als Snack. Erdbeeren und Banane fügen natürliche Süße und Vitamine hinzu, Joghurt und Milch liefern Eiweiß und Kalzium. Einfach zuzubereiten und gesund. Guten Appetit!', '[{"name":"Erdbeeren (frisch oder gefroren)","menge_anzeige":"150 g","gramm":150},{"name":"Banane","menge_anzeige":"1 Stück (ca. 120 g)","gramm":120},{"name":"Joghurt (natur oder griechisch)","menge_anzeige":"100 ml","gramm":100},{"name":"Milch (fettreduziert oder pflanzlich)","menge_anzeige":"100 ml","gramm":100},{"name":"Honig","menge_anzeige":"1 TL (7 g)","gramm":7}]'::jsonb, '1. Erdbeeren, Banane, Joghurt und Milch im Mixer zu einer glatten Masse verrühren. 2. Bei Bedarf Honig für zusätzliche Süße hinzufügen und alle Zutaten glatt mixen. 3. Den Smoothie in ein Glas gießen und sofort servieren.', 2, 'Die große Zutatenmenge (ca. 470 g/ml) ergibt eher 2 mittlere Gläser; dieser Wert liegt zudem am nächsten am alten kcal-Wert.', 290, 145, 5, 24, 3, 'Erdbeeren 150 g = 48 kcal; Banane 120 g = 114 kcal; Joghurt 100 ml = 61 kcal; Milch (1,5% Fett) 100 ml = 46 kcal; Honig 7 g (1 TL) = 21 kcal; Summe = 290 kcal'),
  (127, 'Hagebuttentee mit Honig', 'Getränke', 'Hagebuttentee mit Honig ist ein wärmendes, gesundes Getränk, reich an Vitamin C und Antioxidantien. Hagebutten stärken das Immunsystem, Honig fügt natürliche Süße hinzu. Ideal für kalte Tage. Guten Appetit!', '[{"name":"Getrocknete Hagebutten","menge_anzeige":"2 EL (ca. 20 g)","gramm":20},{"name":"Wasser","menge_anzeige":"300 ml","gramm":300},{"name":"Honig","menge_anzeige":"1 TL (7 g)","gramm":7},{"name":"Zitrone","menge_anzeige":"1 Scheibe (ca. 5 g)","gramm":5}]'::jsonb, '1. Getrocknete Hagebutten unter kaltem Wasser abspülen. 2. Wasser aufkochen und über die Hagebutten in einer Teekanne oder Thermoskanne gießen. 3. 10–15 Minuten ziehen lassen. 4. Den Aufguss durch ein Sieb abseihen, um die Hagebutten zu entfernen. 5. Honig hinzufügen und gut umrühren. 6. Bei Bedarf eine Zitronenscheibe für zusätzlichen Geschmack und Aroma hinzufügen. 7. Heiß servieren.', 2, '300 ml Tee in einer Kanne ergeben ca. 2 Tassen; dieser Wert liegt zudem sehr nahe am alten kcal-Wert von 40 kcal.', 73, 35, 0, 9, 0, 'Getrocknete Hagebutten 20 g (2 EL) = 51 kcal; Wasser 300 ml = 0 kcal; Honig 7 g (1 TL) = 21 kcal; Zitrone 1 Scheibe (5 g) = 1 kcal; Summe = 73 kcal'),
  (128, 'Grüner Smoothie mit Kiwi und Spinat', 'Getränke', 'Grüner Smoothie mit Kiwi und Spinat ist ein erfrischendes und nahrhaftes Getränk, reich an Vitaminen und Antioxidantien. Kiwi fügt Süße und Vitamin C hinzu, Spinat liefert Eisen und Magnesium, und Banane sorgt für eine cremige Textur. Perfekt für Frühstück oder Snack.', '[{"name":"Kiwi","menge_anzeige":"2 Stück (ca. 70 g je Stück)","gramm":140},{"name":"Frischer Spinat","menge_anzeige":"1 Tasse (ca. 30 g)","gramm":30},{"name":"Banane","menge_anzeige":"1/2 Stück (ca. 60 g)","gramm":60},{"name":"Kokoswasser","menge_anzeige":"200 ml","gramm":200}]'::jsonb, '1. Kiwi und Banane schälen. 2. Kiwi, Spinat, Banane und Kokoswasser im Mixer zu einer glatten Masse verrühren. 3. Den Smoothie in ein Glas gießen und sofort servieren.', 1, 'Die Zutatenmenge ergibt ein großes Smoothie-Glas (ca. 430 ml) für 1 Portion, was auch am nächsten am alten kcal-Wert liegt.', 187, 185, 4, 35, 1, 'Kiwi 140 g (2 Stück) = 85 kcal; Frischer Spinat 30 g (1 Tasse) = 7 kcal; Banane 60 g = 57 kcal; Kokoswasser 200 ml = 38 kcal; Summe = 187 kcal'),
  (129, 'Hafermilch mit Zimt', 'Getränke', 'Hafermilch mit Zimt ist ein nahrhaftes, aromatisches Getränk, ideal für Veganer und als Kuhmilch-Alternative. Reich an Ballaststoffen und gesunden Kohlenhydraten, perfekt zum Frühstück oder als Snack.', '[{"name":"Haferflocken","menge_anzeige":"50 g","gramm":50},{"name":"Wasser","menge_anzeige":"500 ml","gramm":500},{"name":"Zimt","menge_anzeige":"1/2 TL (ca. 1 g)","gramm":1},{"name":"Honig oder Agavensirup","menge_anzeige":"1 TL (7 g)","gramm":7},{"name":"Vanilleextrakt","menge_anzeige":"1/2 TL (ca. 2 g)","gramm":2}]'::jsonb, '1. Haferflocken 30 Minuten in 500 ml Wasser einweichen. 2. Die Mischung in einen Mixer geben und zu einer glatten Masse mixen. 3. Hafermilch durch ein Käsetuch oder ein feines Sieb abseihen. 4. Zimt, Honig und Vanilleextrakt hinzufügen und gut umrühren. 5. Kalt servieren.', 3, 'Die Gesamtkalorienzahl geteilt durch 3 liegt am nächsten am alten kcal-Wert (80 kcal) und entspricht 3 kleineren Gläsern/Tassen Hafermilch.', 215, 70, 2, 12, 1, 'Haferflocken 50 g = 186 kcal; Wasser 500 ml = 0 kcal; Zimt 1 g (1/2 TL) = 2 kcal; Honig oder Agavensirup 7 g (1 TL) = 21 kcal; Vanilleextrakt 2 g (1/2 TL) = 5 kcal; Summe = 215 kcal'),
  (130, 'Bananen-Spinat-Smoothie', 'Getränke', 'Bananen-Spinat-Smoothie ist ein nahrhaftes grünes Getränk aus Banane, Spinat und Mandelmilch – ideal als Frühstück oder Snack.', '[{"name":"Banane","menge_anzeige":"1 Stück (ca. 120 g)","gramm":120},{"name":"Frischer Spinat","menge_anzeige":"1 Tasse (ca. 30 g)","gramm":30},{"name":"Mandelmilch","menge_anzeige":"200 ml","gramm":200},{"name":"Honig","menge_anzeige":"1 TL (7 g)","gramm":7},{"name":"Eis","menge_anzeige":"nach Wunsch","gramm":null}]'::jsonb, '1. Banane, Spinat und Mandelmilch im Mixer zu einer glatten Masse verrühren. 2. Bei Bedarf Honig für zusätzliche Süße hinzufügen und alle Zutaten glatt mixen. 3. Bei Bedarf Eis hinzufügen und erneut mixen. 4. Den Smoothie in ein Glas gießen und sofort servieren.', 1, 'Die Zutatenmenge ergibt ein übliches Smoothie-Glas (ca. 350 ml) für 1 Portion, was auch am nächsten am alten kcal-Wert liegt.', 176, 175, 3, 31, 3, 'Banane 120 g = 114 kcal; Frischer Spinat 30 g (1 Tasse) = 7 kcal; Mandelmilch 200 ml = 34 kcal; Honig 7 g (1 TL) = 21 kcal; Eis nach Wunsch = 0 kcal; Summe = 176 kcal'),
  (131, 'Matcha Latte', 'Getränke', 'Matcha-Latte ist ein belebendes Getränk mit antioxidativem Matcha und cremiger Mandelmilch. Ideal für einen Energieschub am Morgen oder als Nachmittagssnack. Einfach zuzubereiten.', '[{"name":"Matcha-Pulver","menge_anzeige":"1 TL","gramm":2},{"name":"Wasser","menge_anzeige":"50 ml","gramm":50},{"name":"Mandelmilch (oder andere pflanzliche Milch)","menge_anzeige":"200 ml","gramm":200},{"name":"Honig oder Agavensirup","menge_anzeige":"1 TL","gramm":7}]'::jsonb, '1. Matcha-Pulver in einer kleinen Schüssel mit heißem, aber nicht kochendem Wasser glattrühren.
2. Mandelmilch erwärmen, ohne sie zum Kochen zu bringen.
3. Matcha mit der warmen Milch verrühren und nach Geschmack Honig oder Agavensirup hinzufügen.
4. Das Getränk in eine Tasse gießen und heiß servieren.', 1, 'Die Menge (ca. 250 ml) ergibt ein Glas als Einzelportion, was auch am nächsten am alten kcal-Wert liegt.', 76, 75, 2, 12, 3, 'Matcha-Pulver 2 g = 6,5 kcal; Wasser 50 g = 0 kcal; Mandelmilch 200 g = 48,0 kcal; Honig 7 g = 21,3 kcal; Summe = 75,8 kcal ≈ 76 kcal'),
  (132, 'Goldene Milch', 'Getränke', 'Goldene Milch ist ein aromatisches und gesundes Getränk, das das Immunsystem stärkt und Entzündungen dank Kurkuma und Ingwer reduziert. Der sanfte Geschmack mit Zimt- und Kokosnoten macht es ideal zum Entspannen am Abend.', '[{"name":"Kokosmilch (oder Mandelmilch)","menge_anzeige":"250 ml","gramm":250},{"name":"Kurkuma","menge_anzeige":"1/2 TL","gramm":1.5},{"name":"Ingwer (gemahlen)","menge_anzeige":"1/4 TL","gramm":0.75},{"name":"Zimt","menge_anzeige":"1/4 TL","gramm":0.75},{"name":"Honig oder Agavensirup","menge_anzeige":"1 TL (optional)","gramm":7},{"name":"Schwarzer Pfeffer (für bessere Kurkuma-Aufnahme)","menge_anzeige":"1 Prise","gramm":0.3}]'::jsonb, '1. Alle Zutaten in einem kleinen Topf gut verrühren.
2. Bei mittlerer Hitze erwärmen, aber nicht zum Kochen bringen.
3. Das Getränk in eine Tasse gießen und heiß servieren.', 1, 'Die Menge (250 ml) entspricht einer üblichen Tassenportion Goldene Milch.', 107, 105, 1, 16, 5, 'Kokosmilch (leichtes Kokosgetränk) 250 g = 75,0 kcal; Kurkuma 1,5 g = 5,3 kcal; Ingwer gemahlen 0,75 g = 2,6 kcal; Zimt 0,75 g = 1,9 kcal; Honig 7 g = 21,3 kcal; Schwarzer Pfeffer 0,3 g = 0,8 kcal; Summe = 106,8 kcal ≈ 107 kcal'),
  (133, 'Rote-Bete-Saft mit Apfel und Karotte', 'Getränke', 'Rote-Bete-Saft mit Apfel und Karotte ist ein nahrhaftes und vitaminreiches Getränk, das die Durchblutung verbessert und Energie liefert. Rote Bete ist reich an Eisen und Antioxidantien, Apfel fügt Süße hinzu und Karotte liefert Carotinoide. Dieser Saft ist ideal für einen Energieschub am Morgen.', '[{"name":"Rote Bete","menge_anzeige":"1 Stück","gramm":150},{"name":"Apfel (mittelgroß)","menge_anzeige":"1 Stück","gramm":150},{"name":"Karotte","menge_anzeige":"1 Stück","gramm":80},{"name":"Zitronensaft","menge_anzeige":"1 EL","gramm":15}]'::jsonb, '1. Rote Bete, Apfel und Karotte schälen und in kleine Stücke schneiden.
2. Alle Zutaten durch einen Entsafter geben.
3. Zitronensaft hinzufügen und gut umrühren.
4. Sofort servieren.', 2, 'Die Saftmenge aus einer ganzen Rote Bete, einem Apfel und einer Karotte reicht für zwei Gläser; 178,6 kcal ÷ 2 ≈ 89 kcal liegt zudem näher am alten kcal-Wert als eine einzelne Portion.', 179, 90, 2, 22, 0, 'Rote Bete 150 g = 64,5 kcal; Apfel 150 g = 78,0 kcal; Karotte 80 g = 32,8 kcal; Zitronensaft 15 g = 3,3 kcal; Summe = 178,6 kcal ≈ 179 kcal; ÷2 Portionen = 89,3 kcal'),
  (134, 'Smoothie mit Erdbeeren und Orange', 'Getränke', 'Smoothie mit Erdbeeren und Orange ist ein helles und erfrischendes Getränk, reich an Vitamin C und Antioxidantien. Joghurt fügt eine cremige Textur und gesunde Probiotika hinzu. Dieser Smoothie ist ideal für ein Frühstück oder einen Nachmittagssnack.', '[{"name":"Erdbeeren (frisch oder gefroren)","menge_anzeige":"150 g","gramm":150},{"name":"Orangensaft (frisch gepresst)","menge_anzeige":"200 ml","gramm":200},{"name":"Joghurt (natur oder griechisch)","menge_anzeige":"100 ml","gramm":100},{"name":"Honig","menge_anzeige":"1 TL","gramm":7}]'::jsonb, '1. Erdbeeren, Orangensaft und Joghurt im Mixer zu einer glatten Masse verrühren.
2. Bei Bedarf Honig für zusätzliche Süße hinzufügen.
3. Alles glatt mixen.
4. Den Smoothie in ein Glas gießen und sofort servieren.', 1, 'Die Menge (ca. 450 ml) ergibt ein großes Smoothie-Glas als Einzelportion.', 221, 220, 6, 43, 4, 'Erdbeeren 150 g = 48,0 kcal; Orangensaft 200 g = 90,0 kcal; Joghurt 100 g = 62,0 kcal; Honig 7 g = 21,3 kcal; Summe = 221,3 kcal ≈ 221 kcal'),
  (135, 'Kefir-Smoothie mit Gurke und Dill', 'Getränke', 'Kefir-Smoothie mit Gurke und Dill ist ein leichtes und erfrischendes Getränk, ideal für einen Sommertag. Kefir liefert Probiotika, während Gurke und Dill Vitamine und Mineralien hinzufügen, was diesen Smoothie zu einem ausgezeichneten Drink macht.', '[{"name":"Kefir","menge_anzeige":"200 ml","gramm":200},{"name":"Gurke","menge_anzeige":"1 Stück","gramm":100},{"name":"Dill","menge_anzeige":"1 EL","gramm":3},{"name":"Salz und Pfeffer","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Gurke schälen und in kleine Stücke schneiden.
2. Kefir, Gurke und Dill im Mixer zu einer glatten Masse verrühren.
3. Mit Salz und Pfeffer nach Geschmack würzen.
4. Kalt servieren.', 1, 'Die Menge (ca. 300 ml) entspricht einem Glas als Einzelportion; der alte kcal-Wert wirkt zu niedrig angesetzt.', 95, 95, 7, 10, 3, 'Kefir 200 g = 82,0 kcal; Gurke 100 g = 12,0 kcal; Dill 3 g = 1,3 kcal; Salz und Pfeffer nach Geschmack = 0 kcal; Summe = 95,3 kcal ≈ 95 kcal'),
  (136, 'Hibiskustee (Karkade)', 'Getränke', 'Hibiskustee (Karkade) ist ein leuchtendes und erfrischendes Getränk, reich an Antioxidantien und Vitamin C. Sein intensives Aroma und Geschmack machen ihn zu einer idealen Wahl, um den Durst zu jeder Jahreszeit zu stillen.', '[{"name":"Getrocknete Hibiskusblüten","menge_anzeige":"1 EL","gramm":5},{"name":"Wasser","menge_anzeige":"250 ml","gramm":250},{"name":"Honig","menge_anzeige":"1 TL","gramm":7},{"name":"Zitrone (optional)","menge_anzeige":"1 Scheibe","gramm":5}]'::jsonb, '1. Wasser aufkochen und über die getrockneten Hibiskusblüten gießen.
2. 5–10 Minuten ziehen lassen.
3. Den Tee durch ein Sieb abseihen und nach Geschmack Honig und Zitrone hinzufügen.
4. Heiß oder gekühlt servieren.', 1, 'Die Menge (250 ml) ergibt eine Tasse Tee als Einzelportion.', 22, 20, 0, 6, 0, 'Getrocknete Hibiskusblüten 5 g (aufgebrüht und abgeseiht) = 0 kcal; Wasser 250 g = 0 kcal; Honig 7 g = 21,3 kcal; Zitrone (Scheibe, Saftanteil) 5 g = 1,1 kcal; Summe = 22,4 kcal ≈ 22 kcal'),
  (137, 'Zitronen-Ingwer-Getränk', 'Getränke', 'Zitronen-Ingwer-Getränk ist ein wärmendes und gesundes Getränk, das das Immunsystem stärkt und die Verdauung verbessert. Ingwer hat entzündungshemmende Eigenschaften, während Zitrone Vitamin C liefert. Honig fügt natürliche Süße und beruhigende Wirkung hinzu.', '[{"name":"Wasser","menge_anzeige":"300 ml","gramm":300},{"name":"Frischer Ingwer","menge_anzeige":"2 cm Wurzel","gramm":10},{"name":"Zitrone","menge_anzeige":"1/2 Stück","gramm":30},{"name":"Honig","menge_anzeige":"1 TL","gramm":7}]'::jsonb, '1. Wasser aufkochen.
2. Ingwer in dünne Scheiben schneiden und ins heiße Wasser geben.
3. 5–10 Minuten ziehen lassen.
4. Zitronensaft und Honig hinzufügen und gut umrühren.
5. Heiß servieren.', 1, 'Die Menge (300 ml) entspricht einer großen Tasse als Einzelportion, nahe am alten kcal-Wert.', 36, 35, 0, 10, 0, 'Wasser 300 g = 0 kcal; Frischer Ingwer 10 g = 8,0 kcal; Zitronensaft (1/2 Stück) 30 g = 6,6 kcal; Honig 7 g = 21,3 kcal; Summe = 35,9 kcal ≈ 36 kcal'),
  (138, 'Hüttenkäse-Mousse mit Beeren', 'Desserts', 'Hüttenkäse-Mousse mit Beeren ist ein cremiges, eiweißreiches Dessert aus Hüttenkäse, griechischem Joghurt und frischen Beeren. Schnell zubereitet und ideal als proteinreicher Snack oder leichtes Dessert.', '[{"name":"Hüttenkäse (fettarm)","menge_anzeige":"100 g","gramm":100},{"name":"Griechischer Joghurt","menge_anzeige":"50 g","gramm":50},{"name":"Honig oder Agavensirup","menge_anzeige":"1 EL","gramm":20},{"name":"Vanilleextrakt","menge_anzeige":"1/2 TL","gramm":2.5},{"name":"Beeren (Erdbeeren, Blaubeeren, Himbeeren; frisch oder gefroren)","menge_anzeige":"100 g","gramm":100},{"name":"Minzblätter zum Garnieren (optional)","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Hüttenkäse, griechischen Joghurt, Honig und Vanilleextrakt in einer Schüssel vermischen und gut verrühren, bis die Masse glatt und luftig ist.
2. Die Hüttenkäse-Mousse in ein Glas oder eine Schüssel geben.
3. Mit Beeren toppen.
4. Optional mit ein paar frischen Minzblättern garnieren.
5. Sofort servieren oder vor dem Servieren im Kühlschrank kühlen.', 1, 'Die Menge (ca. 250 g Mousse) ergibt eine großzügige Einzelportion, am nächsten am alten kcal-Wert.', 247, 245, 17, 31, 5, 'Hüttenkäse fettarm 100 g = 90,0 kcal; Griechischer Joghurt 50 g = 48,5 kcal; Honig 20 g = 60,8 kcal; Vanilleextrakt 2,5 g = 7,2 kcal; Beeren 100 g = 40,0 kcal; Summe = 246,5 kcal ≈ 247 kcal'),
  (139, 'Schokoladenpudding mit Avocado', 'Desserts', 'Schokoladenpudding mit Avocado ist ein köstliches, nahrhaftes Dessert mit cremiger Textur und reichhaltigem Schokoladengeschmack. Avocado liefert gesunde Fette, Kakao Antioxidantien. Einfach zuzubereiten, perfekt als gesunder Snack oder Dessert.', '[{"name":"Reife Avocado","menge_anzeige":"1 Stück","gramm":150},{"name":"Ungesüßtes Kakaopulver","menge_anzeige":"2 EL","gramm":10},{"name":"Honig oder Agavensirup","menge_anzeige":"1-2 EL","gramm":30},{"name":"Vanilleextrakt","menge_anzeige":"1/2 TL","gramm":2.5},{"name":"Kokosmilch (oder andere pflanzliche Milch)","menge_anzeige":"2-3 EL","gramm":37.5},{"name":"Salz","menge_anzeige":"1 Prise (optional)","gramm":null},{"name":"Frische Beeren oder Minze zum Garnieren","menge_anzeige":"optional","gramm":null}]'::jsonb, '1. Die Avocado halbieren, den Kern entfernen und das Fruchtfleisch herauslöffeln.
2. Im Mixer Avocado-Fruchtfleisch, Kakaopulver, Honig oder Agavensirup, Vanilleextrakt, Kokosmilch und eine Prise Salz vermischen und glatt und cremig mixen.
3. Den Pudding abschmecken und bei Bedarf mehr Honig oder Agavensirup für zusätzliche Süße hinzufügen.
4. Den Pudding in ein Glas oder eine Schüssel füllen.
5. Nach Wunsch mit frischen Beeren oder Minze garnieren.
6. Sofort servieren oder vor dem Servieren im Kühlschrank kühlen.', 2, 'Eine ganze Avocado ergibt einen recht üppigen Pudding; aufgeteilt auf 2 Portionen (≈218 kcal) liegt der Wert nahe am alten kcal-Wert und im Dessert-Richtwert.', 436, 220, 3, 20, 16, 'Avocado 150 g = 240,0 kcal; Kakaopulver 10 g = 22,8 kcal; Honig 30 g = 91,2 kcal; Vanilleextrakt 2,5 g = 7,2 kcal; Kokosmilch 37,5 g = 75,0 kcal; Summe = 436,2 kcal ≈ 436 kcal; ÷2 Portionen = 218,1 kcal'),
  (140, 'Gebackene Äpfel mit Honig und Nüssen', 'Desserts', 'Gebackene Äpfel mit Honig und Nüssen sind ein duftendes, gesundes Dessert mit zartem Apfel und knusprigen Nüssen. Honig und Zimt fügen Süße und Wärme hinzu, perfekt für Herbst und Winter. Einfach zuzubereiten und ideal für Gesundheitsbewusste.', '[{"name":"Apfel","menge_anzeige":"1 Stück","gramm":150},{"name":"Honig","menge_anzeige":"1 EL (21 g)","gramm":21},{"name":"Walnüsse (oder Mandeln)","menge_anzeige":"2 EL","gramm":20},{"name":"Zimt","menge_anzeige":"1/2 TL","gramm":1.5},{"name":"Rosinen","menge_anzeige":"1 EL","gramm":10},{"name":"Butter","menge_anzeige":"1/2 TL","gramm":2}]'::jsonb, '1. Den Ofen auf 180 °C vorheizen.
2. Den Apfel waschen und das Kerngehäuse entfernen, dabei den Boden intakt lassen, sodass eine „Tasse" entsteht.
3. In einer kleinen Schüssel Honig, gehackte Nüsse, Zimt und Rosinen vermischen.
4. Den Apfel mit der Honig-Nuss-Mischung füllen.
5. Falls gewünscht, ein kleines Stück Butter auf die Füllung legen.
6. Den Apfel in eine Auflaufform setzen.
7. Im vorgeheizten Ofen etwa 20–25 Minuten backen, bis der Apfel weich ist.
8. Aus dem Ofen nehmen und leicht abkühlen lassen, bevor er serviert wird.', 1, 'Ein ganzer, gefüllter Apfel ist als klassisches Rezept eine Einzelportion; die alte kcal-Angabe war offenbar zu niedrig geschätzt.', 321, 320, 4, 49, 15, 'Apfel 150 g = 78,0 kcal; Honig 21 g = 63,8 kcal; Walnüsse 20 g = 130,8 kcal; Zimt 1,5 g = 3,7 kcal; Rosinen 10 g = 29,9 kcal; Butter 2 g = 14,3 kcal; Summe = 320,6 kcal ≈ 321 kcal'),
  (141, 'Bananenmuffins ohne Mehl', 'Desserts', 'Mehlfreie Bananenmuffins sind ein leckeres und gesundes Dessert, perfekt zum Frühstück oder als Snack. Bananen und Honig geben den Muffins natürliche Süße, und Haferflocken liefern Ballaststoffe. Diese Muffins sind einfach zuzubereiten und eine tolle Ergänzung für Ihre Ernährung. Guten Appetit!', '[{"name":"Bananen","menge_anzeige":"2 Stück","gramm":240},{"name":"Eier","menge_anzeige":"2 Stück","gramm":110},{"name":"Haferflocken","menge_anzeige":"100 g","gramm":100},{"name":"Honig","menge_anzeige":"2 EL","gramm":40},{"name":"Backpulver","menge_anzeige":"1 TL","gramm":5}]'::jsonb, '1. Den Ofen auf 180 °C vorheizen.
2. Bananen, Eier, Haferflocken, Honig und Backpulver im Mixer zu einer glatten Masse mixen.
3. Den Teig in Muffinförmchen füllen.
4. 15–20 Minuten backen, bis die Muffins goldbraun sind.
5. Die Muffins leicht abkühlen lassen, bevor sie serviert werden.', 6, '2 Bananen, 2 Eier, 100 g Haferflocken und Honig ergeben typischerweise ein Set von 6 Muffins; 877,7 kcal ÷ 6 ≈ 146 kcal liegt sehr nah am alten Wert von 140 kcal.', 878, 145, 5, 25, 3, 'Bananen 240 g = 213,6 kcal; Eier 110 g = 170,5 kcal; Haferflocken 100 g = 372,0 kcal; Honig 40 g = 121,6 kcal; Backpulver 5 g = 0 kcal; Summe = 877,7 kcal; ÷6 Muffins = 146,3 kcal'),
  (142, 'Joghurtkuchen mit Früchten', 'Desserts', 'Joghurtkuchen mit Früchten ist ein leichtes, erfrischendes Dessert, das zarten Joghurt und frische Früchte kombiniert. Der Hafer-Nuss-Boden sorgt für Knusprigkeit, und Honig verleiht natürliche Süße. Gesund durch hohen Proteingehalt und Vitamine. Guten Appetit!', '[{"name":"Griechischer Joghurt","menge_anzeige":"500 g","gramm":500},{"name":"Honig","menge_anzeige":"3 EL","gramm":60},{"name":"Gelatine","menge_anzeige":"15 g","gramm":15},{"name":"Wasser (zum Einweichen der Gelatine)","menge_anzeige":"50 ml","gramm":50},{"name":"Lieblingsfrüchte (Beeren, Kiwi, Banane, Mango)","menge_anzeige":"300 g","gramm":300},{"name":"Haferflocken","menge_anzeige":"100 g","gramm":100},{"name":"Nüsse (Mandeln, Walnüsse)","menge_anzeige":"50 g","gramm":50},{"name":"Kokosöl","menge_anzeige":"2 EL","gramm":20}]'::jsonb, '1. Die Gelatine in einer kleinen Schüssel im Wasser einweichen und 10 Minuten quellen lassen.
2. Griechischen Joghurt mit Honig glattrühren.
3. Die gequollene Gelatine im Wasserbad oder in der Mikrowelle schmelzen, aber nicht kochen lassen, und in die Joghurtmischung einrühren.
4. Haferflocken und Nüsse im Mixer zu Krümeln mahlen.
5. Das Kokosöl schmelzen und mit den Hafer-Nuss-Krümeln vermischen.
6. Die Mischung auf den Boden einer Kuchenform verteilen, festdrücken und 15–20 Minuten im Kühlschrank kühlen.
7. Die Joghurtmischung über den vorbereiteten Boden gießen und glattstreichen.
8. Die Früchte schneiden und den Kuchen damit dekorieren.
9. Den Kuchen mindestens 4 Stunden, vorzugsweise über Nacht, im Kühlschrank fest werden lassen.
10. Vor dem Servieren den Kuchen vorsichtig aus der Form lösen.', 8, 'Ein ganzer Kuchen aus 500 g Joghurt mit Hafer-Nuss-Boden wird üblicherweise in 8 Stücke geschnitten; 1671,6 kcal ÷ 8 ≈ 209 kcal liegt am nächsten am alten Wert von 180 kcal innerhalb des zulässigen Bereichs 1–8.', 1672, 210, 10, 21, 10, 'Griechischer Joghurt 500 g = 485,0 kcal; Honig 60 g = 182,4 kcal; Gelatine 15 g = 50,2 kcal; Früchte 300 g = 120,0 kcal; Haferflocken 100 g = 372,0 kcal; Nüsse 50 g = 289,5 kcal; Kokosöl 20 g = 172,4 kcal; Wasser 50 g = 0 kcal; Summe = 1671,6 kcal; ÷8 Stücke = 208,95 kcal'),
  (143, 'Karottenkuchen ohne Zucker', 'Desserts', 'Zuckerfreier Karottenkuchen ist ein leckeres, gesundes Dessert, ideal für Ernährungsbewusste. Karotten bringen Feuchtigkeit und Süße, Haferflocken und Nüsse liefern Ballaststoffe und gesunde Fette. Einfach zuzubereiten und perfekt für Ihre Ernährung.', '[{"name":"Geriebene Karotten","menge_anzeige":"300 g","gramm":300},{"name":"Eier","menge_anzeige":"3 Stück","gramm":165},{"name":"Haferflocken","menge_anzeige":"150 g","gramm":150},{"name":"Honig","menge_anzeige":"3 EL","gramm":60},{"name":"Zimt","menge_anzeige":"1 TL","gramm":2.5},{"name":"Backpulver","menge_anzeige":"1 TL","gramm":5},{"name":"Pflanzenöl","menge_anzeige":"2 EL","gramm":20},{"name":"Nüsse (Walnüsse oder Mandeln, gehackt)","menge_anzeige":"50 g","gramm":50},{"name":"Vanilleextrakt","menge_anzeige":"1 TL","gramm":5},{"name":"Salz","menge_anzeige":"1 Prise","gramm":1}]'::jsonb, '1. Den Ofen auf 180 °C vorheizen und eine Backform einfetten oder mit Backpapier auslegen.
2. Haferflocken im Mixer zu Mehl mahlen.
3. In einer großen Schüssel Eier mit Honig und Pflanzenöl glattrühren.
4. Vanilleextrakt und eine Prise Salz hinzufügen und gut mischen.
5. Nach und nach Hafermehl, Backpulver und Zimt unter Rühren hinzufügen.
6. Geriebene Karotten und gehackte Nüsse unter den Teig heben.
7. Den Teig in die vorbereitete Backform gießen und die Oberfläche glattstreichen.
8. Im vorgeheizten Ofen 35–40 Minuten backen, bis ein Zahnstocher in der Mitte sauber herauskommt.
9. Den Kuchen in der Form abkühlen lassen, dann herausnehmen und in Portionen schneiden.', 8, 'Ein klassischer Karottenkuchen aus dieser Zutatenmenge wird typischerweise in 8 Stücke geschnitten; 1643,5 kcal ÷ 8 ≈ 205 kcal liegt am nächsten am alten Wert von 180 kcal innerhalb des zulässigen Bereichs 1–8.', 1644, 205, 6, 23, 10, 'Geriebene Karotten 300 g = 123,0 kcal; Eier 165 g = 255,8 kcal; Haferflocken 150 g = 558,0 kcal; Honig 60 g = 182,4 kcal; Zimt 2,5 g = 6,2 kcal; Backpulver 5 g = 0 kcal; Pflanzenöl 20 g = 176,8 kcal; Nüsse 50 g = 327,0 kcal; Vanilleextrakt 5 g = 14,4 kcal; Salz 1 g = 0 kcal; Summe = 1643,5 kcal; ÷8 Stücke = 205,4 kcal'),
  (144, 'Mangosorbet', 'Desserts', 'Mango-Sorbet ist ein erfrischendes, natürliches Dessert, ideal für heiße Sommertage. Die Süße der Mango und die Säure des Zitronensafts sorgen für einen einzigartigen Geschmack. Ohne Milchprodukte und Zucker ist es leicht und gesund. Einfach zuzubereiten, perfekt als Abschluss jeder Mahlzeit.', '[{"name":"Reife Mangos","menge_anzeige":"2 Stück (ca. 400 g Fruchtfleisch)","gramm":400},{"name":"Zitronensaft","menge_anzeige":"1 EL (15 ml)","gramm":15},{"name":"Honig oder Agavensirup","menge_anzeige":"2 EL (40 g)","gramm":40},{"name":"Wasser","menge_anzeige":"100 ml","gramm":100}]'::jsonb, '1. Mangos schälen, den Kern entfernen und das Fruchtfleisch in Stücke schneiden. 2. Mangostücke in einen Mixer geben und Zitronensaft, Honig oder Agavensirup und Wasser hinzufügen. 3. Alles zu einer glatten Masse pürieren. 4. Die Mischung in einen Gefrierbehälter gießen und für 1-2 Stunden in den Gefrierschrank stellen. 5. Nach 1-2 Stunden den Behälter aus dem Gefrierschrank nehmen und die Mischung erneut mixen, um große Eiskristalle zu vermeiden. 6. Die Mischung zurück in den Behälter gießen und weitere 3-4 Stunden einfrieren, bis sie vollständig fest ist. 7. Vor dem Servieren das Sorbet 5-10 Minuten bei Raumtemperatur weich werden lassen.', 4, '365 kcal gesamt ÷ 4 ergibt 91 kcal/Portion, sehr nah am alten Wert (90 kcal) — 4 Portionen sind für ein Sorbet aus 2 Mangos realistisch.', 365, 90, 1, 23, 0, 'Mango 400 g = 240 kcal; Zitronensaft 15 ml = 4 kcal; Honig 40 g = 122 kcal; Wasser 100 ml = 0 kcal; Summe = 365 kcal (÷4 Portionen ≈ 91 kcal/Portion)'),
  (145, 'Käsekuchen mit Nussboden', 'Desserts', 'Käsekuchen mit Nussboden ist ein köstliches, nahrhaftes Dessert, das die cremige Käsefüllung mit knusprigem Nussboden kombiniert. Reich an Eiweiß und gesunden Fetten, ideal für Gesundheitsbewusste. Einfach zuzubereiten und ein eleganter Abschluss jeder Mahlzeit.', '[{"name":"Mandeln oder Walnüsse (für den Boden)","menge_anzeige":"150 g","gramm":150},{"name":"Datteln (entsteint)","menge_anzeige":"100 g","gramm":100},{"name":"Kokosöl","menge_anzeige":"2 EL (20 g)","gramm":20},{"name":"Frischkäse (z. B. Philadelphia)","menge_anzeige":"400 g","gramm":400},{"name":"Griechischer Joghurt","menge_anzeige":"200 g","gramm":200},{"name":"Honig oder Agavensirup","menge_anzeige":"3 EL (60 g)","gramm":60},{"name":"Vanilleextrakt","menge_anzeige":"1 TL (5 g)","gramm":5},{"name":"Zitronensaft","menge_anzeige":"1 EL (15 ml)","gramm":15},{"name":"Gelatine","menge_anzeige":"15 g","gramm":15},{"name":"Wasser","menge_anzeige":"50 ml","gramm":50}]'::jsonb, '1. Boden vorbereiten: Nüsse und Datteln im Mixer mahlen. 2. Geschmolzenes Kokosöl hinzufügen und glatt rühren. 3. Die Mischung in eine Kuchenform geben, gleichmäßig andrücken und 20 Minuten im Kühlschrank kühlen. 4. Füllung vorbereiten: Gelatine in einer kleinen Schüssel im Wasser einweichen und 10 Minuten quellen lassen. 5. Frischkäse, griechischen Joghurt, Honig, Vanilleextrakt und Zitronensaft glatt und cremig schlagen. 6. Die gequollene Gelatine im Wasserbad oder in der Mikrowelle schmelzen, aber nicht kochen lassen. 7. Die geschmolzene Gelatine zur Käsemischung geben und gut verrühren. 8. Käsekuchen zusammensetzen: Die Käsemischung auf den Nussboden gießen und die Oberfläche glatt streichen. 9. Den Käsekuchen mindestens 4 Stunden, vorzugsweise über Nacht, im Kühlschrank fest werden lassen. 10. Servieren: Vor dem Servieren den Käsekuchen aus der Form nehmen und in Portionen schneiden. Nach Wunsch mit frischen Beeren, Minze oder geriebener Schokolade garnieren.', 8, 'Ein Käsekuchen von ca. 1 kg Gesamtmasse (Nussboden, Frischkäse-Füllung) wird typischerweise in 8 Stücke geschnitten; das ergibt eine realistische Portionsgröße von ca. 125 g.', 2785, 350, 10, 22, 26, 'Mandeln/Walnüsse 150 g = 869 kcal; Datteln 100 g = 282 kcal; Kokosöl 20 g = 172 kcal; Frischkäse 400 g = 984 kcal; Griechischer Joghurt 200 g = 230 kcal; Honig 60 g = 182 kcal; Vanilleextrakt 5 g = 12 kcal; Zitronensaft 15 ml = 4 kcal; Gelatine 15 g = 50 kcal; Wasser 50 ml = 0 kcal; Summe = 2785 kcal (÷8 Portionen ≈ 348 kcal/Portion)'),
  (146, 'Kokoskugeln', 'Desserts', 'Kokoskugeln sind ein einfaches, leckeres Dessert mit zarter Textur und reichhaltigem Kokosgeschmack. Nüsse und Schokolade sorgen für Abwechslung. Perfekt für Feiertage oder als Leckerei zum Tee. Guten Appetit!', '[{"name":"Kokosraspeln","menge_anzeige":"200 g","gramm":200},{"name":"Kondensmilch","menge_anzeige":"200 ml","gramm":200},{"name":"Mandeln (oder andere Nüsse)","menge_anzeige":"50 g","gramm":50},{"name":"Vanilleextrakt (optional)","menge_anzeige":"1 TL (5 g)","gramm":5},{"name":"Kakaopulver oder Schokoladenglasur zum Überziehen (optional)","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. In einer großen Schüssel Kokosraspeln und Kondensmilch glatt rühren. 2. Optional Vanilleextrakt für den Geschmack hinzufügen. 3. Aus der Kokosmasse kleine Kugeln formen. 4. Falls Mandeln verwendet werden, eine Nuss in die Mitte jeder Kugel legen. 5. Die Kugeln auf ein mit Backpapier ausgelegtes Backblech oder einen Teller legen. 6. Die Kugeln mindestens 1 Stunde im Kühlschrank fest werden lassen. 7. Nach Wunsch die Kugeln in Kakaopulver wälzen oder mit Schokoladenglasur überziehen. Dazu die Schokolade im Wasserbad schmelzen und jede Kugel darin eintauchen, dann die Schokolade fest werden lassen. 8. Gekühlt servieren.', 8, 'Die Masse (ca. 450 g Kokos-Mandel-Mischung) ergibt ca. 30 kleine Kugeln; bei 8 Portionen (je ca. 3-4 Kugeln) liegt der Wert mit 236 kcal im für Snacks/Desserts üblichen Bereich (100-350 kcal); der alte Wert (100 kcal) wäre nur bei Einzelkugeln erreichbar.', 1890, 235, 5, 6, 21, 'Kokosraspeln 200 g = 1320 kcal; Kondensmilch 200 ml = 268 kcal; Mandeln 50 g = 290 kcal; Vanilleextrakt 5 g = 12 kcal; Kakaopulver/Schokoladenglasur (optional, nach Geschmack, nicht mitgerechnet); Summe = 1890 kcal (÷8 Portionen ≈ 236 kcal/Portion)'),
  (147, 'Fruchtgelee ohne Zucker', 'Desserts', 'Zuckerfreies Fruchtgelee ist ein leichtes, erfrischendes Dessert für Diätbewusste. Früchte und Beeren fügen natürliche Süße und Vitamine hinzu, und natürlicher Saft macht es perfekt für jede Jahreszeit. Einfach zuzubereiten, gesund und lecker. Guten Appetit!', '[{"name":"Früchte oder Beeren (z. B. Erdbeeren, Himbeeren, Blaubeeren, Kiwi)","menge_anzeige":"300 g","gramm":300},{"name":"Natürlicher Saft (Apfel, Orange oder jeder andere ohne Zucker)","menge_anzeige":"500 ml","gramm":500},{"name":"Gelatine","menge_anzeige":"15 g","gramm":15},{"name":"Wasser (zum Einweichen der Gelatine)","menge_anzeige":"50 ml","gramm":50},{"name":"Minzblätter zum Garnieren (optional)","menge_anzeige":"nach Geschmack","gramm":null}]'::jsonb, '1. Gelatine in einer kleinen Schüssel im Wasser einweichen und 10 Minuten quellen lassen. 2. Die Früchte oder Beeren in kleine Stücke schneiden. 3. Den Saft in einem Topf erhitzen, aber nicht zum Kochen bringen. 4. Die gequollene Gelatine zum heißen Saft geben und gründlich umrühren, bis sie sich vollständig aufgelöst hat. 5. Die geschnittenen Früchte oder Beeren in Geleeformen oder eine große Form geben. 6. Den Saft mit der aufgelösten Gelatine über die Früchte oder Beeren gießen. 7. Das Gelee auf Raumtemperatur abkühlen lassen und dann mehrere Stunden im Kühlschrank fest werden lassen. 8. Vor dem Servieren nach Wunsch mit Minzblättern garnieren.', 4, '300 g Früchte plus 500 ml Saft ergeben ca. 850 ml Geleemasse, realistisch auf 4 Dessertförmchen verteilt; bei 104 kcal/Portion liegt der Wert im Rahmen für ein leichtes Dessert. Der alte Wert (40 kcal) wäre nur bei deutlich mehr, sehr kleinen Portionen erreichbar.', 415, 105, 4, 21, 1, 'Früchte/Beeren 300 g = 135 kcal; Natürlicher Saft 500 ml = 230 kcal; Gelatine 15 g = 50 kcal; Wasser 50 ml = 0 kcal; Minzblätter (optional, nicht mitgerechnet); Summe = 415 kcal (÷4 Portionen ≈ 104 kcal/Portion)'),
  (148, 'Karottenmuffins', 'Desserts', 'Karottenmuffins sind ein nahrhaftes, leckeres Dessert, perfekt zum Frühstück oder als Snack. Geriebene Karotten bringen Süße und Vitamine, Haferflocken und Nüsse liefern Ballaststoffe und gesunde Fette. Einfach zuzubereiten und eine tolle Ergänzung für Ihre Ernährung. Guten Appetit!', '[{"name":"Geriebene Karotten","menge_anzeige":"150 g","gramm":150},{"name":"Haferflocken","menge_anzeige":"100 g","gramm":100},{"name":"Eier","menge_anzeige":"2 Stück","gramm":110},{"name":"Griechischer Joghurt","menge_anzeige":"120 ml","gramm":120},{"name":"Honig","menge_anzeige":"3 EL (60 g)","gramm":60},{"name":"Backpulver","menge_anzeige":"1 TL","gramm":4},{"name":"Zimt","menge_anzeige":"1 TL","gramm":3},{"name":"Vanilleextrakt","menge_anzeige":"1 TL (5 g)","gramm":5},{"name":"Nüsse (Walnüsse oder Mandeln, gehackt)","menge_anzeige":"1/4 Tasse (ca. 35 g)","gramm":35}]'::jsonb, '1. Den Ofen auf 180 °C vorheizen und ein Muffinblech einfetten oder mit Papierförmchen auslegen. 2. In einer großen Schüssel Haferflocken, geriebene Karotten, Backpulver, Zimt und Nüsse mischen. 3. In einer separaten Schüssel Eier, Joghurt, Honig und Vanilleextrakt glatt rühren. 4. Die nassen und trockenen Zutaten gut vermischen. 5. Den Teig in die Muffinförmchen füllen. 6. 20-25 Minuten backen, bis die Muffins goldbraun sind und den Zahnstocher-Test bestehen. 7. Die Muffins leicht abkühlen lassen, bevor sie serviert werden.', 8, 'Die Teigmenge (Haferflocken, Karotten, 2 Eier) ergibt ein klassisches Muffinrezept für ca. 8 Muffins; das errechnete kcal/Portion (143) liegt nah am alten Wert (130) und bestätigt die Portionenzahl.', 1144, 145, 5, 16, 6, 'Geriebene Karotten 150 g = 45 kcal; Haferflocken 100 g = 372 kcal; Eier 110 g = 171 kcal; Griechischer Joghurt 120 g = 138 kcal; Honig 60 g = 182 kcal; Backpulver 4 g = 2 kcal; Zimt 3 g = 6 kcal; Vanilleextrakt 5 g = 12 kcal; Nüsse (1/4 Tasse ≈ 35 g) = 216 kcal; Summe = 1144 kcal (÷8 Portionen ≈ 143 kcal/Portion)'),
  (149, 'Birnencrumble', 'Desserts', 'Birnencrumble ist ein duftendes und nahrhaftes Dessert, das die Süße von gebackenen Birnen mit der knusprigen Textur eines Hafer-Mandel-Toppings kombiniert. Dieses Dessert ist einfach zuzubereiten und ein großartiger Abschluss für jedes Mittag- oder Abendessen. Guten Appetit!', '[{"name":"Birnen","menge_anzeige":"4 Stück (ca. 600 g)","gramm":600},{"name":"Haferflocken","menge_anzeige":"100 g","gramm":100},{"name":"Mandelmehl","menge_anzeige":"50 g","gramm":50},{"name":"Honig","menge_anzeige":"3 EL (60 g)","gramm":60},{"name":"Kokosöl","menge_anzeige":"60 ml (ca. 55 g)","gramm":55},{"name":"Zimt","menge_anzeige":"1 TL","gramm":3},{"name":"Vanilleextrakt","menge_anzeige":"1 TL (5 g)","gramm":5}]'::jsonb, '1. Den Ofen auf 180 °C vorheizen und eine Auflaufform vorbereiten. 2. Die Birnen dünn schneiden und in die Form legen. 3. In einer Schüssel Haferflocken, Mandelmehl, Zimt und Vanilleextrakt mischen. 4. Honig und geschmolzenes Kokosöl hinzufügen und gründlich mischen. 5. Die Hafermischung über die Birnen streuen. 6. 30-35 Minuten backen, bis der Crumble goldbraun ist. 7. Vor dem Servieren leicht abkühlen lassen.', 8, '4 Birnen mit Hafer-Mandel-Topping füllen eine Auflaufform, die üblicherweise in 8 Portionen serviert wird; 210 kcal/Portion liegt im für Desserts üblichen Bereich, etwas über dem alten Wert (180 kcal).', 1678, 210, 3, 26, 11, 'Birnen 600 g = 342 kcal; Haferflocken 100 g = 372 kcal; Mandelmehl 50 g = 290 kcal; Honig 60 g = 182 kcal; Kokosöl 55 g = 474 kcal; Zimt 3 g = 6 kcal; Vanilleextrakt 5 g = 12 kcal; Summe = 1678 kcal (÷8 Portionen ≈ 210 kcal/Portion)'),
  (150, 'Mandelplätzchen', 'Desserts', 'Mandelplätzchen sind ein knuspriges und gesundes Dessert, das einfach zuzubereiten ist. Sie sind reich an Eiweiß und gesunden Fetten aus Mandelmehl, und Honig und Vanille verleihen ihnen ein süßes Aroma. Diese Plätzchen sind ein großartiger Snack oder eine Ergänzung zum Tee. Guten Appetit!', '[{"name":"Mandelmehl","menge_anzeige":"200 g (aus zubereitung_raw geschätzt)","gramm":200},{"name":"Ei","menge_anzeige":"1 Stück (aus zubereitung_raw geschätzt)","gramm":55},{"name":"Honig","menge_anzeige":"2 EL (40 g, geschätzt)","gramm":40},{"name":"Backpulver","menge_anzeige":"1 TL (geschätzt)","gramm":4},{"name":"Vanilleextrakt","menge_anzeige":"1 TL (5 g, geschätzt)","gramm":5}]'::jsonb, '1. Den Ofen auf 180 °C vorheizen und ein Backblech mit Backpapier auslegen. 2. In einer Schüssel Mandelmehl, Backpulver, Ei, Honig und Vanilleextrakt zu einem glatten Teig verrühren. 3. Kleine Plätzchen formen und auf das Backblech legen. 4. 10-12 Minuten backen, bis die Plätzchen goldbraun sind. 5. Vor dem Servieren abkühlen lassen.', 8, 'Die Teigmenge (200 g Mandelmehl u. a.) ergibt ca. 15-16 kleine Plätzchen; bei 8 Portionen (je ca. 2 Plätzchen) liegt der Wert (172 kcal) im Rahmen für einen Snack. Der Vergleich mit dem alten Wert (100 kcal) ist wegen der fehlerhaften Rohdaten nur eingeschränkt aussagekräftig.', 1379, 170, 6, 10, 13, 'Mandelmehl 200 g = 1158 kcal; Ei 55 g = 85 kcal; Honig 40 g = 122 kcal; Backpulver 4 g = 2 kcal; Vanilleextrakt 5 g = 12 kcal; Summe = 1379 kcal (÷8 Portionen ≈ 172 kcal/Portion)'),
  (151, 'Bananenchips', 'Desserts', 'Bananenchips sind ein leckerer und gesunder Snack, den Sie leicht zu Hause zubereiten können. Sie sind reich an Vitaminen und natürlicher Süße, und Zimt verleiht ein angenehmes Aroma. Diese Chips sind perfekt für einen leichten Snack zu jeder Zeit. Guten Appetit!', '[{"name":"Bananen","menge_anzeige":"3 Stück (ca. 360 g)","gramm":360},{"name":"Zitronensaft","menge_anzeige":"2 EL (30 ml)","gramm":30},{"name":"Zimt","menge_anzeige":"1/2 TL (ca. 1,3 g)","gramm":1}]'::jsonb, '1. Den Ofen auf 100 °C vorheizen und ein Backblech mit Backpapier auslegen. 2. Die Bananen in dünne Scheiben schneiden und auf das Backblech legen. 3. Mit Zitronensaft beträufeln und mit Zimt bestreuen. 4. Im Ofen 2-3 Stunden trocknen, dabei gelegentlich wenden, bis die Chips knusprig sind. 5. Vor dem Servieren abkühlen lassen.', 3, '331 kcal gesamt ÷ 3 Portionen ergibt 110 kcal/Portion, exakt der alte Wert — 3 Portionen (je 1 Banane) sind für diesen Snack realistisch.', 331, 110, 1, 29, 0, 'Bananen 360 g = 320 kcal; Zitronensaft 30 ml = 8 kcal; Zimt 1,3 g = 3 kcal; Summe = 331 kcal (÷3 Portionen ≈ 110 kcal/Portion)'),
  (152, 'Avocado-Bananen-Mousse', 'Desserts', 'Avocado-Bananen-Mousse ist ein cremiges und nahrhaftes Dessert, das die gesunden Fette der Avocado mit der natürlichen Süße der Banane kombiniert. Kakaopulver verleiht ihm einen schokoladigen Geschmack, was diese Mousse zu einer großartigen Wahl für ein gesundes Dessert macht. Guten Appetit!', '[{"name":"Avocado","menge_anzeige":"1 Stück (ca. 140 g Fruchtfleisch)","gramm":140},{"name":"Banane","menge_anzeige":"1 Stück (ca. 120 g)","gramm":120},{"name":"Kakaopulver","menge_anzeige":"2 EL (16 g)","gramm":16},{"name":"Honig oder Agavensirup","menge_anzeige":"1 EL (20 g)","gramm":20},{"name":"Vanilleextrakt","menge_anzeige":"1/2 TL (ca. 2,5 g)","gramm":3}]'::jsonb, '1. Avocado, Banane, Kakaopulver, Honig und Vanilleextrakt in einem Mixer glatt mixen. 2. Die Mousse in Gläser füllen und im Kühlschrank kühlen.', 3, '434 kcal gesamt ÷ 3 ergibt 145 kcal/Portion, nah am alten Wert (150 kcal); passt zu 3 kleinen Dessertgläsern aus 1 Avocado und 1 Banane.', 434, 145, 2, 21, 8, 'Avocado 140 g = 224 kcal; Banane 120 g = 107 kcal; Kakaopulver 16 g = 37 kcal; Honig 20 g = 61 kcal; Vanilleextrakt 2,5 g = 6 kcal; Summe = 434 kcal (÷3 Portionen ≈ 145 kcal/Portion)'),
  (153, 'Beerenparfait mit Joghurt', 'Desserts', 'Beerenparfait mit Joghurt ist ein leichtes und erfrischendes Dessert, das die cremige Textur von Joghurt, die Süße der Beeren und die Knusprigkeit von Granola kombiniert. Dieses Dessert ist reich an Eiweiß und Vitaminen, ideal für einen gesunden Snack oder ein Frühstück. Guten Appetit!', '[{"name":"Griechischer Joghurt","menge_anzeige":"200 g","gramm":200},{"name":"Frische Beeren (Heidelbeeren, Himbeeren, Erdbeeren)","menge_anzeige":"150 g","gramm":150},{"name":"Honig","menge_anzeige":"1 EL (20 g)","gramm":20},{"name":"Granola","menge_anzeige":"2 EL (20 g)","gramm":20}]'::jsonb, '1. In einem Glas oder einer Schüssel eine Schicht Joghurt einfüllen. 2. Eine Schicht Beeren hinzufügen und mit Honig beträufeln. 3. Die Schichten wiederholen und mit Granola abschließen. 4. Sofort servieren.', 2, '453 kcal gesamt ergeben bei 2 Portionen 226 kcal/Portion, am nächsten am alten Wert (200 kcal) und passend für ein Frühstücks-Parfait in 2 Gläsern.', 453, 225, 6, 25, 12, 'Griechischer Joghurt 200 g = 230 kcal; Frische Beeren 150 g = 68 kcal; Honig 20 g = 61 kcal; Granola 20 g = 94 kcal; Summe = 453 kcal (÷2 Portionen ≈ 226 kcal/Portion)'),
  (154, 'Zitronensorbet', 'Desserts', 'Zitronensorbet ist ein erfrischendes und leichtes Dessert, perfekt für heiße Sommertage. Sein leichter Geschmack und die natürliche Süße machen es zu einer ausgezeichneten Wahl für diejenigen, die eine gesunde Alternative zu Eis suchen. Guten Appetit!', '[{"name":"Zitronensaft (aus 4 Zitronen)","menge_anzeige":"4 Stück (ca. 180 ml Saft)","gramm":180},{"name":"Wasser","menge_anzeige":"240 ml","gramm":240},{"name":"Honig","menge_anzeige":"3 EL (60 g)","gramm":60}]'::jsonb, '1. Den Saft aus den Zitronen pressen. 2. In einem kleinen Topf Wasser und Honig erhitzen und rühren, bis der Honig vollständig aufgelöst ist. 3. Den Zitronensaft mit dem Honig-Wasser-Sirup mischen. 4. Die Mischung in einen Behälter gießen und einfrieren, dabei gelegentlich umrühren, bis sie vollständig gefroren ist. 5. Das Sorbet gekühlt servieren.', 3, '227 kcal gesamt ÷ 3 Portionen ergibt 76 kcal/Portion, nah am alten Wert (80 kcal); 4 Zitronen ergeben realistisch 3 kleine Sorbet-Portionen.', 227, 75, 0, 21, 0, 'Zitronensaft (aus 4 Zitronen) 180 ml = 45 kcal; Wasser 240 ml = 0 kcal; Honig 60 g = 182 kcal; Summe = 227 kcal (÷3 Portionen ≈ 76 kcal/Portion)'),
  (155, 'No-Bake-Käsekuchen mit Beeren', 'Desserts', 'No-Bake-Käsekuchen mit Beeren ist ein leichtes und erfrischendes Dessert, das nicht gebacken werden muss. Der Haferboden und die zarte Käsefüllung mit Beeren machen ihn perfekt für jeden Anlass. Dieser Käsekuchen ist einfach zuzubereiten und eine großartige Ergänzung für Ihren Tisch. Guten Appetit!', '[{"name":"Haferflocken (für den Boden)","menge_anzeige":"100 g","gramm":100},{"name":"Datteln (entsteint)","menge_anzeige":"75 g","gramm":75},{"name":"Kokosöl","menge_anzeige":"2 EL (20 g)","gramm":20},{"name":"Frischkäse (z. B. Philadelphia)","menge_anzeige":"400 g","gramm":400},{"name":"Griechischer Joghurt","menge_anzeige":"200 g","gramm":200},{"name":"Honig oder Agavensirup","menge_anzeige":"3 EL (60 g)","gramm":60},{"name":"Vanilleextrakt","menge_anzeige":"1 TL (5 g)","gramm":5},{"name":"Gelatine","menge_anzeige":"15 g","gramm":15},{"name":"Wasser","menge_anzeige":"50 ml","gramm":50},{"name":"Frische Beeren (Topping)","menge_anzeige":"200 g","gramm":200}]'::jsonb, '1. Haferflocken und Datteln im Mixer mahlen. 2. Geschmolzenes Kokosöl einrühren. 3. In eine Kuchenform drücken und 20 Minuten kühlen. 4. Füllung vorbereiten: Gelatine in Wasser einweichen (10 Minuten). 5. Frischkäse, Joghurt, Honig und Vanille glatt schlagen. 6. Gelatine schmelzen (nicht kochen) und einrühren. 7. Käsekuchen zusammensetzen: Käsemischung auf den Boden gießen und glatt streichen, mindestens 4 Stunden oder über Nacht kühlen. 8. Topping: Vor dem Servieren mit frischen Beeren garnieren.', 8, 'Die Gesamtmasse (ca. 1,1 kg: Boden, Füllung, Topping) entspricht einem klassischen Kuchen für 8 Stücke; 288 kcal/Portion liegt über dem alten Wert (210 kcal), ist aber für einen cremigen Frischkäse-Kuchen mit Kokosöl-Boden plausibel.', 2305, 290, 7, 25, 18, 'Haferflocken 100 g = 372 kcal; Datteln 75 g = 212 kcal; Kokosöl 20 g = 172 kcal; Frischkäse 400 g = 984 kcal; Griechischer Joghurt 200 g = 230 kcal; Honig 60 g = 182 kcal; Vanilleextrakt 5 g = 12 kcal; Gelatine 15 g = 50 kcal; Wasser 50 ml = 0 kcal; Frische Beeren 200 g = 90 kcal; Summe = 2305 kcal (÷8 Portionen ≈ 288 kcal/Portion)'),
  (156, 'Kokosmakronen', 'Desserts', 'Kokosmakronen sind ein leichtes Gebäck aus nur wenigen Zutaten: Kokosraspeln, Eiweiß und Honig. Außen knusprig, innen zart — perfekt zur Teezeit. Guten Appetit!', '[{"name":"Kokosraspeln","menge_anzeige":"160 g","gramm":160},{"name":"Eiweiß","menge_anzeige":"3 Stück (ca. 100 g)","gramm":100},{"name":"Honig oder Agavensirup","menge_anzeige":"63 ml (ca. 90 g)","gramm":90},{"name":"Vanilleextrakt","menge_anzeige":"1 TL","gramm":5},{"name":"Salz","menge_anzeige":"1 Prise","gramm":null}]'::jsonb, '1. Den Ofen auf 160 °C vorheizen und ein Backblech mit Backpapier auslegen. 2. Eiweiß mit einer Prise Salz steif schlagen, bis sich weiche Spitzen bilden. 3. Nach und nach Honig und Vanilleextrakt hinzufügen und weiterschlagen, bis die Masse steif ist. 4. Die Kokosraspeln vorsichtig unterheben. 5. Kleine Kugeln formen und auf das Backblech setzen. 6. 15–20 Minuten goldgelb backen und auskühlen lassen.', 20, 'Die Teigmenge ergibt ca. 20 Makronen; 1 Makrone = 1 Portion (passt zum alten Wert von 70 kcal pro Stück).', 1395, 70, 1, 4, 5, 'Kokosraspeln 160 g = 1056 kcal; Eiweiß 100 g = 52 kcal; Honig 90 g = 274 kcal; Vanilleextrakt 5 g = 13 kcal; Summe = 1395 kcal / 20 Stück = 70 kcal'),
  (157, 'Bananeneis mit Beeren', 'Desserts', 'Dieses gesunde Dessert besteht aus natürlichen Zutaten. Bananen sorgen für Süße und Cremigkeit, Beeren für frischen Geschmack und Antioxidantien. Das Rezept lässt sich leicht mit Nüssen, Samen oder anderen Früchten schmücken. Guten Appetit!', '[{"name":"Bananen","menge_anzeige":"3 Stück","gramm":360},{"name":"Frische oder gefrorene Beeren (Erdbeeren, Blaubeeren, Himbeeren, etc.)","menge_anzeige":"1/2 Tasse (120 ml)","gramm":70},{"name":"Ungesüßte Mandel- oder Kokosmilch","menge_anzeige":"1/4 Tasse (60 ml)","gramm":60},{"name":"Vanilleextrakt","menge_anzeige":"1 TL","gramm":4},{"name":"Honig oder Ahornsirup","menge_anzeige":"1 EL","gramm":20},{"name":"Minzblätter","menge_anzeige":"nach Geschmack (zum Garnieren)","gramm":null}]'::jsonb, '1. Bananen schälen, in Stücke schneiden und 2–3 Stunden einfrieren.
2. Gefrorene Bananen, Mandel- oder Kokosmilch und Vanilleextrakt im Mixer glattmixen. Bei Bedarf mehr Milch hinzufügen.
3. Beeren vorsichtig unterrühren.
4. Nach Belieben Honig oder Ahornsirup hinzufügen und erneut kurz mixen.
5. Bananeneis in Schalen füllen, nach Belieben mit Beeren und Minze garnieren. Sofort servieren oder für 30 Minuten einfrieren.', 3, '433 kcal Gesamtmenge ÷ 3 ≈ 144 kcal/Portion liegt nah am alten kcal_alt-Wert (150) und passt zur Dessert-Richtgröße von 100–350 kcal/Portion.', 433, 145, 2, 35, 1, 'Bananen 360 g (3 Stück à 120 g) = 320 kcal; Beeren 70 g = 32 kcal; Mandel-/Kokosmilch 60 g = 8 kcal; Vanilleextrakt 4 g = 12 kcal; Honig 20 g = 61 kcal; Minzblätter (Garnitur, nach Geschmack) = 0 kcal; Summe = 433 kcal (Eiweiß ≈ 4,8 g, Fett ≈ 2,0 g, KH ≈ 105,6 g)')
on conflict (id) do update set
  title = excluded.title,
  category = excluded.category,
  description = excluded.description,
  ingredients = excluded.ingredients,
  instructions = excluded.instructions,
  servings = excluded.servings,
  servings_note = excluded.servings_note,
  kcal_total = excluded.kcal_total,
  kcal_per_serving = excluded.kcal_per_serving,
  protein_per_serving_g = excluded.protein_per_serving_g,
  carbs_per_serving_g = excluded.carbs_per_serving_g,
  fat_per_serving_g = excluded.fat_per_serving_g,
  nutrition_note = excluded.nutrition_note,
  updated_at = now();

-- Import-Rezepte sind redaktionell geprüft → direkt veröffentlicht
update public.recipes set status = 'published' where status = 'draft' and id <= 157;

-- Identity-Sequenz hinter die Import-IDs setzen (Admin-Editor vergibt neue IDs automatisch)
select setval(pg_get_serial_sequence('public.recipes', 'id'), (select max(id) from public.recipes));
